import { NextRequest, NextResponse } from 'next/server'
import { supabaseAdmin } from '@/lib/supabase'

export async function GET() {
  try {
    // Get total counts
    const { count: totalAlerts } = await supabaseAdmin
      .from('admin_alerts')
      .select('*', { count: 'exact', head: true })

    const { count: activeAlerts } = await supabaseAdmin
      .from('admin_alerts')
      .select('*', { count: 'exact', head: true })
      .eq('status', 'active')

    const { count: inactiveAlerts } = await supabaseAdmin
      .from('admin_alerts')
      .select('*', { count: 'exact', head: true })
      .eq('status', 'inactive')

    const { count: draftAlerts } = await supabaseAdmin
      .from('admin_alerts')
      .select('*', { count: 'exact', head: true })
      .eq('status', 'draft')

    const { count: criticalAlerts } = await supabaseAdmin
      .from('admin_alerts')
      .select('*', { count: 'exact', head: true })
      .eq('severity', 'critical')
      .eq('status', 'active')

    const { count: highPriorityAlerts } = await supabaseAdmin
      .from('admin_alerts')
      .select('*', { count: 'exact', head: true })
      .gte('priority', 8)
      .eq('status', 'active')

    // Get alerts by type
    const { data: alertsByType } = await supabaseAdmin
      .from('admin_alerts')
      .select('alert_type')
      .eq('status', 'active')

    type AlertTypeRow = { alert_type: string | null }
    const typeCounts = (alertsByType as AlertTypeRow[] | null)?.reduce<Record<string, number>>((acc, alert) => {
      const key = alert.alert_type || 'unknown'
      acc[key] = (acc[key] || 0) + 1
      return acc
    }, {}) || {}

    const alertsByTypeArray = Object.entries(typeCounts).map(([type, count]) => ({
      type,
      count: count as number
    }))

    // Get alerts by severity
    const { data: alertsBySeverity } = await supabaseAdmin
      .from('admin_alerts')
      .select('severity')
      .eq('status', 'active')

    type SeverityRow = { severity: string | null }
    const severityCounts = (alertsBySeverity as SeverityRow[] | null)?.reduce<Record<string, number>>((acc, alert) => {
      const key = alert.severity || 'unknown'
      acc[key] = (acc[key] || 0) + 1
      return acc
    }, {}) || {}

    const alertsBySeverityArray = Object.entries(severityCounts).map(([severity, count]) => ({
      severity,
      count: count as number
    }))

    // Get recent alerts
    const { data: recentAlerts } = await supabaseAdmin
      .from('admin_alerts')
      .select(`
        *,
        created_by_user:users!admin_alerts_created_by_fkey(first_name, last_name, email)
      `)
      .order('created_at', { ascending: false })
      .limit(5)

    const stats = {
      totalAlerts: totalAlerts || 0,
      activeAlerts: activeAlerts || 0,
      inactiveAlerts: inactiveAlerts || 0,
      draftAlerts: draftAlerts || 0,
      criticalAlerts: criticalAlerts || 0,
      highPriorityAlerts: highPriorityAlerts || 0,
      alertsByType: alertsByTypeArray,
      alertsBySeverity: alertsBySeverityArray,
      recentAlerts: recentAlerts || []
    }

    return NextResponse.json({ stats })
  } catch (error) {
    console.error('Error in alerts stats GET:', error)
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseAdmin } from '@/lib/supabase'

export async function GET() {
  try {
    const supabase = supabaseAdmin

    // Get total users count
    const { count: totalUsers, error: totalUsersError } = await supabase
      .from('users')
      .select('*', { count: 'exact', head: true })

    if (totalUsersError) {
      console.error('Error fetching total users:', totalUsersError)
      return NextResponse.json({ error: 'Failed to fetch total users' }, { status: 500 })
    }

    // Get active users (users with recent activity - last 30 days)
    const thirtyDaysAgo = new Date()
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30)

    const { count: activeUsers, error: activeUsersError } = await supabase
      .from('users')
      .select('*', { count: 'exact', head: true })
      .gte('updated_at', thirtyDaysAgo.toISOString())

    if (activeUsersError) {
      console.error('Error fetching active users:', activeUsersError)
      return NextResponse.json({ error: 'Failed to fetch active users' }, { status: 500 })
    }

    // Get total projects count
    const { count: totalProjects, error: totalProjectsError } = await supabase
      .from('audit_projects')
      .select('*', { count: 'exact', head: true })

    if (totalProjectsError) {
      console.error('Error fetching total projects:', totalProjectsError)
      return NextResponse.json({ error: 'Failed to fetch total projects' }, { status: 500 })
    }

    // Get total audits count
    const { count: totalAudits, error: totalAuditsError } = await supabase
      .from('audit_projects')
      .select('*', { count: 'exact', head: true })
      .eq('status', 'completed')

    if (totalAuditsError) {
      console.error('Error fetching total audits:', totalAuditsError)
      return NextResponse.json({ error: 'Failed to fetch total audits' }, { status: 500 })
    }

    // Get critical issues (projects with low scores)
    const { count: criticalIssues, error: criticalIssuesError } = await supabase
      .from('audit_projects')
      .select('*', { count: 'exact', head: true })
      .lt('score', 50)

    if (criticalIssuesError) {
      console.error('Error fetching critical issues:', criticalIssuesError)
      return NextResponse.json({ error: 'Failed to fetch critical issues' }, { status: 500 })
    }

    // Get resolved issues (projects with high scores)
    const { count: resolvedIssues, error: resolvedIssuesError } = await supabase
      .from('audit_projects')
      .select('*', { count: 'exact', head: true })
      .gte('score', 80)

    if (resolvedIssuesError) {
      console.error('Error fetching resolved issues:', resolvedIssuesError)
      return NextResponse.json({ error: 'Failed to fetch resolved issues' }, { status: 500 })
    }

    // Get total scraped pages count
    const { count: totalScrapedPages, error: scrapedPagesError } = await supabase
      .from('scraped_pages')
      .select('*', { count: 'exact', head: true })

    if (scrapedPagesError) {
      console.error('Error fetching scraped pages:', scrapedPagesError)
      return NextResponse.json({ error: 'Failed to fetch scraped pages' }, { status: 500 })
    }

    // Get pages with social meta tags
    const { count: pagesWithSocialMeta, error: socialMetaError } = await supabase
      .from('scraped_pages')
      .select('*', { count: 'exact', head: true })
      .gt('social_meta_tags_count', 0)

    if (socialMetaError) {
      console.error('Error fetching pages with social meta:', socialMetaError)
    }

    // Get pages with CMS detection
    const { count: pagesWithCMS, error: cmsError } = await supabase
      .from('scraped_pages')
      .select('*', { count: 'exact', head: true })
      .not('cms_type', 'is', null)

    if (cmsError) {
      console.error('Error fetching pages with CMS:', cmsError)
    }

    // Get ticket statistics
    const { count: totalTickets, error: totalTicketsError } = await supabase
      .from('tickets')
      .select('*', { count: 'exact', head: true })

    if (totalTicketsError) {
      console.error('Error fetching total tickets:', totalTicketsError)
    }

    // Get open tickets
    const { count: openTickets, error: openTicketsError } = await supabase
      .from('tickets')
      .select('*', { count: 'exact', head: true })
      .eq('status', 'open')

    if (openTicketsError) {
      console.error('Error fetching open tickets:', openTicketsError)
    }

    // Get in progress tickets
    const { count: inProgressTickets, error: inProgressTicketsError } = await supabase
      .from('tickets')
      .select('*', { count: 'exact', head: true })
      .eq('status', 'in_progress')

    if (inProgressTicketsError) {
      console.error('Error fetching in progress tickets:', inProgressTicketsError)
    }

    // Get resolved tickets
    const { count: resolvedTickets, error: resolvedTicketsError } = await supabase
      .from('tickets')
      .select('*', { count: 'exact', head: true })
      .eq('status', 'resolved')

    if (resolvedTicketsError) {
      console.error('Error fetching resolved tickets:', resolvedTicketsError)
    }

    // Get high priority tickets
    const { count: highPriorityTickets, error: highPriorityTicketsError } = await supabase
      .from('tickets')
      .select('*', { count: 'exact', head: true })
      .in('priority', ['high', 'urgent'])

    if (highPriorityTicketsError) {
      console.error('Error fetching high priority tickets:', highPriorityTicketsError)
    }

    // Calculate system uptime (mock calculation - in real scenario, this would come from monitoring)
    const systemUptime = '99.9%'

    // Calculate average response time (mock calculation)
    const responseTime = '120ms'

    const stats = {
      totalUsers: totalUsers || 0,
      activeUsers: activeUsers || 0,
      totalProjects: totalProjects || 0,
      totalAudits: totalAudits || 0,
      criticalIssues: criticalIssues || 0,
      resolvedIssues: resolvedIssues || 0,
      totalScrapedPages: totalScrapedPages || 0,
      pagesWithSocialMeta: pagesWithSocialMeta || 0,
      pagesWithCMS: pagesWithCMS || 0,
      totalTickets: totalTickets || 0,
      openTickets: openTickets || 0,
      inProgressTickets: inProgressTickets || 0,
      resolvedTickets: resolvedTickets || 0,
      highPriorityTickets: highPriorityTickets || 0,
      systemUptime,
      responseTime
    }

    return NextResponse.json(stats)
  } catch (error) {
    console.error('Error in overview stats API:', error)
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseAdmin } from '@/lib/supabase'

export async function GET(request: NextRequest) {
  try {
    const supabase = supabaseAdmin
    const { searchParams } = new URL(request.url)
    const limit = parseInt(searchParams.get('limit') || '10')
    const offset = parseInt(searchParams.get('offset') || '0')

    // Get payment history with user and plan details
    const { data: payments, error } = await supabase
      .from('payments')
      .select(`
        id,
        amount,
        currency,
        plan_name,
        plan_type,
        billing_cycle,
        payment_status,
        payment_method,
        payment_date,
        created_at,
        receipt_number,
        user_id,
        users!inner(email, first_name, last_name)
      `)
      .order('payment_date', { ascending: false })
      .range(offset, offset + limit - 1)

    if (error) {
      console.error('Error fetching payment history:', error)
      return NextResponse.json({ error: 'Failed to fetch payment history' }, { status: 500 })
    }

    // Get plan statistics
    const { data: planStats, error: planStatsError } = await supabase
      .from('payments')
      .select(`
        plan_name,
        plan_type,
        amount,
        payment_status
      `)
      .eq('payment_status', 'completed')

    if (planStatsError) {
      console.error('Error fetching plan stats:', planStatsError)
      return NextResponse.json({ error: 'Failed to fetch plan statistics' }, { status: 500 })
    }

    // Calculate plan statistics
    const planStatsMap = new Map()
    planStats?.forEach(payment => {
      const key = `${payment.plan_name}-${payment.plan_type}`
      if (!planStatsMap.has(key)) {
        planStatsMap.set(key, {
          name: payment.plan_name,
          type: payment.plan_type,
          users: 0,
          revenue: 0,
          status: 'active'
        })
      }
      const plan = planStatsMap.get(key)
      plan.users += 1
      plan.revenue += Number(payment.amount)
    })

    const planStatistics = Array.from(planStatsMap.values())

    // Fetch auth user data for users who might have Google auth
    const userIds = payments?.map(p => p.user_id).filter(Boolean) || [];
    type AuthUserData = {
      raw_user_meta_data: Record<string, any>;
      app_metadata: Record<string, any>;
    };
    const authUserDataMap = new Map<string, AuthUserData>();
    
    // Fetch auth data for all unique user IDs
    if (userIds.length > 0) {
      try {
        const uniqueUserIds = [...new Set(userIds)];
        await Promise.all(
          uniqueUserIds.map(async (userId) => {
            try {
              const { data: authUser, error: authError } = await supabase.auth.admin.getUserById(userId);
              if (!authError && authUser?.user) {
                authUserDataMap.set(userId, {
                  raw_user_meta_data: authUser.user.user_metadata || {},
                  app_metadata: authUser.user.app_metadata || {}
                });
              }
            } catch (err) {
              // Silently fail for individual users
              console.warn(`Failed to fetch auth data for user ${userId}:`, err);
            }
          })
        );
      } catch (err) {
        // Silently fail - we'll just use database data
        console.warn('Failed to fetch some auth user data:', err);
      }
    }

    // Format payment history
    const formattedPayments = payments?.map(payment => {
      // Handle the case where users might be an array or single object
      const user = Array.isArray(payment.users) ? payment.users[0] : payment.users

      // Try to get Google auth data
      const authData = authUserDataMap.get(payment.user_id);
      const googleFirstName = authData?.raw_user_meta_data?.first_name ||
        authData?.raw_user_meta_data?.full_name?.split(' ')[0];
      const googleLastName = authData?.raw_user_meta_data?.last_name ||
        authData?.raw_user_meta_data?.full_name?.split(' ').slice(1).join(' ');
      const googleFullName = authData?.raw_user_meta_data?.full_name ||
        authData?.raw_user_meta_data?.name;

      // Determine display name with priority: Google > Database > Email
      let userName = 'Unknown User';
      if (googleFullName) {
        userName = googleFullName;
      } else if (googleFirstName && googleLastName) {
        userName = `${googleFirstName} ${googleLastName}`;
      } else if (user?.first_name && user?.last_name) {
        userName = `${user.first_name} ${user.last_name}`;
      } else if (googleFirstName || user?.first_name) {
        userName = googleFirstName || user?.first_name || '';
      } else if (googleLastName || user?.last_name) {
        userName = googleLastName || user?.last_name || '';
      } else if (user?.email) {
        userName = user.email.split('@')[0];
      }

      return {
        id: payment.id,
        user: user?.email || 'Unknown',
        userName: userName,
        plan: payment.plan_name,
        amount: Number(payment.amount),
        currency: payment.currency || 'INR',
        status: payment.payment_status,
        date: payment.payment_date ? new Date(payment.payment_date).toISOString().split('T')[0] : 'N/A',
        paymentMethod: payment.payment_method,
        receiptNumber: payment.receipt_number
      }
    }) || []

    return NextResponse.json({
      payments: formattedPayments,
      planStatistics
    })
  } catch (error) {
    console.error('Error in payment history API:', error)
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { supabaseAdmin } from '@/lib/supabase'

export async function GET() {
  try {
    const supabase = supabaseAdmin

    // Test basic connection
    const { data, error } = await supabase
      .from('payments')
      .select('count', { count: 'exact', head: true })

    if (error) {
      console.error('Database connection error:', error)
      return NextResponse.json({
        success: false,
        error: error.message,
        details: error
      }, { status: 500 })
    }

    return NextResponse.json({
      success: true,
      message: 'Database connection successful',
      paymentsCount: data || 0
    })
  } catch (error) {
    console.error('Test connection error:', error)
    return NextResponse.json({
      success: false,
      error: 'Connection test failed',
      details: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

interface SupabaseError {
  message: string;
  code?: string;
  details?: string;
  hint?: string;
}

// GET /api/plans/[id] - Fetch a specific plan
export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const { data: plan, error } = await supabase
      .from('plans')
      .select('*')
      .eq('id', id)
      .single();

    if (error) {
      console.error('Error fetching plan:', error);
      return NextResponse.json(
        { error: 'Plan not found' },
        { status: 404 }
      );
    }

    return NextResponse.json({ plan });

  } catch (error) {
    console.error('Unexpected error fetching plan:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

// PUT /api/plans/[id] - Update a plan
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const body = await request.json();

    // Validate plan_type if provided
    if (body.plan_type && !['Starter', 'Growth', 'Scale'].includes(body.plan_type)) {
      return NextResponse.json(
        { error: 'Invalid plan_type. Must be Starter, Growth, or Scale' },
        { status: 400 }
      );
    }

    // Filter out empty razorpay_plan_id to avoid unique constraint violations
    const updateData = {
      ...body,
      updated_at: new Date().toISOString()
    };

    // Remove razorpay_plan_id if it's empty to avoid unique constraint issues
    if (updateData.razorpay_plan_id === '' || updateData.razorpay_plan_id === null) {
      delete updateData.razorpay_plan_id;
    }

    let { data, error } = await supabase
      .from('plans')
      .update(updateData)
      .eq('id', id)
      .select();

    // If error is due to missing image_scan_credits column, retry without it
    if (error && error.message?.includes('image_scan_credits') && error.message?.includes('column')) {
      console.warn('⚠️ image_scan_credits column not found. Retrying without it. Please run: database/add_image_scan_credits_to_plans.sql');
      const { image_scan_credits: _image_scan_credits, ...updateDataWithoutCredits } = updateData;
      const retryResult = await supabase
        .from('plans')
        .update(updateDataWithoutCredits)
        .eq('id', id)
        .select();

      if (retryResult.error) {
        error = retryResult.error;
      } else {
        data = retryResult.data;
        error = null;
      }
    }

    // Check if any rows were affected
    if (!data || data.length === 0) {
      console.error('No rows affected for plan ID:', id);
      console.error('Update data:', updateData);
      return NextResponse.json(
        { error: `Plan not found with ID: ${id}` },
        { status: 404 }
      );
    }

    // Return the first (and should be only) updated plan
    const updatedPlan = data[0];

    if (error) {
      console.error('Error updating plan:', error);
      const supabaseError = error as SupabaseError;
      console.error('Error details:', {
        message: supabaseError.message,
        code: supabaseError.code,
        details: supabaseError.details,
        hint: supabaseError.hint
      });

      // Handle specific error cases
      if (supabaseError.code === '23505') {
        return NextResponse.json(
          { error: 'A plan with this Razorpay ID already exists. Please use a different Razorpay ID or leave it empty.' },
          { status: 400 }
        );
      }

      return NextResponse.json(
        { error: `Failed to update plan: ${supabaseError.message || 'Unknown error'}` },
        { status: 500 }
      );
    }

    return NextResponse.json({
      plan: updatedPlan,
      message: 'Plan updated successfully'
    });

  } catch (error) {
    console.error('Unexpected error updating plan:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

// DELETE /api/plans/[id] - Delete a plan (soft delete)
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const { data, error } = await supabase
      .from('plans')
      .update({
        is_active: false,
        updated_at: new Date().toISOString()
      })
      .eq('id', id)
      .select();

    // Check if any rows were affected
    if (!data || data.length === 0) {
      return NextResponse.json(
        { error: 'Plan not found' },
        { status: 404 }
      );
    }

    if (error) {
      console.error('Error deleting plan:', error);
      return NextResponse.json(
        { error: 'Failed to delete plan' },
        { status: 500 }
      );
    }

    return NextResponse.json({
      message: 'Plan deleted successfully'
    });

  } catch (error) {
    console.error('Unexpected error deleting plan:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

// Create Supabase client with proper configuration
const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
const supabase = createClient(supabaseUrl, supabaseAnonKey);

// GET /api/plans - Fetch all active plans for public use
export async function GET() {
  try {
    const now = new Date().toISOString();

    const { data: plans, error } = await supabase
      .from('plans')
      .select('*')
      .eq('is_active', true)
      .or(`start_date.is.null,start_date.lte.${now}`)
      .or(`end_date.is.null,end_date.gte.${now}`)
      .order('sort_order', { ascending: true })
      .order('created_at', { ascending: true });

    if (error) {
      console.error('Error fetching plans:', error);
      return NextResponse.json(
        { error: 'Failed to fetch plans' },
        { status: 500 }
      );
    }

    // Transform plans to match frontend expectations
    const transformedPlans = (plans || []).map(plan => ({
      id: plan.id,
      name: plan.name,
      plan_type: plan.plan_type,
      description: plan.description,
      price: plan.price,
      currency: plan.currency,
      billing_cycle: plan.billing_cycle,
      max_projects: plan.max_projects,
      can_use_features: plan.can_use_features,
      features: plan.features,
      is_active: plan.is_active,
      razorpay_plan_id: plan.razorpay_plan_id,
      subscription_id: plan.subscription_id,
      color: plan.color,
      is_popular: plan.is_popular,
      limits: plan.limits,
      created_at: plan.created_at,
      updated_at: plan.updated_at,
      sort_order: plan.sort_order
    }));

    return NextResponse.json({
      plans: transformedPlans,
      total: transformedPlans.length
    });

  } catch (error) {
    console.error('Unexpected error fetching plans:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

// POST /api/plans - Create a new plan
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();

    // Validate required fields
    const {
      name,
      plan_type,
      price,
      currency,
      billing_cycle,
      features,
      can_use_features,
      max_projects,
      color,
      is_popular,
      limits,
      sort_order,
      razorpay_plan_id,
      subscription_id
    } = body;

    if (!name || !plan_type) {
      return NextResponse.json(
        { error: 'Name and plan_type are required' },
        { status: 400 }
      );
    }

    // Validate plan_type
    if (!['Starter', 'Growth', 'Scale'].includes(plan_type)) {
      return NextResponse.json(
        { error: 'Invalid plan_type. Must be Starter, Growth, or Scale' },
        { status: 400 }
      );
    }

    // Validate billing_cycle
    if (billing_cycle && !['monthly', 'yearly'].includes(billing_cycle)) {
      return NextResponse.json(
        { error: 'Invalid billing_cycle. Must be monthly or yearly' },
        { status: 400 }
      );
    }

    const planData: Record<string, unknown> = {
      name,
      description: body.description || '',
      plan_type,
      price: price || 0,
      currency: currency || 'INR',
      billing_cycle: billing_cycle || 'monthly',
      features: features || [],
      can_use_features: can_use_features || [],
      max_projects: max_projects !== undefined ? max_projects : 1,
      is_active: body.is_active !== undefined ? body.is_active : true,
      sort_order: sort_order || 0,
      razorpay_plan_id: razorpay_plan_id && razorpay_plan_id.trim() !== '' ? razorpay_plan_id : null,
      subscription_id: subscription_id && subscription_id.trim() !== '' ? subscription_id : null,
      color: color || 'gray',
      is_popular: is_popular || false,
      limits: limits || {}
    };

    // Only include image_scan_credits if the column exists in the database
    // If the column doesn't exist, run: database/add_image_scan_credits_to_plans.sql
    if (body.image_scan_credits !== undefined) {
      planData.image_scan_credits = body.image_scan_credits;
    }

    let { data, error } = await supabase
      .from('plans')
      .insert([planData])
      .select()
      .single();

    // If error is due to missing image_scan_credits column, retry without it
    if (error && error.message?.includes('image_scan_credits') && error.message?.includes('column')) {
      console.warn('⚠️ image_scan_credits column not found. Retrying without it. Please run: database/add_image_scan_credits_to_plans.sql');
      const { image_scan_credits: _unused, ...planDataWithoutCredits } = planData;
      const retryResult = await supabase
        .from('plans')
        .insert([planDataWithoutCredits])
        .select()
        .single();

      if (retryResult.error) {
        console.error('Error creating plan:', retryResult.error);
        return NextResponse.json(
          { error: 'Failed to create plan', details: retryResult.error.message },
          { status: 500 }
        );
      }

      data = retryResult.data;
      error = null;
    } else if (error) {
      console.error('Error creating plan:', error);
      return NextResponse.json(
        { error: 'Failed to create plan', details: error.message },
        { status: 500 }
      );
    }

    return NextResponse.json({
      plan: data,
      message: 'Plan created successfully'
    }, { status: 201 });

  } catch (error) {
    console.error('Unexpected error creating plan:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

