'use client'

import React, { useState, useMemo, useEffect } from 'react'
import Image from 'next/image'
import { AuditProject } from '@/types/audit'
import { ScrapedPage } from '../analysis-tab/types'
import { useSupabase } from '@/contexts/SupabaseContext'
import { supabase } from '@/lib/supabase-client'
import { useUserPlan } from '@/hooks/useUserPlan'

// Override the ScrapedPage type to accept any performance_analysis type
interface ScrapedPageOverride extends Omit<ScrapedPage, 'performance_analysis'> {
  performance_analysis?: Record<string, unknown>
}

interface OriginalScrapingData {
  pages?: ScrapedPageOverride[]
}

interface ImagesSectionProps {
  project: AuditProject
  scrapedPages: ScrapedPageOverride[]
  originalScrapingData?: OriginalScrapingData
}

interface ImageData {
  url?: string
  src?: string
  alt?: string | null
  title?: string | null
  width?: number
  height?: number
  type?: string
  size?: number
  page_url?: string
  altText?: string
  alt_text?: string
  titleText?: string
  title_text?: string
  fullTag?: string
  isBroken?: boolean
  loadError?: boolean
  extra_metadata?: {
    id?: string
    scraped_page_id?: string
    audit_project_id?: string
    size_bytes?: number | null
    scan_results?: any
    open_web_ninja_data?: any
    created_at?: string
    updated_at?: string
  }
}

export default function ImagesSection({ project, scrapedPages, originalScrapingData }: ImagesSectionProps) {
  const { getScrapedImages } = useSupabase()
  const { hasFeature, planInfo } = useUserPlan()
  const [currentPage, setCurrentPage] = useState(1)
  const [itemsPerPage] = useState(20) // Reduced from 40 to 20 for better performance
  const [isProcessing, setIsProcessing] = useState(false)
  const [isLoading, setIsLoading] = useState(true)
  const [selectedImage, setSelectedImage] = useState<ImageData | null>(null)
  const [showModal, setShowModal] = useState(false)
  const [scrapedImagesData, setScrapedImagesData] = useState<any[]>([])
  const [scanningImages, setScanningImages] = useState<Set<string>>(new Set())
  const [showActionsTooltip, setShowActionsTooltip] = useState(false)
  const [scanResults, setScanResults] = useState<Record<string, any>>({})
  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set())
  
  // Check if user has image scan feature
  const hasImageScanFeature = hasFeature('Image_scane')
  
  // Filter states
  const [selectedImageType, setSelectedImageType] = useState<string>('all')
  const [searchQuery, setSearchQuery] = useState('')

  

  const getImageType = (url: string) => {
    const extension = url.split('.').pop()?.toLowerCase()
    switch (extension) {
      case 'jpg':
      case 'jpeg':
        return 'JPEG'
      case 'png':
        return 'PNG'
      case 'gif':
        return 'GIF'
      case 'webp':
        return 'WebP'
      case 'svg':
        return 'SVG'
      case 'bmp':
        return 'BMP'
      case 'ico':
        return 'ICO'
      case 'tiff':
        return 'TIFF'
      default:
        return 'Unknown'
    }
  }


  // Helper function to parse fullTag HTML and extract image attributes
  const parseImageFromFullTag = (fullTag: string) => {
    try {
      // Create a temporary DOM element to parse the fullTag
      const tempDiv = document.createElement('div')
      tempDiv.innerHTML = fullTag
      const imgElement = tempDiv.querySelector('img')
      
      if (!imgElement) {
        return null
      }
      
      // Extract all relevant attributes
      const src = imgElement.src || imgElement.getAttribute('src') || ''
      const alt = imgElement.alt || imgElement.getAttribute('alt') || null
      const title = imgElement.title || imgElement.getAttribute('title') || null
      const width = imgElement.width || imgElement.getAttribute('width') || null
      const height = imgElement.height || imgElement.getAttribute('height') || null
      const className = imgElement.className || imgElement.getAttribute('class') || null
      const loading = imgElement.loading || imgElement.getAttribute('loading') || null
      const decoding = imgElement.getAttribute('decoding') || null
      
      return {
        src,
        alt,
        title,
        width: width ? parseInt(width.toString()) : null,
        height: height ? parseInt(height.toString()) : null,
        className,
        loading,
        decoding
      }
    } catch (error) {
      console.warn('❌ Error parsing fullTag:', error)
      return null
    }
  }

  // Fetch images from scraped_images table
  useEffect(() => {
    const fetchImages = async () => {
      if (!project?.id) return
      
      setIsLoading(true)
      try {
        const { data, error } = await getScrapedImages(project.id)
        
        if (error) {
          console.error('❌ Error fetching scraped images:', error)
          // Fall back to parsing from scraped_pages if database fetch fails
          setScrapedImagesData([])
        } else {
          setScrapedImagesData(data || [])
          
          // Load existing scan results from database into state
          if (data && data.length > 0) {
            const existingResults: Record<string, any> = {}
            data.forEach((img: any) => {
              if (img.open_web_ninja_data) {
                // Use the same key generation logic as in rendering
                // Priority: img.id (database ID), then original_url, then empty string
                const uniqueKey = img.id || img.original_url || ''
                if (uniqueKey) {
                  existingResults[uniqueKey] = img.open_web_ninja_data
                }
              }
            })
            
            if (Object.keys(existingResults).length > 0) {
              setScanResults(prev => ({
                ...prev,
                ...existingResults
              }))
              console.log('✅ Loaded existing scan results from database:', Object.keys(existingResults).length, Object.keys(existingResults))
            }
          }
        }
      } catch (err) {
        console.error('❌ Exception fetching scraped images:', err)
        setScrapedImagesData([])
      } finally {
        setIsLoading(false)
      }
    }

    fetchImages()
  }, [project?.id, getScrapedImages])

  // Convert scraped_images data to ImageData format
  const images = useMemo(() => {
    setIsProcessing(true)
    const allImages: ImageData[] = []
    
    // First, try to use images from scraped_images table
    if (scrapedImagesData && scrapedImagesData.length > 0) {
      scrapedImagesData.forEach((img: any) => {
        const src = img.original_url || ''
        const alt = img.alt_text || null
        const title = img.title_text || null
        const width = img.width || undefined
        const height = img.height || undefined
        const type = img.type || getImageType(src)
        const pageUrl = img.scraped_pages?.url || ''
        
        if (src) {
          // Filter out localhost URLs
          if (src.includes('localhost') || src.includes('127.0.0.1')) {
            return
          }
          
          // Convert relative URLs to absolute
          let absoluteUrl = src
          if (!src.startsWith('http')) {
            const baseUrl = project.site_url || 'https://example.com'
            if (src.startsWith('/')) {
              absoluteUrl = `${baseUrl}${src}`
            } else {
              absoluteUrl = `${baseUrl}/${src}`
            }
          }
          
          // Convert HTTP to HTTPS
          if (absoluteUrl.startsWith('http://')) {
            absoluteUrl = absoluteUrl.replace('http://', 'https://')
          }
          
          // Note: Existing scan data is now loaded in useEffect above
          // This avoids setting state inside useMemo
          
          allImages.push({
            url: absoluteUrl,
            src: absoluteUrl,
            alt: alt,
            alt_text: alt,
            title: title,
            title_text: title,
            width: width,
            height: height,
            type: type,
            page_url: pageUrl,
            // Store the full scraped image record for future actions
            extra_metadata: {
              id: img.id,
              scraped_page_id: img.scraped_page_id,
              audit_project_id: img.audit_project_id,
              size_bytes: img.size_bytes,
              scan_results: img.scan_results,
              open_web_ninja_data: img.open_web_ninja_data,
              created_at: img.created_at,
              updated_at: img.updated_at
            }
          })
        }
      })
    }
    
    // Fallback: If no images from database, try to extract from original scraping data
    if (allImages.length === 0 && originalScrapingData?.pages && Array.isArray(originalScrapingData.pages)) {
      originalScrapingData.pages.forEach((page: ScrapedPageOverride) => {
        if (page.images && Array.isArray(page.images)) {
          page.images.forEach((img: ImageData) => {
            let src = img.src || img.url || ''
            let alt = img.alt || img.altText || img.alt_text || null
            let title = img.title || img.titleText || img.title_text || null
            let width = img.width || undefined
            let height = img.height || undefined
            
            // If we have fullTag, parse it to extract more accurate data
            if (img.fullTag) {
              const parsedData = parseImageFromFullTag(img.fullTag)
              if (parsedData) {
                // Use parsed values if available, fallback to original values
                if (parsedData.src) src = parsedData.src
                if (parsedData.alt !== null) alt = parsedData.alt
                if (parsedData.title !== null) title = parsedData.title
                if (parsedData.width !== null) width = parsedData.width
                if (parsedData.height !== null) height = parsedData.height
              }
            }
            
            if (src) {
              // Filter out localhost URLs
              if (src.includes('localhost') || src.includes('127.0.0.1')) {
                return
              }
              
              // Convert relative URLs to absolute
              let absoluteUrl = src
              if (!src.startsWith('http')) {
                const baseUrl = project.site_url || 'https://example.com'
                if (src.startsWith('/')) {
                  absoluteUrl = `${baseUrl}${src}`
                } else {
                  absoluteUrl = `${baseUrl}/${src}`
                }
              }
              
              // Convert HTTP to HTTPS
              if (absoluteUrl.startsWith('http://')) {
                absoluteUrl = absoluteUrl.replace('http://', 'https://')
              }
              
              allImages.push({
                url: absoluteUrl,
                alt: alt,
                title: title,
                width: width,
                height: height,
                type: getImageType(src),
                page_url: page.url
              })
            }
          })
        }
      })
    }
    
    // Final fallback: Parse from HTML content
    if (allImages.length === 0 && scrapedPages && scrapedPages.length > 0) {
      scrapedPages.forEach((page: ScrapedPageOverride) => {
        if (page.html_content) {
          try {
            if (typeof DOMParser === 'undefined') {
              console.warn('DOMParser not available in this environment')
              return
            }
            const parser = new DOMParser()
            const doc = parser.parseFromString(page.html_content, 'text/html')
            const imgElements = doc.querySelectorAll('img')
            
            imgElements.forEach((img: HTMLImageElement) => {
              const src = img.src || img.getAttribute('src') || ''
              const alt = img.alt || img.getAttribute('alt') || null
              const title = img.title || img.getAttribute('title') || null
              
              if (src) {
                // Filter out localhost URLs
                if (src.includes('localhost') || src.includes('127.0.0.1')) {
                  return
                }
                
                // Convert relative URLs to absolute
                let absoluteUrl = src
                if (!src.startsWith('http')) {
                  const baseUrl = project.site_url || 'https://example.com'
                  if (src.startsWith('/')) {
                    absoluteUrl = `${baseUrl}${src}`
                  } else {
                    absoluteUrl = `${baseUrl}/${src}`
                  }
                }
                
                // Convert HTTP to HTTPS
                if (absoluteUrl.startsWith('http://')) {
                  absoluteUrl = absoluteUrl.replace('http://', 'https://')
                }
                
                allImages.push({
                  url: absoluteUrl,
                  alt: alt,
                  title: title,
                  width: img.width || undefined,
                  height: img.height || undefined,
                  type: getImageType(src),
                  page_url: page.url
                })
              }
            })
          } catch (error) {
            console.warn('❌ Error parsing HTML for images:', error)
          }
        }
      })
    }
    
    setIsProcessing(false)
    return allImages
  }, [scrapedImagesData, scrapedPages, project.site_url, originalScrapingData])

  // Filter images based on selected criteria
  const filteredImages = useMemo(() => {
    let filtered = [...images]

    // Filter by image type
    if (selectedImageType !== 'all') {
      filtered = filtered.filter(img => img.type === selectedImageType)
    }

    // Filter by search query
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase()
      filtered = filtered.filter(img => 
        img.url?.toLowerCase().includes(query) ||
        img.alt?.toLowerCase().includes(query) ||
        img.title?.toLowerCase().includes(query) ||
        img.page_url?.toLowerCase().includes(query)
      )
    }


    return filtered
  }, [images, selectedImageType, searchQuery])

  // Pagination logic
  const totalPages = Math.ceil(filteredImages.length / itemsPerPage)
  const startIndex = (currentPage - 1) * itemsPerPage
  const endIndex = startIndex + itemsPerPage
  const paginatedImages = filteredImages.slice(startIndex, endIndex)

  // Reset to first page when filters change
  useEffect(() => {
    setCurrentPage(1)
  }, [selectedImageType, searchQuery])

  const stats = useMemo(() => {
    const total = images.length
    const withAlt = images.filter(img => img.alt && img.alt.trim() !== '').length
    const withoutAlt = total - withAlt
    
    return { total, withAlt, withoutAlt }
  }, [images])

  // Handle search
  const handleSearch = () => {
    setCurrentPage(1)
  }



  // Handle image click to open modal
  const handleImageClick = (image: ImageData) => {
    setSelectedImage(image)
    setShowModal(true)
  }

  // Close modal
  const closeModal = () => {
    setShowModal(false)
    setSelectedImage(null)
  }

  // Handle image scanning
  const handleScanImage = async (e: React.MouseEvent, image: ImageData) => {
    e.stopPropagation() // Prevent event bubbling
    e.preventDefault() // Prevent any default behavior
    
    // Check if user has access to image scan feature
    if (!hasImageScanFeature) {
      alert('Reverse Image Search is not available in your current plan. Please upgrade to access this feature.')
      return
    }
    
    const imageId = image.extra_metadata?.id || image.url || ''
    const uniqueKey = image.extra_metadata?.id || image.url || ''
    
    if (!uniqueKey || !image.url) {
      console.warn('❌ Cannot scan image: missing image URL')
      return
    }

    // Log image details for debugging
    console.log('🔍 Starting image scan:', {
      imageId: image.extra_metadata?.id || 'NO_ID',
      hasDatabaseId: !!image.extra_metadata?.id,
      imageUrl: image.url?.substring(0, 50),
      scrapedPageId: image.extra_metadata?.scraped_page_id
    })

    setScanningImages(prev => new Set(prev).add(uniqueKey))
    
    try {
      // Get session token for API call
      const session = await supabase.auth.getSession()
      const token = session.data.session?.access_token

      if (!token) {
        console.error('❌ No access token available')
        return
      }

      // Call reverse image search API
      let response: Response;
      let result: any;
      
      try {
        const requestBody = {
          imageUrl: image.url,
          imageId: image.extra_metadata?.id || null,
          limit: 20,
          safe_search: 'blur'
        }
        
        console.log('📤 Sending scan request:', {
          hasImageId: !!requestBody.imageId,
          imageId: requestBody.imageId
        })
        
        response = await fetch('/api/reverse-image-search', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
          },
          body: JSON.stringify(requestBody)
        })

        // Try to parse JSON response
        try {
          result = await response.json()
        } catch (parseError) {
          const textResponse = await response.text()
          console.error('❌ Failed to parse JSON response:', {
            status: response.status,
            statusText: response.statusText,
            textResponse: textResponse.substring(0, 200),
            parseError
          })
          
          throw new Error(`Invalid JSON response from server: ${textResponse.substring(0, 100)}`)
        }
      } catch (fetchError) {
        console.error('❌ Network error calling reverse-image-search API:', {
          error: fetchError,
          message: fetchError instanceof Error ? fetchError.message : String(fetchError),
          imageUrl: image.url?.substring(0, 50)
        })
        return
      }

      if (!response.ok || result.error) {
        console.error('❌ Error scanning image:', {
          status: response.status,
          statusText: response.statusText,
          error: result.error || 'Unknown error',
          message: result.message || 'No error message',
          details: result.details || 'No details',
          code: result.code || 'NO_CODE',
          fullResponse: result
        })
        
        // Handle insufficient credits error
        if (response.status === 402 || result.code === 'INSUFFICIENT_CREDITS') {
          alert(`Insufficient Credits: ${result.message || 'You do not have enough credits to scan images. Please purchase credits from the Billing section.'}`)
          // Optionally redirect to billing or show credit purchase UI
          return
        }
        
        // Handle feature access denied errors
        if (response.status === 403 || result.code === 'FEATURE_ACCESS_DENIED') {
          alert(`Access Denied: ${result.message || 'Reverse Image Search is not available in your current plan. Please upgrade to access this feature.'}`)
          return
        }
        
        // Handle rate limit errors specifically
        if (response.status === 429 || result.code === 'RATE_LIMIT_EXCEEDED') {
          const retryAfter = result.retryAfter || 5
          alert(`Rate limit reached. Please wait ${retryAfter} seconds before scanning more images.`)
          return
        }
        
        // Show user-friendly error for other errors
        if (result.message || result.error) {
          alert(`Error scanning image: ${result.message || result.error}`)
        }
        
        return
      }

      // Store scan results
      if (result.data) {
        setScanResults(prev => ({
          ...prev,
          [uniqueKey]: result.data
        }))
        // Auto-expand the row to show results
        setExpandedRows(prev => new Set(prev).add(uniqueKey))
        
        // If image has database ID, update the extra_metadata
        if (image.extra_metadata?.id) {
          image.extra_metadata.open_web_ninja_data = result.data
        }
        
        // Show credits remaining if available and refresh plan info
        if (result.creditsRemaining !== undefined) {
          console.log('✅ Credits remaining after scan:', result.creditsRemaining)
          // Refresh plan info to update credits display
          window.dispatchEvent(new Event('planUpdated'))
        }
        
        // Check if save was successful
        if (result.saveError) {
          console.error('❌ Scan completed but save to database failed:', result.saveError)
          // Show user-friendly error (you could add a toast notification here)
        } else if (result.imageId) {
          console.log('✅ Scan results saved to database for image:', result.imageId)
          
          // Refresh images from database to get updated data
          if (project?.id) {
            console.log('🔄 Refreshing images data after scan save...')
            try {
              const { data: refreshedImages, error: refreshError } = await getScrapedImages(project.id)
              if (!refreshError && refreshedImages) {
                setScrapedImagesData(refreshedImages)
                
                // Reload scan results from refreshed data into state
                const refreshedResults: Record<string, any> = {}
                refreshedImages.forEach((img: any) => {
                  if (img.open_web_ninja_data) {
                    const refreshedKey = img.id || img.original_url || ''
                    if (refreshedKey) {
                      refreshedResults[refreshedKey] = img.open_web_ninja_data
                    }
                  }
                })
                
                if (Object.keys(refreshedResults).length > 0) {
                  setScanResults(prev => ({
                    ...prev,
                    ...refreshedResults
                  }))
                  console.log('✅ Reloaded scan results from refreshed data:', Object.keys(refreshedResults).length)
                }
                
                console.log('✅ Images data refreshed, open_web_ninja_data should now be available')
              } else if (refreshError) {
                console.warn('⚠️ Could not refresh images data:', refreshError)
              }
            } catch (refreshErr) {
              console.warn('⚠️ Exception refreshing images:', refreshErr)
            }
          }
        } else {
          console.warn('⚠️ No imageId - scan results will not persist in database. Image may not be in scraped_images table yet.')
        }
      }

      console.log('✅ Image scan completed:', {
        uniqueKey,
        hasData: !!result.data,
        imageId: result.imageId,
        dataSaved: !result.saveError && !!result.imageId,
        saveError: result.saveError
      })
    } catch (error) {
      console.error('❌ Error scanning image:', error)
    } finally {
      setScanningImages(prev => {
        const next = new Set(prev)
        next.delete(uniqueKey)
        return next
      })
    }
  }

  // Toggle scan results display
  const toggleScanResults = (e: React.MouseEvent, imageKey: string) => {
    e.stopPropagation()
    setExpandedRows(prev => {
      const next = new Set(prev)
      if (next.has(imageKey)) {
        next.delete(imageKey)
      } else {
        next.add(imageKey)
      }
      return next
    })
  }

  return (
    <div className="bg-white rounded-lg  border border-gray-200 p-6">
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-semibold text-gray-900">Images Analysis</h3>
        <div className="text-sm text-gray-500">
          {isLoading || isProcessing ? (
            <span className="flex items-center gap-2">
              <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-gray-900"></div>
              {isLoading ? 'Loading images...' : 'Processing images...'}
            </span>
          ) : (
            <>
              Showing {startIndex + 1}-{Math.min(endIndex, filteredImages.length)} of {filteredImages.length} images
              {filteredImages.length !== stats.total && ` (${stats.total} total)`}
              {scrapedImagesData.length > 0 && (
                <span className="ml-2 text-green-600">• From database</span>
              )}
            </>
          )}
        </div>
      </div>


      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <div className="bg-gray-50 rounded-lg p-4">
          <div className="text-2xl font-bold text-gray-900">{stats.total}</div>
          <div className="text-sm text-gray-600">Total Images</div>
        </div>
        <div className="bg-gray-50 rounded-lg p-4">
          <div className="text-2xl font-bold text-gray-900">{stats.withAlt}</div>
          <div className="text-sm text-gray-600">With Alt Text</div>
        </div>
        <div className="bg-gray-50 rounded-lg p-4">
          <div className="text-2xl font-bold text-gray-900">{stats.withoutAlt}</div>
          <div className="text-sm text-gray-600">Without Alt Text</div>
        </div>
        <div className={`rounded-lg p-4 ${(planInfo?.image_scan_credits ?? 0) < 5 ? 'bg-yellow-50 border border-yellow-200' : 'bg-gray-50'}`}>
          <div className={`text-2xl font-bold ${(planInfo?.image_scan_credits ?? 0) < 5 ? 'text-yellow-700' : 'text-gray-900'}`}>
            {planInfo?.image_scan_credits ?? 0}
          </div>
          <div className={`text-sm ${(planInfo?.image_scan_credits ?? 0) < 5 ? 'text-yellow-600' : 'text-gray-600'}`}>
            Scan Credits
            {(planInfo?.image_scan_credits ?? 0) < 5 && (planInfo?.image_scan_credits ?? 0) > 0 && (
              <span className="block text-xs mt-1">⚠️ Low credits</span>
            )}
            {(planInfo?.image_scan_credits ?? 0) === 0 && (
              <span className="block text-xs mt-1">⚠️ No credits</span>
            )}
          </div>
        </div>
      </div>

      {/* Filter Controls */}
      <div className="bg-gray-50 rounded-lg p-4 mb-6">
        <div className="flex flex-col lg:flex-row gap-4">
          {/* Search Input */}
          <div className="flex-1">
            <label className="block text-sm font-medium text-gray-700 mb-2">Search Images</label>
            <div className="flex flex-col sm:flex-row gap-2">
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search by URL, alt text, title, or page..."
                className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
              <button
                onClick={handleSearch}
                className="px-4 py-2 bg-[#ff4b01] text-white rounded-md hover:bg-[#e64401] transition-colors w-full sm:w-auto"
              >
                Search
              </button>
            </div>
          </div>

          {/* Image Type Filter */}
          <div className="lg:w-48">
            <label className="block text-sm font-medium text-gray-700 mb-2">Image Type</label>
            <select
              value={selectedImageType}
              onChange={(e) => setSelectedImageType(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            >
              <option value="all">All Types</option>
              <option value="JPEG">JPEG</option>
              <option value="PNG">PNG</option>
              <option value="GIF">GIF</option>
              <option value="WebP">WebP</option>
              <option value="SVG">SVG</option>
              <option value="BMP">BMP</option>
              <option value="ICO">ICO</option>
              <option value="TIFF">TIFF</option>
              <option value="Unknown">Unknown</option>
            </select>
          </div>


        </div>

        {/* Clear Filters */}
        {(selectedImageType !== 'all' || searchQuery) && (
          <div className="mt-4 pt-4 border-t border-gray-200">
            <button
              onClick={() => {
                setSelectedImageType('all')
                setSearchQuery('')
              }}
              className="text-sm text-gray-600 hover:text-gray-800 underline"
            >
              Clear all filters
            </button>
          </div>
        )}
      </div>


      {/* Images Display */}
      {filteredImages.length > 0 ? (
        <>
          {/* Desktop Table View */}
          <div className="hidden lg:block overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Preview
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    URL
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Alt Text
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Type
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Dimensions
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Page
                  </th>
                  <th 
                    className="px-6 py-3 text-left text-xs font-medium text-gray-500 cursor-pointer tracking-wider relative group"
                    onMouseEnter={() => setShowActionsTooltip(true)}
                    onMouseLeave={() => setShowActionsTooltip(false)}
                  >
                    <div className="flex items-center gap-1.5">
                      Actions
                      <svg 
                        className="w-3.5 h-3.5 text-gray-400 group-hover:text-gray-600 transition-colors" 
                        fill="none" 
                        stroke="currentColor" 
                        viewBox="0 0 24 24"
                      >
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                      </svg>
                    </div>
                    {showActionsTooltip && (
                      <div className="absolute z-50 top-full right-0 mt-1 w-64 p-3 bg-white text-black text-xs rounded-lg shadow-lg pointer-events-none">
                        
                        <p className="text-black font-medium mb-1">Search Image Usage</p>
                        <p className="text-black text-xs leading-relaxed">
                          Click the "Scan Image" button to search where this image is used across the website and analyze its usage.
                        </p>
                      </div>
                    )}
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {paginatedImages.map((img, index) => {
                  // Create a truly unique key combining multiple identifiers
                  // Priority: database ID > URL + page_url + global index > fallback
                  const globalIndex = startIndex + index; // Use global index, not paginated index
                  
                  // Generate a stable unique key
                  let uniqueKey: string;
                  if (img.extra_metadata?.id) {
                    // Use database ID if available (most reliable)
                    uniqueKey = `img-${img.extra_metadata.id}`;
                  } else {
                    // Create a hash-like key from URL, page_url, and global index
                    const urlHash = img.url ? img.url.substring(0, 50).replace(/[^a-zA-Z0-9]/g, '') : 'no-url';
                    const pageHash = img.page_url ? img.page_url.substring(0, 30).replace(/[^a-zA-Z0-9]/g, '') : 'no-page';
                    uniqueKey = `img-${globalIndex}-${urlHash}-${pageHash}`;
                  }
                  
                  return (
                  <React.Fragment key={uniqueKey}>
                    <tr className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div 
                        className="w-16 h-16 bg-gray-100 rounded border overflow-hidden flex items-center justify-center cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleImageClick(img)}
                      >
                        <Image
                          src={img.url || img.src || ''}
                          alt={img.alt || 'No alt text'}
                          width={64}
                          height={64}
                          className="w-full h-full object-cover"
                          onError={(e) => {
                            const target = e.currentTarget
                            target.style.display = 'none'
                            const parent = target.parentElement
                            if (parent) {
                              parent.innerHTML = '<div class="w-full h-full flex items-center justify-center text-gray-400 text-xs">Failed to load</div>'
                            }
                          }}
                        />
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="max-w-xs truncate">
                        <a
                          href={img.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-[#ff4b01] hover:text-[#e64401] text-sm"
                        >
                          {img.url}
                        </a>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="max-w-xs">
                        {img.alt && img.alt.trim() !== '' ? (
                          <span className="text-sm text-gray-900">{img.alt}</span>
                        ) : (
                          <span className="text-sm text-gray-500 italic">No alt text</span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="inline-flex px-2 py-1 text-xs font-medium bg-gray-100 text-gray-900 rounded-full">
                        {img.type || 'Unknown'}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {img.width && img.height ? `${img.width}×${img.height}` : 'N/A'}
                    </td>
                    <td className="px-6 py-4">
                      <div className="max-w-xs truncate">
                        <a
                          href={img.page_url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-[#ff4b01] hover:text-[#e64401] text-sm"
                        >
                          {img.page_url}
                        </a>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex flex-col gap-2">
                        {(() => {
                          // Determine unique key for this image - must match the key used when loading from database
                          // Priority: database ID, then URL
                          const imageId = img.extra_metadata?.id || ''
                          const uniqueKey = imageId || img.url || ''
                          
                          // Check if scan data exists - check multiple possible keys
                          // 1. Check by database ID (primary key)
                          // 2. Check by full uniqueKey (ID or URL)
                          // 3. Check in metadata
                          const hasScanData = !!(
                            (imageId && scanResults[imageId]) ||
                            scanResults[uniqueKey] ||
                            img.extra_metadata?.open_web_ninja_data
                          )
                          
                          // If scan data exists, show "Show/Hide Results" button
                          if (hasScanData) {
                            // Use the database ID as the key if available, otherwise use uniqueKey
                            const displayKey = imageId || uniqueKey
                            
                            return (
                              <button
                                onClick={(e) => {
                                  // Load data from database if not already loaded in state
                                  const dataToLoad = img.extra_metadata?.open_web_ninja_data
                                  if (dataToLoad) {
                                    // Load using both possible keys to ensure it's found
                                    setScanResults(prev => {
                                      const updated = { ...prev }
                                      if (imageId) updated[imageId] = dataToLoad
                                      if (uniqueKey) updated[uniqueKey] = dataToLoad
                                      return updated
                                    })
                                  }
                                  toggleScanResults(e, displayKey)
                                }}
                                className="px-3 py-1.5 text-xs font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 transition-colors flex items-center justify-center gap-1"
                              >
                                {expandedRows.has(displayKey) ? (
                                  <>
                                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" />
                                    </svg>
                                    Hide Results
                                  </>
                                ) : (
                                  <>
                                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                                    </svg>
                                    Show Results
                                  </>
                                )}
                              </button>
                            )
                          }
                          
                          // If no scan data exists, show "Scan Image" button or "Upgrade Required"
                          if (hasImageScanFeature) {
                            return (
                              <button
                                onClick={(e) => handleScanImage(e, img)}
                                disabled={scanningImages.has(uniqueKey) || scanningImages.has(imageId)}
                                className="px-3 py-1.5 text-xs font-medium text-white bg-[#ff4b01] rounded-md hover:bg-[#e64401] disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center justify-center gap-1.5"
                                title={img.extra_metadata?.id ? 'Scan image from database' : 'Scan image (will be saved to database)'}
                              >
                                {(scanningImages.has(uniqueKey) || scanningImages.has(imageId)) ? (
                                  <>
                                    <div className="animate-spin rounded-full h-3 w-3 border-b-2 border-white"></div>
                                    Scanning...
                                  </>
                                ) : (
                                  <>
                                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                                    </svg>
                                    Scan Image
                                  </>
                                )}
                              </button>
                            )
                          }
                          
                          // Show upgrade required message
                          return (
                            <div className="px-3 py-1.5 text-xs font-medium text-gray-500 bg-gray-100 rounded-md flex items-center justify-center gap-1.5 cursor-not-allowed" title="Reverse Image Search is not available in your current plan">
                              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                              </svg>
                              Upgrade Required
                            </div>
                          )
                        })()}
                      </div>
                    </td>
                    </tr>
                    
                    {/* Expanded row with scan results */}
                    {expandedRows.has(img.extra_metadata?.id || img.url || '') && (
                      <tr>
                        <td colSpan={7} className="px-6 py-4 bg-gray-50">
                          <div className="bg-white rounded-lg border border-gray-200 p-4">
                            <h4 className="text-sm font-semibold text-gray-900 mb-4">Reverse Image Search Results</h4>
                            {(() => {
                              const uniqueKey = img.extra_metadata?.id || img.url || ''
                              const scanData = scanResults[uniqueKey] || img.extra_metadata?.open_web_ninja_data
                              
                              if (!scanData) return <p className="text-xs text-gray-500">No results available</p>
                              
                              // Handle the new API response structure
                              const results = scanData?.data || scanData?.data?.matches || scanData?.matches || []
                              
                              if (results.length === 0) {
                                return <p className="text-xs text-gray-500">No matches found</p>
                              }
                              
                              return (
                                <div>
                                  <p className="text-xs font-medium text-gray-700 mb-4">
                                    Found {results.length} {results.length === 1 ? 'match' : 'matches'}
                                  </p>
                                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 max-h-96 overflow-y-auto">
                                    {results.map((match: any, idx: number) => (
                                      <div 
                                        key={idx} 
                                        className="bg-white border border-gray-200 rounded-lg overflow-hidden hover:shadow-md transition-shadow"
                                      >
                                        {/* Image */}
                                        {match.image && (
                                          <div className="w-full h-40 bg-gray-100 overflow-hidden">
                                            <Image
                                              src={match.image}
                                              alt={match.title || 'Match image'}
                                              width={match.image_width || 300}
                                              height={match.image_height || 200}
                                              className="w-full h-full object-cover"
                                              onError={(e) => {
                                                const target = e.currentTarget
                                                target.style.display = 'none'
                                                const parent = target.parentElement
                                                if (parent) {
                                                  parent.innerHTML = '<div class="w-full h-full flex items-center justify-center text-gray-400 text-xs">Image not available</div>'
                                                }
                                              }}
                                            />
                                          </div>
                                        )}
                                        
                                        {/* Content */}
                                        <div className="p-3">
                                          {/* Domain with logo */}
                                          <div className="flex items-center gap-2 mb-2">
                                            {match.logo && (
                                              <img 
                                                src={match.logo} 
                                                alt={match.domain || 'Domain logo'}
                                                className="w-4 h-4 rounded"
                                                onError={(e) => {
                                                  e.currentTarget.style.display = 'none'
                                                }}
                                              />
                                            )}
                                            <span className="text-xs text-gray-500 truncate">
                                              {match.domain || 'Unknown domain'}
                                            </span>
                                            {match.date && (
                                              <span className="text-xs text-gray-400 ml-auto">
                                                {match.date}
                                              </span>
                                            )}
                                          </div>
                                          
                                          {/* Title */}
                                          {match.title && (
                                            <h5 className="text-xs font-medium text-gray-900 mb-2 line-clamp-2">
                                              {match.title}
                                            </h5>
                                          )}
                                          
                                          {/* Link */}
                                          {match.link && (
                                            <a
                                              href={match.link}
                                              target="_blank"
                                              rel="noopener noreferrer"
                                              className="text-xs text-blue-600 hover:text-blue-800 truncate block"
                                              title={match.link}
                                            >
                                              View Source →
                                            </a>
                                          )}
                                        </div>
                                      </div>
                                    ))}
                                  </div>
                                </div>
                              )
                            })()}
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                  );
                })}
              </tbody>
            </table>
          </div>

          {/* Mobile Card View */}
          <div className="lg:hidden space-y-4">
            {paginatedImages.map((img, index) => {
              // Create a truly unique key combining multiple identifiers
              // Priority: database ID > URL + page_url + global index > fallback
              const globalIndex = startIndex + index; // Use global index, not paginated index
              
              // Generate a stable unique key (same logic as desktop)
              let uniqueKey: string;
              if (img.extra_metadata?.id) {
                // Use database ID if available (most reliable)
                uniqueKey = `img-${img.extra_metadata.id}`;
              } else {
                // Create a hash-like key from URL, page_url, and global index
                const urlHash = img.url ? img.url.substring(0, 50).replace(/[^a-zA-Z0-9]/g, '') : 'no-url';
                const pageHash = img.page_url ? img.page_url.substring(0, 30).replace(/[^a-zA-Z0-9]/g, '') : 'no-page';
                uniqueKey = `img-mobile-${globalIndex}-${urlHash}-${pageHash}`;
              }
              
              return (
              <div key={uniqueKey} className="bg-white border border-gray-200 rounded-lg p-4 hover:shadow-sm transition-shadow">
                <div className="flex flex-col sm:flex-row gap-4">
                  {/* Image Preview */}
                  <div className="flex-shrink-0 mx-auto sm:mx-0">
                    <div 
                      className="w-24 h-24 bg-gray-100 rounded border overflow-hidden flex items-center justify-center cursor-pointer hover:bg-gray-200 transition-colors"
                      onClick={() => handleImageClick(img)}
                    >
                      <Image
                        src={img.url || img.src || ''}
                        alt={img.alt || 'No alt text'}
                        width={96}
                        height={96}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          const target = e.currentTarget
                          target.style.display = 'none'
                          const parent = target.parentElement
                          if (parent) {
                            parent.innerHTML = '<div class="w-full h-full flex items-center justify-center text-gray-400 text-xs">Failed to load</div>'
                          }
                        }}
                      />
                    </div>
                  </div>

                  {/* Image Details */}
                  <div className="flex-1 min-w-0 space-y-3">
                    {/* URL */}
                    <div>
                      <label className="text-xs font-medium text-gray-500 uppercase tracking-wider">URL</label>
                      <div className="mt-1">
                        <a
                          href={img.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-blue-600 hover:text-blue-800 text-sm break-all"
                        >
                          {img.url}
                        </a>
                      </div>
                    </div>

                    {/* Alt Text */}
                    <div>
                      <label className="text-xs font-medium text-gray-500 uppercase tracking-wider">Alt Text</label>
                      <div className="mt-1">
                        {img.alt && img.alt.trim() !== '' ? (
                          <span className="text-sm text-gray-900">{img.alt}</span>
                        ) : (
                          <span className="text-sm text-gray-500 italic">No alt text</span>
                        )}
                      </div>
                    </div>

                    {/* Type and Dimensions */}
                    <div className="flex flex-col sm:flex-row gap-2 sm:gap-4">
                      <div className="flex-1">
                        <label className="text-xs font-medium text-gray-500 uppercase tracking-wider">Type</label>
                        <div className="mt-1">
                          <span className="inline-flex px-2 py-1 text-xs font-medium bg-gray-100 text-gray-900 rounded-full">
                            {img.type || 'Unknown'}
                          </span>
                        </div>
                      </div>
                      <div className="flex-1">
                        <label className="text-xs font-medium text-gray-500 uppercase tracking-wider">Dimensions</label>
                        <div className="mt-1 text-sm text-gray-500">
                          {img.width && img.height ? `${img.width}×${img.height}` : 'N/A'}
                        </div>
                      </div>
                    </div>

                    {/* Page URL */}
                    <div>
                      <label className="text-xs font-medium text-gray-500 uppercase tracking-wider">Page</label>
                      <div className="mt-1">
                        <a
                          href={img.page_url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-blue-600 hover:text-blue-800 text-sm break-all"
                        >
                          {img.page_url}
                        </a>
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="relative">
                      <label 
                        className="text-xs font-medium text-gray-500 uppercase tracking-wider flex items-center gap-1.5 group"
                        onMouseEnter={() => setShowActionsTooltip(true)}
                        onMouseLeave={() => setShowActionsTooltip(false)}
                      >
                        Actions
                        <svg 
                          className="w-3 h-3 text-gray-400 group-hover:text-gray-600 transition-colors" 
                          fill="none" 
                          stroke="currentColor" 
                          viewBox="0 0 24 24"
                        >
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                      </label>
                      {showActionsTooltip && (
                        <div className="absolute z-50 top-full left-0 mt-1 w-64 p-3 bg-red-900 text-white text-xs rounded-lg shadow-lg pointer-events-none">
                          <div className="absolute -top-1 left-4 w-2 h-2 bg-gray-900 transform rotate-45"></div>
                          <p className="text-white font-medium mb-1">Search Image Usage</p>
                          <p className="text-gray-300 text-xs leading-relaxed">
                            Click the "Scan Image" button to search where this image is used across the website and analyze its usage.
                          </p>
                        </div>
                      )}
                      <div className="mt-1 space-y-2">
                        {(() => {
                          // Determine unique key for this image - must match the key used when loading from database
                          // Priority: database ID, then URL
                          const imageId = img.extra_metadata?.id || ''
                          const uniqueKey = imageId || img.url || ''
                          
                          // Check if scan data exists - check multiple possible keys
                          // 1. Check by database ID (primary key)
                          // 2. Check by full uniqueKey (ID or URL)
                          // 3. Check in metadata
                          const hasScanData = !!(
                            (imageId && scanResults[imageId]) ||
                            scanResults[uniqueKey] ||
                            img.extra_metadata?.open_web_ninja_data
                          )
                          
                          // If scan data exists, show "Show/Hide Results" button
                          if (hasScanData) {
                            // Use the database ID as the key if available, otherwise use uniqueKey
                            const displayKey = imageId || uniqueKey
                            
                            return (
                              <button
                                onClick={(e) => {
                                  // Load data from database if not already loaded in state
                                  const dataToLoad = img.extra_metadata?.open_web_ninja_data
                                  if (dataToLoad) {
                                    // Load using both possible keys to ensure it's found
                                    setScanResults(prev => {
                                      const updated = { ...prev }
                                      if (imageId) updated[imageId] = dataToLoad
                                      if (uniqueKey) updated[uniqueKey] = dataToLoad
                                      return updated
                                    })
                                  }
                                  toggleScanResults(e, displayKey)
                                }}
                                className="w-full px-3 py-1.5 text-xs font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 transition-colors flex items-center justify-center gap-1"
                              >
                                {expandedRows.has(displayKey) ? (
                                  <>
                                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" />
                                    </svg>
                                    Hide Results
                                  </>
                                ) : (
                                  <>
                                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                                    </svg>
                                    Show Results
                                  </>
                                )}
                              </button>
                            )
                          }
                          
                          // If no scan data exists, show "Scan Image" button or "Upgrade Required"
                          if (hasImageScanFeature) {
                            return (
                              <button
                                onClick={(e) => handleScanImage(e, img)}
                                disabled={scanningImages.has(uniqueKey) || scanningImages.has(imageId)}
                                className="w-full sm:w-auto px-3 py-1.5 text-xs font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center justify-center gap-1.5"
                                title={img.extra_metadata?.id ? 'Scan image from database' : 'Scan image (will be saved to database)'}
                              >
                                {(scanningImages.has(uniqueKey) || scanningImages.has(imageId)) ? (
                                  <>
                                    <div className="animate-spin rounded-full h-3 w-3 border-b-2 border-white"></div>
                                    Scanning...
                                  </>
                                ) : (
                                  <>
                                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                                    </svg>
                                    Scan Image
                                  </>
                                )}
                              </button>
                            )
                          }
                          
                          // Show upgrade required message
                          return (
                            <div className="w-full px-3 py-1.5 text-xs font-medium text-gray-500 bg-gray-100 rounded-md flex items-center justify-center gap-1.5 cursor-not-allowed" title="Reverse Image Search is not available in your current plan">
                              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                              </svg>
                              Upgrade Required
                            </div>
                          )
                        })()}
                      </div>
                      
                      {/* Expanded scan results */}
                      {expandedRows.has(img.extra_metadata?.id || img.url || '') && (
                        <div className="mt-3 bg-white rounded-lg border border-gray-200 p-4">
                          <h4 className="text-sm font-semibold text-gray-900 mb-4">Reverse Image Search Results</h4>
                          {(() => {
                            const uniqueKey = img.extra_metadata?.id || img.url || ''
                            const scanData = scanResults[uniqueKey] || img.extra_metadata?.open_web_ninja_data
                            
                            if (!scanData) return <p className="text-xs text-gray-500">No results available</p>
                            
                            // Handle the new API response structure
                            const results = scanData?.data || scanData?.data?.matches || scanData?.matches || []
                            
                            if (results.length === 0) {
                              return <p className="text-xs text-gray-500">No matches found</p>
                            }
                            
                            return (
                              <div>
                                <p className="text-xs font-medium text-gray-700 mb-4">
                                  Found {results.length} {results.length === 1 ? 'match' : 'matches'}
                                </p>
                                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 max-h-96 overflow-y-auto">
                                  {results.map((match: any, idx: number) => (
                                    <div 
                                      key={idx} 
                                      className="bg-white border border-gray-200 rounded-lg overflow-hidden hover:shadow-md transition-shadow"
                                    >
                                      {/* Image */}
                                      {match.image && (
                                        <div className="w-full h-40 bg-gray-100 overflow-hidden">
                                          <Image
                                            src={match.image}
                                            alt={match.title || 'Match image'}
                                            width={match.image_width || 300}
                                            height={match.image_height || 200}
                                            className="w-full h-full object-cover"
                                            onError={(e) => {
                                              const target = e.currentTarget
                                              target.style.display = 'none'
                                              const parent = target.parentElement
                                              if (parent) {
                                                parent.innerHTML = '<div class="w-full h-full flex items-center justify-center text-gray-400 text-xs">Image not available</div>'
                                              }
                                            }}
                                          />
                                        </div>
                                      )}
                                      
                                      {/* Content */}
                                      <div className="p-3">
                                        {/* Domain with logo */}
                                        <div className="flex items-center gap-2 mb-2">
                                          {match.logo && (
                                            <img 
                                              src={match.logo} 
                                              alt={match.domain || 'Domain logo'}
                                              className="w-4 h-4 rounded"
                                              onError={(e) => {
                                                e.currentTarget.style.display = 'none'
                                              }}
                                            />
                                          )}
                                          <span className="text-xs text-gray-500 truncate">
                                            {match.domain || 'Unknown domain'}
                                          </span>
                                          {match.date && (
                                            <span className="text-xs text-gray-400 ml-auto">
                                              {match.date}
                                            </span>
                                          )}
                                        </div>
                                        
                                        {/* Title */}
                                        {match.title && (
                                          <h5 className="text-xs font-medium text-gray-900 mb-2 line-clamp-2">
                                            {match.title}
                                          </h5>
                                        )}
                                        
                                        {/* Link */}
                                        {match.link && (
                                          <a
                                            href={match.link}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            className="text-xs text-blue-600 hover:text-blue-800 truncate block"
                                            title={match.link}
                                          >
                                            View Source →
                                          </a>
                                        )}
                                      </div>
                                    </div>
                                  ))}
                                </div>
                              </div>
                            )
                          })()}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
              );
            })}
          </div>
        </>
      ) : (
        <div className="text-center py-8">
          <div className="text-gray-400 mb-2">
            <svg className="w-12 h-12 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
          </div>
          <p className="text-gray-600">No images found matching your filters</p>
        </div>
      )}

      {/* Pagination Controls */}
      {filteredImages.length > itemsPerPage && (
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mt-6 pt-4 border-t border-gray-200">
          <div className="flex items-center justify-center sm:justify-start text-sm text-gray-700">
            <span>
              Page {currentPage} of {totalPages}
            </span>
          </div>
          
          <div className="flex items-center justify-center space-x-2">
            {/* Previous Button */}
            <button
              onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
              disabled={currentPage === 1}
              className="px-3 py-1.5 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-white"
            >
              <span className="hidden sm:inline">Previous</span>
              <span className="sm:hidden">‹</span>
            </button>

            {/* Page Numbers */}
            <div className="flex items-center space-x-1">
              {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                let pageNum;
                if (totalPages <= 5) {
                  pageNum = i + 1;
                } else if (currentPage <= 3) {
                  pageNum = i + 1;
                } else if (currentPage >= totalPages - 2) {
                  pageNum = totalPages - 4 + i;
                } else {
                  pageNum = currentPage - 2 + i;
                }

                return (
                  <button
                    key={pageNum}
                    onClick={() => setCurrentPage(pageNum)}
                    className={`px-3 py-1.5 text-sm font-medium rounded-md ${
                      currentPage === pageNum
                        ? 'bg-gray-900 text-white'
                        : 'text-gray-700 bg-white border border-gray-300 hover:bg-gray-50'
                    }`}
                  >
                    {pageNum}
                  </button>
                );
              })}
            </div>

            {/* Next Button */}
            <button
              onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
              disabled={currentPage === totalPages}
              className="px-3 py-1.5 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-white"
            >
              <span className="hidden sm:inline">Next</span>
              <span className="sm:hidden">›</span>
            </button>
          </div>
        </div>
      )}

      {/* Image Modal */}
      {showModal && selectedImage && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-4xl max-h-[90vh] w-full overflow-hidden border border-gray-300 ">
            {/* Modal Header */}
            <div className="flex items-center justify-between p-4 border-b border-gray-200">
              <h3 className="text-lg font-semibold text-gray-900">Image Details</h3>
              <button
                onClick={closeModal}
                className="text-gray-400 hover:text-gray-600 transition-colors"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            {/* Modal Content */}
            <div className="p-4 overflow-y-auto max-h-[calc(90vh-120px)]">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Large Image */}
                <div className="space-y-4">
                  <div className="bg-gray-100 rounded-lg p-4 flex items-center justify-center min-h-[300px]">
                    <Image
                      src={selectedImage.url || selectedImage.src || ''}
                      alt={selectedImage.alt || 'No alt text'}
                      width={400}
                      height={400}
                      className="max-w-full max-h-[400px] object-contain rounded-lg "
                      onError={(e) => {
                        const target = e.currentTarget
                        target.style.display = 'none'
                        const parent = target.parentElement
                        if (parent) {
                          parent.innerHTML = '<div class="text-center text-gray-400">Failed to load image</div>'
                        }
                      }}
                    />
                  </div>
                  
                  {/* Image Actions */}
                  <div className="flex gap-2">
                    <a
                      href={selectedImage.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex-1 bg-[#ff4b01] text-white px-4 py-2 rounded-md hover:bg-[#e64401] transition-colors text-center"
                    >
                      Open in New Tab
                    </a>
                    <button
                      onClick={() => navigator.clipboard.writeText(selectedImage.url || selectedImage.src || '')}
                      className="px-4 py-2 border border-gray-300 text-gray-700 rounded-md hover:bg-gray-50 transition-colors"
                    >
                      Copy URL
                    </button>
                  </div>
                </div>

                {/* Image Details */}
                <div className="space-y-4">
                  <div className="bg-gray-50 rounded-lg p-4">
                    <h4 className="font-medium text-gray-900 mb-3">Image Information</h4>
                    <div className="space-y-3">
                      <div>
                        <label className="text-sm font-medium text-gray-600">URL:</label>
                        <p className="text-sm text-gray-900 break-all mt-1">{selectedImage.url}</p>
                      </div>
                      
                      <div>
                        <label className="text-sm font-medium text-gray-600">Alt Text:</label>
                        <p className="text-sm text-gray-900 mt-1">
                          {selectedImage.alt && selectedImage.alt.trim() !== '' ? selectedImage.alt : 'No alt text provided'}
                        </p>
                      </div>
                      
                      {selectedImage.title && (
                        <div>
                          <label className="text-sm font-medium text-gray-600">Title:</label>
                          <p className="text-sm text-gray-900 mt-1">{selectedImage.title}</p>
                        </div>
                      )}
                      
                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <label className="text-sm font-medium text-gray-600">Type:</label>
                          <p className="text-sm text-gray-900 mt-1">{selectedImage.type || 'Unknown'}</p>
                        </div>
                        
                        <div>
                          <label className="text-sm font-medium text-gray-600">Dimensions:</label>
                          <p className="text-sm text-gray-900 mt-1">
                            {selectedImage.width && selectedImage.height 
                              ? `${selectedImage.width} × ${selectedImage.height}` 
                              : 'N/A'
                            }
                          </p>
                        </div>
                      </div>
                      
                      {selectedImage.page_url && (
                        <div>
                          <label className="text-sm font-medium text-gray-600">Found on Page:</label>
                          <a
                            href={selectedImage.page_url}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="text-sm text-blue-600 hover:text-blue-800 break-all block mt-1"
                          >
                            {selectedImage.page_url}
                          </a>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Accessibility Check */}
                  <div className="bg-gray-50 rounded-lg p-4">
                    <h4 className="font-medium text-gray-900 mb-3">Accessibility</h4>
                    <div className="space-y-2">
                      <div className="flex items-center gap-2">
                        {selectedImage.alt && selectedImage.alt.trim() !== '' ? (
                          <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                            ✓ Has Alt Text
                          </span>
                        ) : (
                          <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-red-100 text-red-800">
                            ✗ Missing Alt Text
                          </span>
                        )}
                      </div>
                      
                      {selectedImage.alt && selectedImage.alt.trim() !== '' && (
                        <div className="text-sm text-gray-600">
                          <strong>Alt Text:</strong> &quot;{selectedImage.alt}&quot;
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useMemo, useCallback, useEffect } from 'react'
import { AuditProject } from '@/types/audit'
import { ScrapedPage } from '../analysis-tab/types'
import { useSupabase } from '@/contexts/SupabaseContext'
import { useUserPlan } from '@/hooks/useUserPlan'
import { supabase } from '@/lib/supabase-client'

// Override the ScrapedPage type to accept any performance_analysis type
interface ScrapedPageOverride extends Omit<ScrapedPage, 'performance_analysis'> {
  performance_analysis?: Record<string, unknown>
}

interface OriginalScrapingData {
  pages?: ScrapedPageOverride[]
}

interface LinksSectionProps {
  project: AuditProject
  scrapedPages: ScrapedPageOverride[]
  originalScrapingData?: OriginalScrapingData
}

interface LinkData {
  url: string
  text: string | null
  title: string | null
  type: 'internal' | 'external'
  page_url?: string
  target?: string
  rel?: string
  isBroken?: boolean
  status?: 'working' | 'broken' | 'unknown'
}


export default function LinksSection({ project, scrapedPages, originalScrapingData }: LinksSectionProps) {
  const { updateScrapedPage, user } = useSupabase()
  const { hasFeature } = useUserPlan()
  const [currentPage, setCurrentPage] = useState(1)
  const [itemsPerPage] = useState(20) // Reduced from 40 to 20 for better performance
  const [isProcessing, setIsProcessing] = useState(false)
  const [isExporting, setIsExporting] = useState(false)
  
  // Check if user has broken links check feature
  const hasBrokenLinksFeature = hasFeature('broken_links_check')
  
  // Filter states
  const [selectedLinkType, setSelectedLinkType] = useState<string>('all')
  const [searchQuery, setSearchQuery] = useState('')
  const [checkingBrokenLinks, setCheckingBrokenLinks] = useState(false)

  // Function to check if a link is broken using API endpoint
  const checkLinkBroken = useCallback(async (linkUrl: string): Promise<boolean> => {
    try {
      // Get session token for API call
      const { data: { session } } = await supabase.auth.getSession()
      const token = session?.access_token

      if (!token) {
        console.error('❌ No access token available for link check')
        return true // Assume broken if no auth
      }

      // Use API endpoint to check link status (bypasses CORS)
      const response = await fetch('/api/check-link', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ url: linkUrl }),
      })
      
      if (!response.ok) {
        // Handle feature access denied
        if (response.status === 403) {
          const errorData = await response.json().catch(() => ({}))
          console.warn('Feature access denied for link check:', errorData)
          return true // Assume broken if access denied
        }
        
        console.warn(`API check failed for ${linkUrl}:`, response.status)
        return true // Assume broken if API fails
      }
      
      const data = await response.json()
      return data.isBroken === true
    } catch (error) {
      console.error('Error checking link:', error, linkUrl)
      return true // Link is broken on error
    }
  }, [])

  // State to track link statuses
  const [linkStatuses, setLinkStatuses] = useState<Record<string, 'working' | 'broken' | 'unknown'>>({})

  // Load existing link statuses from database on mount
  useEffect(() => {
    const loadExistingStatuses = async () => {
      if (!scrapedPages || scrapedPages.length === 0) return

      const statusMap: Record<string, 'working' | 'broken' | 'unknown'> = {}

      scrapedPages.forEach(page => {
        if (!page.links) return

        let pageLinks: any[] = []
        if (typeof page.links === 'string') {
          try {
            pageLinks = JSON.parse(page.links)
          } catch {
            pageLinks = Array.isArray(page.links) ? page.links : []
          }
        } else if (Array.isArray(page.links)) {
          pageLinks = page.links
        }

        pageLinks.forEach((link: any) => {
          const linkUrl = link.url || link.href || ''
          if (linkUrl && link.status) {
            statusMap[linkUrl] = link.status
          } else if (linkUrl && link.isBroken !== undefined) {
            statusMap[linkUrl] = link.isBroken ? 'broken' : 'working'
          }
        })
      })

      if (Object.keys(statusMap).length > 0) {
        setLinkStatuses(statusMap)
      }
    }

    loadExistingStatuses()
  }, [scrapedPages])

  // Extract links from original scraping data or HTML content
  const links = useMemo(() => {
    setIsProcessing(true)
    const allLinks: LinkData[] = []
    const baseDomain = project.site_url ? new URL(project.site_url).hostname : ''
    
    // First, try to extract from original scraping data
    if (originalScrapingData?.pages && Array.isArray(originalScrapingData.pages)) {
      
      
      originalScrapingData.pages.forEach((page: ScrapedPageOverride) => {
        if (page.links && Array.isArray(page.links)) {
          page.links.forEach((link) => {
            const href = link.url || ''
            if (href && href !== '#') {
              // Filter out localhost URLs
              if (href.includes('localhost') || href.includes('127.0.0.1')) {
                return
              }
              
              // Convert relative URLs to absolute
              let absoluteUrl = href.startsWith('http') ? href : 
                href.startsWith('/') ? `${project.site_url}${href}` : 
                `${project.site_url}/${href}`
              
              // Convert HTTP to HTTPS
              if (absoluteUrl.startsWith('http://')) {
                absoluteUrl = absoluteUrl.replace('http://', 'https://')
              }
              
              const isInternal = href.startsWith('/') || 
                (href.startsWith('http') && href.includes(baseDomain))
              
              allLinks.push({
                url: absoluteUrl,
                text: link.text || null,
                title: link.title || null,
                type: isInternal ? 'internal' : 'external',
                page_url: page.url,
                target: '_self',
                rel: undefined
              })
            }
          })
        }
      })
    }
    
    // If no links found in scraping data, fall back to HTML parsing
    if (allLinks.length === 0 && scrapedPages && scrapedPages.length > 0) {
      
      
      scrapedPages.forEach((page: ScrapedPageOverride) => {
        if (page.html_content) {
          try {
            // Create a temporary DOM parser to extract links
            if (typeof DOMParser === 'undefined') {
              console.warn('DOMParser not available in this environment')
              return
            }
            const parser = new DOMParser()
            const doc = parser.parseFromString(page.html_content, 'text/html')
            const linkElements = doc.querySelectorAll('a[href]')
            
            linkElements.forEach((link) => {
              const anchorElement = link as HTMLAnchorElement
              const href = anchorElement.href || anchorElement.getAttribute('href') || ''
              if (href && href !== '#') {
                // Filter out localhost URLs
                if (href.includes('localhost') || href.includes('127.0.0.1')) {
                  return
                }
                
                // Convert relative URLs to absolute
                let absoluteUrl = href.startsWith('http') ? href : 
                  href.startsWith('/') ? `${project.site_url}${href}` : 
                  `${project.site_url}/${href}`
                
                // Convert HTTP to HTTPS
                if (absoluteUrl.startsWith('http://')) {
                  absoluteUrl = absoluteUrl.replace('http://', 'https://')
                }
                
                const isInternal = href.startsWith('/') || 
                  (href.startsWith('http') && href.includes(baseDomain))
                
                allLinks.push({
                  url: absoluteUrl,
                  text: anchorElement.textContent?.trim() || null,
                  title: anchorElement.title || null,
                  type: isInternal ? 'internal' : 'external',
                  page_url: page.url,
                  target: anchorElement.target || '_self',
                  rel: anchorElement.rel || undefined
                })
              }
            })
          } catch (error) {
            console.warn('Error parsing HTML for links:', error)
          }
        }
      })
    }
    
    setIsProcessing(false)
    return allLinks
  }, [scrapedPages, project.site_url, originalScrapingData])

  // Function to update link statuses in database
  const updateLinkStatusesInDB = useCallback(async (
    statusUpdates: Array<{ url: string; status: 'working' | 'broken' | 'unknown' }>
  ) => {
    if (!user || !updateScrapedPage || statusUpdates.length === 0) {
      return
    }

    // Create a map from page URL to page ID
    const pageUrlToIdMap = new Map<string, string>()
    scrapedPages.forEach(page => {
      if (page.url && page.id) {
        pageUrlToIdMap.set(page.url, page.id)
      }
    })

    // Group status updates by page_url
    const updatesByPage = new Map<string, Array<{ url: string; status: 'working' | 'broken' | 'unknown' }>>()
    
    statusUpdates.forEach(update => {
      const link = links.find(l => l.url === update.url)
      if (link && link.page_url) {
        if (!updatesByPage.has(link.page_url)) {
          updatesByPage.set(link.page_url, [])
        }
        updatesByPage.get(link.page_url)!.push(update)
      }
    })

    // Update each affected page
    const updatePromises = Array.from(updatesByPage.entries()).map(async ([pageUrl, updates]) => {
      const pageId = pageUrlToIdMap.get(pageUrl)
      if (!pageId) {
        console.warn(`Page ID not found for URL: ${pageUrl}`)
        return
      }

      // Find the scraped page
      const scrapedPage = scrapedPages.find(p => p.id === pageId)
      if (!scrapedPage) {
        console.warn(`Scraped page not found for ID: ${pageId}`)
        return
      }

      try {
        // Parse existing links
        let pageLinks: any[] = []
        if (scrapedPage.links) {
          if (typeof scrapedPage.links === 'string') {
            try {
              pageLinks = JSON.parse(scrapedPage.links)
            } catch {
              pageLinks = Array.isArray(scrapedPage.links) ? scrapedPage.links : []
            }
          } else if (Array.isArray(scrapedPage.links)) {
            pageLinks = scrapedPage.links
          }
        }

        // Update link statuses in the array
        const updatedLinks = pageLinks.map((link: any) => {
          const linkUrl = link.url || link.href || ''
          const update = updates.find(u => {
            // Normalize URLs for comparison
            const normalizedUpdateUrl = u.url.replace(/\/$/, '')
            const normalizedLinkUrl = linkUrl.replace(/\/$/, '')
            return normalizedUpdateUrl === normalizedLinkUrl
          })
          
          if (update) {
            return {
              ...link,
              status: update.status,
              isBroken: update.status === 'broken'
            }
          }
          return link
        })

        // Update the page in database
        const { error } = await updateScrapedPage(pageId, {
          links: updatedLinks
        })

        if (error) {
          console.error(`Error updating links for page ${pageId}:`, error)
        } else {
          console.log(`✅ Updated ${updates.length} link status(es) for page ${pageUrl}`)
        }
      } catch (error) {
        console.error(`Error processing links for page ${pageId}:`, error)
      }
    })

    // Wait for all database updates to complete
    await Promise.all(updatePromises)
  }, [user, updateScrapedPage, scrapedPages, links])

  // Function to check all links for broken status in batches of 50
  const checkAllLinksBroken = useCallback(async () => {
    // Check if user has access to broken links check feature
    if (!hasBrokenLinksFeature) {
      alert('Broken Links Check is not available in your current plan. Please upgrade to access this feature.')
      return
    }
    
    setCheckingBrokenLinks(true)
    try {
      const batchSize = 50
      const totalLinks = links.length
      const statusMap: Record<string, 'working' | 'broken' | 'unknown'> = {}
      
      // Process links in batches of 50
      for (let i = 0; i < totalLinks; i += batchSize) {
        const batch = links.slice(i, i + batchSize)
        
        // Process current batch in parallel
        const batchPromises = batch.map(async (link) => {
          if (link.url) {
            try {
              const isBroken = await checkLinkBroken(link.url)
              return { url: link.url, status: isBroken ? 'broken' as const : 'working' as const }
            } catch {
              return { url: link.url, status: 'unknown' as const }
            }
          }
          return { url: link.url, status: 'unknown' as const }
        })

        // Wait for current batch to complete
        const batchResults = await Promise.all(batchPromises)
        
        // Update status map with batch results
        const batchStatusUpdates: Array<{ url: string; status: 'working' | 'broken' | 'unknown' }> = []
        batchResults.forEach(result => {
          statusMap[result.url] = result.status
          batchStatusUpdates.push(result)
        })
        
        // Update state after each batch so UI shows progress
        setLinkStatuses(prev => ({ ...prev, ...statusMap }))
        
        // Update database with batch results
        try {
          await updateLinkStatusesInDB(batchStatusUpdates)
        } catch (dbError) {
          console.error('Error updating database:', dbError)
          // Continue processing even if DB update fails
        }
        
        // Small delay between batches to avoid overwhelming the server
        if (i + batchSize < totalLinks) {
          await new Promise(resolve => setTimeout(resolve, 100))
        }
      }
    } catch (error) {
      console.error('Error checking broken links:', error)
    } finally {
      setCheckingBrokenLinks(false)
    }
  }, [links, checkLinkBroken, updateLinkStatusesInDB, hasBrokenLinksFeature])

  // Filter links based on selected criteria
  const filteredLinks = useMemo(() => {
    let filtered = [...links]

    // Filter by link type
    if (selectedLinkType === 'broken') {
      // Filter for broken links
      filtered = filtered.filter(link => linkStatuses[link.url] === 'broken')
    } else if (selectedLinkType !== 'all') {
      filtered = filtered.filter(link => link.type === selectedLinkType)
    }

    // Filter by search query
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase()
      filtered = filtered.filter(link => 
        link.url?.toLowerCase().includes(query) ||
        link.text?.toLowerCase().includes(query) ||
        link.title?.toLowerCase().includes(query) ||
        link.page_url?.toLowerCase().includes(query)
      )
    }

    return filtered
  }, [links, selectedLinkType, searchQuery, linkStatuses])

  // Pagination logic
  const totalPages = Math.ceil(filteredLinks.length / itemsPerPage)
  const startIndex = (currentPage - 1) * itemsPerPage
  const endIndex = startIndex + itemsPerPage
  const paginatedLinks = filteredLinks.slice(startIndex, endIndex)

  // Reset to first page when filters change
  useEffect(() => {
    setCurrentPage(1)
  }, [selectedLinkType, searchQuery])

  const stats = useMemo(() => {
    const total = links.length
    const internal = links.filter(link => link.type === 'internal').length
    const external = links.filter(link => link.type === 'external').length
    const broken = links.filter(link => linkStatuses[link.url] === 'broken').length
    const working = links.filter(link => linkStatuses[link.url] === 'working').length
    
    return { total, internal, external, broken, working }
  }, [links, linkStatuses])

  // Handle search
  const handleSearch = () => {
    setCurrentPage(1)
  }

  // Handle check broken links (hook prepared; UI trigger can be added when needed)


  // Export functions
  const exportToCSV = () => {
    setIsExporting(true)
    try {
      const csvContent = [
        ['URL', 'Text', 'Title', 'Type', 'Target', 'Page URL'],
        ...filteredLinks.map(link => [
          link.url,
          link.text || '',
          link.title || '',
          link.type,
          link.target || '_self',
          link.page_url || ''
        ])
      ].map(row => row.map(field => `"${field.replace(/"/g, '""')}"`).join(',')).join('\n')

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' })
      const link = document.createElement('a')
      const url = URL.createObjectURL(blob)
      link.setAttribute('href', url)
      link.setAttribute('download', `links-export-${new Date().toISOString().split('T')[0]}.csv`)
      link.style.visibility = 'hidden'
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
    } catch (error) {
      console.error('Error exporting CSV:', error)
    } finally {
      setIsExporting(false)
    }
  }

  const exportToJSON = () => {
    setIsExporting(true)
    try {
      const jsonContent = {
        exportDate: new Date().toISOString(),
        project: project.site_url,
        totalLinks: filteredLinks.length,
        links: filteredLinks.map(link => ({
          url: link.url,
          text: link.text,
          title: link.title,
          type: link.type,
          target: link.target,
          page_url: link.page_url,
          rel: link.rel
        }))
      }

      const blob = new Blob([JSON.stringify(jsonContent, null, 2)], { type: 'application/json' })
      const link = document.createElement('a')
      const url = URL.createObjectURL(blob)
      link.setAttribute('href', url)
      link.setAttribute('download', `links-export-${new Date().toISOString().split('T')[0]}.json`)
      link.style.visibility = 'hidden'
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
    } catch (error) {
      console.error('Error exporting JSON:', error)
    } finally {
      setIsExporting(false)
    }
  }

  const exportToTXT = () => {
    setIsExporting(true)
    try {
      const txtContent = [
        `Links Export - ${project.site_url}`,
        `Export Date: ${new Date().toLocaleString()}`,
        `Total Links: ${filteredLinks.length}`,
        '',
        '='.repeat(80),
        '',
        ...filteredLinks.map((link, index) => [
          `${index + 1}. ${link.url}`,
          `   Text: ${link.text || 'No text'}`,
          `   Title: ${link.title || 'No title'}`,
          `   Type: ${link.type}`,
          `   Target: ${link.target || '_self'}`,
          `   Page: ${link.page_url || 'Unknown'}`,
          ''
        ].join('\n'))
      ].join('\n')

      const blob = new Blob([txtContent], { type: 'text/plain;charset=utf-8;' })
      const link = document.createElement('a')
      const url = URL.createObjectURL(blob)
      link.setAttribute('href', url)
      link.setAttribute('download', `links-export-${new Date().toISOString().split('T')[0]}.txt`)
      link.style.visibility = 'hidden'
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
    } catch (error) {
      console.error('Error exporting TXT:', error)
    } finally {
      setIsExporting(false)
    }
  }


  return (
    <div className="bg-white rounded-lg  border border-gray-200 p-6">
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-semibold text-gray-900">Links Analysis</h3>
        <div className="flex items-center gap-4">
          <div className="text-sm text-gray-500">
            {isProcessing ? (
              <span className="flex items-center gap-2">
                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-gray-900"></div>
                Processing links...
              </span>
            ) : (
              <>
                Showing {startIndex + 1}-{Math.min(endIndex, filteredLinks.length)} of {filteredLinks.length} links
                {filteredLinks.length !== stats.total && ` (${stats.total} total)`}
              </>
            )}
          </div>
          
          {/* Export Button */}
          {filteredLinks.length > 0 && (
            <div className="relative group">
              <button
                disabled={isExporting}
                className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isExporting ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-gray-900"></div>
                    Exporting...
                  </>
                ) : (
                  <>
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                    </svg>
                    Export
                  </>
                )}
              </button>
              
              {/* Export Options Dropdown */}
              <div className="absolute right-0 top-full mt-1 w-48 bg-white border border-gray-200 rounded-md  opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-200 z-10">
                <div className="py-1">
                  <button
                    onClick={exportToCSV}
                    disabled={isExporting}
                    className="flex items-center gap-2 w-full px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 disabled:opacity-50"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                    </svg>
                    Export as CSV
                  </button>
                  <button
                    onClick={exportToJSON}
                    disabled={isExporting}
                    className="flex items-center gap-2 w-full px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 disabled:opacity-50"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4" />
                    </svg>
                    Export as JSON
                  </button>
                  <button
                    onClick={exportToTXT}
                    disabled={isExporting}
                    className="flex items-center gap-2 w-full px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 disabled:opacity-50"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                    </svg>
                    Export as TXT
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-5 gap-4 mb-6">
        <div className="bg-gray-50 rounded-lg p-4">
          <div className="text-2xl font-bold text-gray-900">{stats.total}</div>
          <div className="text-sm text-gray-600">Total Links</div>
        </div>
        <div className="bg-gray-50 rounded-lg p-4">
          <div className="text-2xl font-bold text-gray-900">{stats.internal}</div>
          <div className="text-sm text-gray-600">Internal</div>
        </div>
        <div className="bg-gray-50 rounded-lg p-4">
          <div className="text-2xl font-bold text-gray-900">{stats.external}</div>
          <div className="text-sm text-gray-600">External</div>
        </div>
        <div className="bg-gray-50 rounded-lg p-4">
          <div className="text-2xl font-bold text-gray-900">{stats.broken}</div>
          <div className="text-sm text-gray-600">Broken Links</div>
        </div>
        <div className="bg-gray-50 rounded-lg p-4">
          <div className="text-2xl font-bold text-gray-900">{stats.working}</div>
          <div className="text-sm text-gray-600">Working Links</div>
        </div>
      </div>

      {/* Filter Controls */}
      <div className="bg-gray-50 rounded-lg p-4 mb-6">
        <div className="flex flex-col lg:flex-row gap-4">
          {/* Search Input */}
          <div className="flex-1">
            <label className="block text-sm font-medium text-gray-700 mb-2">Search Links</label>
            <div className="flex gap-2">
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search by URL, text, title, or page..."
                className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
              <button
                onClick={handleSearch}
                className="px-4 py-2 bg-[#ff4b01] text-white rounded-md hover:bg-[#e64401] transition-colors"
              >
                Search
              </button>
            </div>
          </div>

          {/* Link Type Filter */}
          <div className="lg:w-48">
            <label className="block text-sm font-medium text-gray-700 mb-2">Link Type</label>
            <select
              value={selectedLinkType}
              onChange={(e) => setSelectedLinkType(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            >
              <option value="all">All Types</option>
              <option value="internal">Internal</option>
              <option value="external">External</option>
              <option value="broken">Broken Links</option>
            </select>
          </div>

          {/* Check Broken Links Button */}
          <div className="lg:w-48">
            <label className="block text-sm font-medium text-gray-700 mb-2">Link Status</label>
            {hasBrokenLinksFeature ? (
              <button
                onClick={checkAllLinksBroken}
                disabled={checkingBrokenLinks || links.length === 0}
                className="w-full px-3 py-2 text-sm font-medium text-white bg-[#ff4b01] border border-[#ff4b01] rounded-md hover:bg-[#e64401] disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-[#ff4b01] transition-colors"
              >
                {checkingBrokenLinks ? (
                  <span className="flex items-center justify-center gap-2">
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                    Checking...
                  </span>
                ) : (
                  'Check Broken Links'
                )}
              </button>
            ) : (
              <div className="w-full px-3 py-2 text-sm font-medium text-gray-500 bg-gray-100 border border-gray-300 rounded-md flex items-center justify-center gap-1.5 cursor-not-allowed" title="Broken Links Check is not available in your current plan">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                </svg>
                Upgrade Required
              </div>
            )}
          </div>

        </div>

        {/* Clear Filters */}
        {(selectedLinkType !== 'all' || searchQuery) && (
          <div className="mt-4 pt-4 border-t border-gray-200">
            <button
              onClick={() => {
                setSelectedLinkType('all')
                setSearchQuery('')
              }}
              className="text-sm text-gray-600 hover:text-gray-800 underline"
            >
              Clear all filters
            </button>
          </div>
        )}
      </div>

      {/* Links Table */}
      {filteredLinks.length > 0 ? (
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Link Text
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  URL
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Type
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Target
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Page
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  Status
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {paginatedLinks.map((link, index) => {
                const linkStatus = linkStatuses[link.url] || 'unknown'
                return (
                  <tr key={index} className="hover:bg-gray-50">
                    <td className="px-6 py-4">
                      <div className="max-w-xs">
                        <div className="text-sm font-medium text-gray-900 truncate">
                          {link.text || 'No text'}
                        </div>
                        {link.title && (
                          <div className="text-sm text-gray-500 truncate" title={link.title}>
                            {link.title}
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="max-w-xs">
                        <a
                          href={link.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-[#ff4b01] hover:text-[#e64401] text-sm truncate block"
                        >
                          {link.url}
                        </a>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`inline-flex px-2 py-1 text-xs font-medium rounded-full ${
                        link.type === 'internal' 
                          ? 'bg-gray-100 text-gray-900' 
                          : 'bg-gray-200 text-gray-900'
                      }`}>
                        {link.type}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {link.target || '_self'}
                    </td>
                    <td className="px-6 py-4">
                      <div className="max-w-xs truncate">
                        <a
                          href={link.page_url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-blue-600 hover:text-blue-800 text-sm"
                        >
                          {link.page_url}
                        </a>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {linkStatus === 'broken' ? (
                        <span className="inline-flex px-2 py-1 text-xs font-medium rounded-full bg-red-100 text-red-800">
                          Broken
                        </span>
                      ) : linkStatus === 'working' ? (
                        <span className="inline-flex px-2 py-1 text-xs font-medium rounded-full bg-green-100 text-green-800">
                          Working
                        </span>
                      ) : (
                        <span className="inline-flex px-2 py-1 text-xs font-medium rounded-full bg-gray-100 text-gray-600">
                          Unknown
                        </span>
                      )}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
      ) : (
        <div className="text-center py-8">
          <div className="text-gray-400 mb-2">
            <svg className="w-12 h-12 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1" />
            </svg>
          </div>
          <p className="text-gray-600">No links found matching your filters</p>
        </div>
      )}

      {/* Pagination Controls */}
      {filteredLinks.length > itemsPerPage && (
        <div className="flex items-center justify-between mt-6 pt-4 border-t border-gray-200">
          <div className="flex items-center text-sm text-gray-700">
            <span>
              Page {currentPage} of {totalPages}
            </span>
          </div>
          
          <div className="flex items-center space-x-2">
            {/* Previous Button */}
            <button
              onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
              disabled={currentPage === 1}
              className="px-3 py-1.5 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-white"
            >
              Previous
            </button>

            {/* Page Numbers */}
            <div className="flex items-center space-x-1">
              {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                let pageNum;
                if (totalPages <= 5) {
                  pageNum = i + 1;
                } else if (currentPage <= 3) {
                  pageNum = i + 1;
                } else if (currentPage >= totalPages - 2) {
                  pageNum = totalPages - 4 + i;
                } else {
                  pageNum = currentPage - 2 + i;
                }

                return (
                  <button
                    key={pageNum}
                    onClick={() => setCurrentPage(pageNum)}
                    className={`px-3 py-1.5 text-sm font-medium rounded-md ${
                      currentPage === pageNum
                        ? 'bg-gray-900 text-white'
                        : 'text-gray-700 bg-white border border-gray-300 hover:bg-gray-50'
                    }`}
                  >
                    {pageNum}
                  </button>
                );
              })}
            </div>

            {/* Next Button */}
            <button
              onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
              disabled={currentPage === totalPages}
              className="px-3 py-1.5 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-white"
            >
              Next
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { AuditProject } from '@/types/audit';
import { useSupabase } from '@/contexts/SupabaseContext';
import { DetectedKey, detectKeysInHtml } from '@/lib/key-detection';
interface KeysTabProps {
  project: AuditProject;
  pageHtml?: string;
  pageUrl?: string;
  pageName?: string;
}
interface KeysData {
  keys: DetectedKey[];
  total: number;
  page: number;
  limit: number;
  totalPages: number;
  filters: {
    status: string;
    severity: string;
  };
  summary: {
    totalKeys: number;
    exposedKeys: number;
    secureKeys: number;
    criticalKeys: number;
    highRiskKeys: number;
    analysisComplete: boolean;
    processingTime: number;
  };
}
export default function KeysTab({
  project,
  pageHtml,
  pageUrl: _pageUrl,
  pageName: _pageName
}: KeysTabProps) {
  const {
    getDetectedKeys
  } = useSupabase();
  const [keysData, setKeysData] = useState<KeysData | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(20);
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [severityFilter, setSeverityFilter] = useState<string>('all');

  // Load keys data from database with pagination and filtering
  const loadKeysData = useCallback(async (page = 1, limit = 20, status = 'all', severity = 'all') => {
    if (!project?.id) return;
    if (!getDetectedKeys) {
      // Fallback to client-side detection if function is not available
      if (pageHtml && pageHtml.length > 0) {
        setIsLoading(true);
        setError(null);
        try {
          const result = await detectKeysInHtml(pageHtml);
          setKeysData({
            keys: result.keys,
            total: result.totalKeys,
            page,
            limit,
            totalPages: Math.max(1, Math.ceil(result.totalKeys / limit)),
            filters: {
              status,
              severity
            },
            summary: {
              totalKeys: result.totalKeys,
              exposedKeys: result.exposedKeys,
              secureKeys: result.secureKeys,
              criticalKeys: result.criticalKeys,
              highRiskKeys: result.highRiskKeys,
              analysisComplete: result.analysisComplete,
              processingTime: result.processingTime
            }
          });
        } catch (err) {
          setError('Failed to analyze keys data');
        } finally {
          setIsLoading(false);
        }
      } else {
        setError('Keys detection function not available');
      }
      return;
    }
    setIsLoading(true);
    setError(null);
    try {
      const {
        data,
        error
      } = await getDetectedKeys(project.id, page, limit, status, severity);
      if (error) {
        // Try fallback to client-side detection if HTML is available
        if (pageHtml && pageHtml.length > 0) {

          const result = await detectKeysInHtml(pageHtml);
          setKeysData({
            keys: result.keys,
            total: result.totalKeys,
            page,
            limit,
            totalPages: Math.max(1, Math.ceil(result.totalKeys / limit)),
            filters: {
              status,
              severity
            },
            summary: {
              totalKeys: result.totalKeys,
              exposedKeys: result.exposedKeys,
              secureKeys: result.secureKeys,
              criticalKeys: result.criticalKeys,
              highRiskKeys: result.highRiskKeys,
              analysisComplete: result.analysisComplete,
              processingTime: result.processingTime
            }
          });
          return;
        }
        console.error('Error loading keys data:', error);
        setError(`Failed to load keys data: ${error.message || 'Unknown error'}`);
        return;
      }
      if (data) {
        // If DB has no keys, try client-side detection as a convenience
        if ((data.total ?? 0) === 0 && pageHtml && pageHtml.length > 0) {
          const result = await detectKeysInHtml(pageHtml);
          setKeysData({
            keys: result.keys,
            total: result.totalKeys,
            page,
            limit,
            totalPages: Math.max(1, Math.ceil(result.totalKeys / limit)),
            filters: {
              status,
              severity
            },
            summary: {
              totalKeys: result.totalKeys,
              exposedKeys: result.exposedKeys,
              secureKeys: result.secureKeys,
              criticalKeys: result.criticalKeys,
              highRiskKeys: result.highRiskKeys,
              analysisComplete: result.analysisComplete,
              processingTime: result.processingTime
            }
          });
        } else {
          setKeysData(data);
        }
      }
    } catch (err) {
      // Fallback to client-side detection if HTML is available
      if (pageHtml && pageHtml.length > 0) {

        try {
          const result = await detectKeysInHtml(pageHtml);
          setKeysData({
            keys: result.keys,
            total: result.totalKeys,
            page,
            limit,
            totalPages: Math.max(1, Math.ceil(result.totalKeys / limit)),
            filters: {
              status,
              severity
            },
            summary: {
              totalKeys: result.totalKeys,
              exposedKeys: result.exposedKeys,
              secureKeys: result.secureKeys,
              criticalKeys: result.criticalKeys,
              highRiskKeys: result.highRiskKeys,
              analysisComplete: result.analysisComplete,
              processingTime: result.processingTime
            }
          });
        } catch (fallbackErr) {
          console.error('Fallback detection also failed:', fallbackErr);
          setError('Failed to analyze keys data');
        }
      } else {
        console.error('Unexpected error loading keys data:', err);
        setError('Unexpected error occurred while loading keys data');
      }
    } finally {
      setIsLoading(false);
    }
  }, [project?.id, getDetectedKeys, pageHtml]);

  // Load data when component mounts or project changes
  useEffect(() => {
    if (project?.id) {
      setCurrentPage(1);
      setStatusFilter('all');
      setSeverityFilter('all');
      loadKeysData(1, itemsPerPage, 'all', 'all');
    }
  }, [project?.id, loadKeysData, itemsPerPage]);

  // Load data when page, items per page, or filters change
  useEffect(() => {
    if (project?.id) {
      loadKeysData(currentPage, itemsPerPage, statusFilter, severityFilter);
    }
  }, [currentPage, itemsPerPage, statusFilter, severityFilter, loadKeysData, project?.id]);

  // Reset to page 1 when filters change
  useEffect(() => {
    if (project?.id && currentPage !== 1) {
      setCurrentPage(1);
    }
  }, [statusFilter, severityFilter, project?.id, currentPage]);
  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'critical':
        return 'bg-[#ff4b01]/40 text-[#ff4b01] border-[#ff4b01]/40';
      case 'high':
        return 'bg-[#ff4b01]/30 text-[#ff4b01] border-[#ff4b01]/30';
      case 'medium':
        return 'bg-[#ff4b01]/20 text-[#ff4b01] border-[#ff4b01]/20';
      case 'low':
        return 'bg-[#ff4b01]/10 text-[#ff4b01] border-[#ff4b01]/10';
      default:
        return 'bg-[#ff4b01]/20 text-[#ff4b01] border-[#ff4b01]/20';
    }
  };
  const LoadingSkeleton = () => <div className="space-y-3">
      {[1, 2, 3].map(i => <div key={i} className="bg-gray-100 rounded-lg p-4">
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-center space-x-3 mb-2">
                <div className="h-4 bg-gray-200 rounded w-1/4"></div>
                <div className="h-6 bg-gray-200 rounded-full w-16"></div>
                <div className="h-6 bg-gray-200 rounded-full w-20"></div>
              </div>
              <div className="space-y-2">
                <div className="h-3 bg-gray-200 rounded w-3/4"></div>
                <div className="h-3 bg-gray-200 rounded w-1/2"></div>
                <div className="h-3 bg-gray-200 rounded w-2/3"></div>
              </div>
            </div>
          </div>
        </div>)}
    </div>;
  return <div className="space-y-6">
      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
        <div className="flex items-start">
          <div className="w-5 h-5 text-[#ff4b01] mt-0.5 mr-3 flex items-center justify-center">
            <span className="text-sm">⚠</span>
          </div>
          <div>
            <h4 className="text-sm font-medium text-yellow-800">Security Keys Analysis</h4>
            <p className="text-sm text-yellow-700 mt-1">
              This analysis checks for exposed API keys, secrets, and sensitive credentials in your website.
            </p>
          </div>
        </div>
      </div>

      {/* Loading State */}
      {isLoading && <div className="space-y-4">
          <div className="flex items-center space-x-2 text-[#ff4b01]">
            <svg className="w-4 h-4 animate-spin" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
            <span className="text-sm font-medium">Loading keys data...</span>
          </div>
          <LoadingSkeleton />
        </div>}

      {/* Error State */}
      {error && <div className="bg-red-50 border border-red-200 rounded-lg p-4">
            <div className="flex items-start">
              <div className="w-5 h-5 text-[#ff4b01] mt-0.5 mr-3 flex items-center justify-center">
                <span className="text-sm">❌</span>
              </div>
              <div>
              <h4 className="text-sm font-medium text-red-800">Error</h4>
              <p className="text-sm text-red-700 mt-1">{error}</p>
            </div>
          </div>
        </div>}

      {/* Analysis Results */}
      {!isLoading && !error && keysData && <>
          {/* Summary */}
          <div className="bg-[#ff4b01]/10 border border-[#ff4b01]/30 rounded-lg p-4">
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
              <div className="min-w-0">
                <h4 className="text-sm font-medium text-[#ff4b01]">Analysis Summary</h4>
                <p className="text-sm text-[#ff4b01] mt-1">
                  Found {keysData.summary.totalKeys} keys across {project.total_pages || 1} pages
                  {pageHtml && keysData.summary.totalKeys > 0 && (
                    <span className="text-xs text-[#ff4b01]/80 ml-2">(analyzed from current page)</span>
                  )}
                </p>
              </div>
              <div className="flex flex-wrap items-center gap-2 sm:gap-4 text-sm">
                <span className="text-[#ff4b01] font-medium whitespace-nowrap">
                  {keysData.summary.exposedKeys} Exposed
                </span>
                <span className="text-[#ff4b01]/90 font-medium whitespace-nowrap">
                  {keysData.summary.secureKeys} Secure
                </span>
                <span className="text-[#ff4b01]/70 font-medium whitespace-nowrap">
                  {keysData.summary.criticalKeys} Critical
                </span>
              </div>
            </div>
          </div>

          {/* Filters */}
          <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
            <div className="flex flex-col sm:flex-row sm:items-center gap-4">
              <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4">
                <div className="flex items-center space-x-2">
                  <label className="text-sm font-medium text-gray-700 whitespace-nowrap">Status:</label>
                  <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="text-sm border border-gray-300 rounded px-3 py-1 min-w-0 flex-1 sm:flex-none">
                    <option value="all">All Status</option>
                    <option value="exposed">Exposed</option>
                    <option value="secure">Secure</option>
                    <option value="warning">Warning</option>
                  </select>
                </div>

                <div className="flex items-center space-x-2">
                  <label className="text-sm font-medium text-gray-700 whitespace-nowrap">Severity:</label>
                  <select value={severityFilter} onChange={e => setSeverityFilter(e.target.value)} className="text-sm border border-gray-300 rounded px-3 py-1 min-w-0 flex-1 sm:flex-none">
                    <option value="all">All Severity</option>
                    <option value="critical">Critical</option>
                    <option value="high">High</option>
                    <option value="medium">Medium</option>
                    <option value="low">Low</option>
                  </select>
                </div>
              </div>

              <div className="flex items-center">
                <button onClick={() => {
              setStatusFilter('all');
              setSeverityFilter('all');
            }} className="text-sm text-[#ff4b01] hover:text-[#e64401] underline whitespace-nowrap">
                  Clear Filters
                </button>
              </div>
            </div>
          </div>

          {/* Keys List */}
          {keysData.keys.length > 0 ? <div className="space-y-4">
              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                <h4 className="text-md font-medium text-gray-700">
                  Detected Keys ({keysData.total} total, showing {keysData.keys.length})
                </h4>
                <div className="flex items-center space-x-2">
                  <span className="text-sm text-gray-500 whitespace-nowrap">Items per page:</span>
                  <select value={itemsPerPage} onChange={e => setItemsPerPage(Number(e.target.value))} className="text-sm border border-gray-300 rounded px-2 py-1">
                    <option value={10}>10</option>
                    <option value={20}>20</option>
                    <option value={50}>50</option>
                    <option value={100}>100</option>
                  </select>
                </div>
              </div>

              <div className="space-y-3">
                {keysData.keys.map((key, index) => <div key={key.id || index} className="bg-white border border-gray-200 rounded-lg p-4 hover:shadow-sm transition-shadow">
                    <div className="flex items-start justify-between">
                      <div className="flex-1 min-w-0">
                        <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-3 mb-2">
                          <h5 className="text-sm font-medium text-gray-900 truncate">{key.type}</h5>
                          <div className="flex flex-wrap gap-2">
                            <span className={`px-2 py-1 text-xs font-medium rounded-full border ${getSeverityColor(key.severity)}`}>
                              {key.severity}
                            </span>
                            <span className={`px-2 py-1 text-xs font-medium rounded-full ${key.status === 'exposed' ? 'bg-[#ff4b01]/40 text-[#ff4b01]' : key.status === 'secure' ? 'bg-[#ff4b01]/20 text-[#ff4b01]' : 'bg-[#ff4b01]/30 text-[#ff4b01]'}`}>
                              {key.status}
                            </span>
                          </div>
                        </div>
                        <div className="space-y-2">
                          <div className="text-sm text-gray-600">
                            <span className="font-medium">Key:</span>
                            <div className="mt-1 font-mono text-xs break-all">
                              {key.key}
                            </div>
                          </div>
                          <div className="text-sm text-gray-600">
                            <span className="font-medium">Location:</span>
                            <div className="mt-1 font-mono text-xs break-all">
                              {key.location}
                            </div>
                          </div>
                          <div className="text-sm text-gray-600">
                            <span className="font-medium">Description:</span>
                            <span className="ml-1">{key.description}</span>
                          </div>
                          {key.context && <div className="text-sm text-gray-600">
                              <span className="font-medium">Context:</span>
                              <div className="mt-1 text-xs break-all">
                                {key.context}
                              </div>
                            </div>}
                          <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4 text-xs text-gray-500">
                            <div className="flex-1 min-w-0">
                              <span className="font-medium">Pattern:</span>
                              <div className="mt-1 font-mono text-xs break-all">
                                {key.pattern}
                              </div>
                            </div>
                            <div className="flex-shrink-0">
                              <span className="font-medium">Confidence: {key.confidence}%</span>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>)}
              </div>

              {/* Pagination */}
              {keysData.totalPages > 1 && <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mt-6">
                  <div className="text-sm text-gray-500 text-center sm:text-left">
                    Showing {(currentPage - 1) * itemsPerPage + 1} to {Math.min(currentPage * itemsPerPage, keysData.total)} of {keysData.total} results
                  </div>
                  <div className="flex items-center justify-center space-x-2">
                    <button onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} disabled={currentPage === 1} className="px-3 py-1 text-sm border border-gray-300 rounded disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50">
                      Previous
                    </button>
                    <span className="text-sm text-gray-600 px-2">
                      Page {currentPage} of {keysData.totalPages}
                    </span>
                    <button onClick={() => setCurrentPage(prev => Math.min(keysData.totalPages, prev + 1))} disabled={currentPage === keysData.totalPages} className="px-3 py-1 text-sm border border-gray-300 rounded disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50">
                      Next
                    </button>
                  </div>
                </div>}
            </div> : <div className="text-center py-8">
              <div className="text-gray-500">
                <div className="w-12 h-12 mx-auto mb-4 text-gray-300 flex items-center justify-center">
                  <span className="text-3xl">🔒</span>
                </div>
                <h4 className="text-lg font-medium text-gray-900 mb-2">No Keys Detected</h4>
                <p className="text-gray-600">No security keys or credentials were found in the analyzed pages.</p>
              </div>
            </div>}
        </>}
    </div>;
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { useSupabase } from '@/contexts/SupabaseContext';
import { supabase } from '@/lib/supabase-client';
import { AnalysisTabState, ScrapedPage } from '../types';
import { AuditProject } from '@/types/audit';
import { useProjectsStore } from '@/lib/stores/projectsStore';

/** Minimal shape used from the user profile for feedback gating */
type MinimalProfile = {
  projects?: number | null;
  feedback_given?: boolean | string | null;
};

/** Helper function to check if feedback has been given, handles both boolean true and string "TRUE" (case-insensitive) */
const hasGivenFeedback = (feedback_given: boolean | string | null | undefined): boolean => {
  console.log('🔍 [DEBUG] hasGivenFeedback check:', {
    value: feedback_given,
    type: typeof feedback_given,
    isNull: feedback_given === null,
    isUndefined: feedback_given === undefined,
    rawValue: JSON.stringify(feedback_given)
  });
  
  if (feedback_given === null || feedback_given === undefined) {
    console.log('🔍 [DEBUG] feedback_given is null/undefined, returning false');
    return false;
  }
  if (typeof feedback_given === 'boolean') {
    const result = feedback_given === true;
    console.log('🔍 [DEBUG] feedback_given is boolean:', feedback_given, '→ result:', result);
    return result;
  }
  if (typeof feedback_given === 'string') {
    const upperValue = feedback_given.toUpperCase();
    const result = upperValue === 'TRUE';
    console.log('🔍 [DEBUG] feedback_given is string:', {
      original: feedback_given,
      uppercase: upperValue,
      result: result
    });
    return result;
  }
  console.log('🔍 [DEBUG] feedback_given type not recognized, returning false');
  return false;
};
/** Minimal shape used from scrape responses where only summary counts and favicons are read */
type ScrapeResponseSummary = {
  summary?: {
    totalLinks?: number;
    totalImages?: number;
    favicons?: unknown[];
  };
  pages?: unknown[];
};
interface CachedData {
  project: AuditProject | null;
  scrapedPages: ScrapedPage[];
  lastFetchTime: number;
}
export function useScrapingAnalysis(projectId: string, cachedData?: CachedData | null) {
  const {
    getAuditProject,
    getScrapedPages,
    updateAuditProject,
    session,
    user,
    userProfile,
    updateUser
  } = useSupabase();

  // Use Zustand store for updating project status
  const { updateProject, projects } = useProjectsStore();
  const [state, setState] = useState<AnalysisTabState>({
    project: null,
    scrapedPages: [],
    loading: true,
    error: null,
    activeSection: 'overview',
    dataFetched: false,
    lastFetchTime: 0,
    isScraping: false,
    scrapingError: null,
    isPageSpeedLoading: false,
    hasAutoStartedPageSpeed: false,
    loadedSections: new Set(['overview']),
    scrapedPagesLoaded: false,
    hasAutoStartedSeoAnalysis: false,
    dataVersion: 0,
    isRefreshing: false
  });

  // Track if scraping has been initiated to prevent multiple calls
  const [scrapingInitiated, setScrapingInitiated] = useState(false);
  const initializationRef = useRef(false);
  const [showFeedbackModal, setShowFeedbackModal] = useState(false);
  const userProfileRef = useRef(userProfile);

  useEffect(() => {
    userProfileRef.current = userProfile;
    console.log('🔍 [DEBUG] userProfile updated:', {
      feedback_given: userProfile?.feedback_given,
      type: typeof userProfile?.feedback_given,
      rawValue: JSON.stringify(userProfile?.feedback_given)
    });
  }, [userProfile]);

  // Debug: Track feedback modal state changes
  useEffect(() => {
    console.log('🔍 [DEBUG] showFeedbackModal state changed to:', showFeedbackModal);
  }, [showFeedbackModal]);

  // Update state helper
  const updateState = useCallback((updates: Partial<AnalysisTabState>) => {
    setState(prev => ({
      ...prev,
      ...updates
    }));
  }, []);

  // Fetch latest feedback_given directly from DB to avoid stale profile
  const fetchLatestFeedbackGiven = useCallback(async (): Promise<boolean> => {
    try {
      if (!user?.id) {
        return hasGivenFeedback(userProfileRef.current?.feedback_given);
      }
      const { data, error } = await supabase
        .from('users')
        .select('feedback_given')
        .eq('id', user.id)
        .single<{ feedback_given: boolean | string | null }>();
      if (error) {
        console.error('🔍 [DEBUG] Failed to fetch latest feedback_given:', error);
        return hasGivenFeedback(userProfileRef.current?.feedback_given);
      }
      console.log('🔍 [DEBUG] Latest feedback_given from DB:', data?.feedback_given);
      return hasGivenFeedback(data?.feedback_given);
    } catch (err) {
      console.error('🔍 [DEBUG] Unexpected error fetching latest feedback_given:', err);
      return hasGivenFeedback(userProfileRef.current?.feedback_given);
    }
  }, [user?.id]);

  // Load scraped pages
  const loadScrapedPages = useCallback(async () => {
    if (!projectId) return;
    try {
      const {
        data: pages,
        error: pagesError
      } = await getScrapedPages(projectId);
      if (pagesError) {
        // Handle "Request already in progress" as a non-error case
        if (pagesError.message === 'Request already in progress') {
          return; // Don't treat this as an error
        }
        console.error('Error loading scraped pages:', pagesError);
        console.error('Error details:', JSON.stringify(pagesError, null, 2));
        // Don't return early - still try to update state to show error
        updateState({
          error: `Failed to load scraped pages: ${pagesError.message || 'Unknown error'}`
        });
        return;
      }
      if (pages) {
        updateState({
          scrapedPages: pages.map(page => ({
            ...page,
            images: (page as any).images || null
          })),
          scrapedPagesLoaded: true,
          error: null // Clear any previous errors
        });
      }
    } catch (error) {
      console.error('Unexpected error loading scraped pages:', error);
      console.error('Error details:', JSON.stringify(error, null, 2));
      updateState({
        error: `Failed to load scraped pages: ${error instanceof Error ? error.message : 'Unknown error'}`
      });
    }
  }, [projectId, getScrapedPages, updateState]);

  // Start scraping process
  const startScraping = useCallback(async (project: AuditProject) => {
    // Prevent multiple scraping calls with multiple guards
    if (scrapingInitiated || state.isScraping) {
      return;
    }

    // Additional check to prevent race conditions
    if (initializationRef.current === false) {
      return;
    }
    setScrapingInitiated(true);
    updateState({
      isScraping: true,
      scrapingError: null
    });
    try {
      // Check if user is authenticated
      if (!session?.access_token) {
        console.error('❌ No session access token available');
        throw new Error('User not authenticated. Please log in again.');
      }
      // Pre-scrape feedback modal (non-blocking)
      try {
        const currentProfile = userProfileRef.current as MinimalProfile | null;
        const projectCount = (projects?.length || currentProfile?.projects || 0) as number;
        console.log('🔍 [DEBUG] Pre-scrape feedback check:', {
          currentProfile: currentProfile ? { ...currentProfile, feedback_given: currentProfile.feedback_given } : null,
          projectCount,
          projectsLength: projects?.length,
          profileProjects: currentProfile?.projects
        });
        const userHasGivenFeedback = await fetchLatestFeedbackGiven();
        console.log('🔍 [DEBUG] Pre-scrape result:', {
          userHasGivenFeedback,
          projectCount,
          shouldShowModal: projectCount >= 2 && !userHasGivenFeedback
        });
        if (projectCount >= 2 && !userHasGivenFeedback) {
          console.log('🔍 [DEBUG] Setting feedback modal to TRUE (pre-scrape)');
          setShowFeedbackModal(true);
        }
      } catch (error) {
        console.error('🔍 [DEBUG] Error in pre-scrape feedback check:', error);
      }

      // Call scraping API
      const scrapeResponse = await fetch('/api/scrape', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': `Bearer ${session.access_token}`
        },
        body: JSON.stringify({
          url: project.site_url,
          mode: (project as {
            page_type?: string;
          }).page_type === 'single' ? 'single' : 'multipage',
          maxPages: 100,
          extractImagesFlag: true,
          extractLinksFlag: true,
          detectTechnologiesFlag: true
        })
      });
      if (!scrapeResponse.ok) {
        let errorData: { code?: string; message?: string; error?: string } = {};
        try {
          const text = await scrapeResponse.text();
          errorData = text ? JSON.parse(text) : {};
          console.log('🔍 [DEBUG] Scrape error response:', {
            status: scrapeResponse.status,
            statusText: scrapeResponse.statusText,
            errorData,
            rawText: text
          });
        } catch (parseError) {
          console.error('🔍 [DEBUG] Failed to parse error response:', parseError);
          errorData = {};
        }

        // Handle specific error cases
        if (errorData.code === 'SERVICE_UNAVAILABLE') {
          throw new Error('Scraping service is not running. Please start the scraping service or contact support.');
        }

        // Handle plan limit errors
        if (errorData.code === 'PROJECT_LIMIT_REACHED') {
          throw new Error(`Project limit reached: ${errorData.message || 'Unknown error'}`);
        }

        // Handle feature not available errors
        if (errorData.code === 'FEATURE_NOT_AVAILABLE') {
          throw new Error(`Feature not available: ${errorData.message || 'Unknown error'}`);
        }

        // Handle authentication errors
        if (errorData.code === 'MISSING_AUTH' || errorData.code === 'INVALID_AUTH' || scrapeResponse.status === 401) {
          const errorMessage = errorData.message || errorData.error || 'Authentication failed';
          console.error('❌ Authentication error:', {
            status: scrapeResponse.status,
            statusText: scrapeResponse.statusText,
            errorCode: errorData.code,
            errorMessage: errorMessage,
            hasSession: !!session?.access_token,
            sessionExpired: !session?.access_token
          });
          // Try to refresh the session
          try {
            const {
              data: {
                session: newSession
              },
              error: refreshError
            } = await supabase.auth.refreshSession();
            if (refreshError || !newSession) {
              throw new Error(`Session refresh failed: ${refreshError?.message || 'Please log in again.'}`);
            }
            // Retry the scraping request with the new token
            const retryResponse = await fetch('/api/scrape', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'Authorization': `Bearer ${newSession.access_token}`
              },
              body: JSON.stringify({
                url: project.site_url,
                mode: (project as {
                  page_type?: string;
                }).page_type === 'single' ? 'single' : 'multipage',
                maxPages: 100,
                extractImagesFlag: true,
                extractLinksFlag: true,
                detectTechnologiesFlag: true
              })
            });
            if (!retryResponse.ok) {
              const retryErrorData = await retryResponse.json().catch(() => ({}));
              throw new Error(retryErrorData.message || retryErrorData.error || `Scraping failed: ${retryResponse.status}`);
            }
            const retryData = await retryResponse.json();

            // Update project status to completed FIRST (without large data to avoid timeout)
            const {
              error: updateError
            } = await updateAuditProject(project.id, {
              status: 'completed',
              progress: 100,
              scraping_completed_at: new Date().toISOString(),
              total_pages: retryData.pages?.length || 0,
              total_links: retryData.summary?.totalLinks || 0,
              total_images: retryData.summary?.totalImages || 0
            });
            if (updateError) {
              throw new Error(`Failed to update project: ${updateError.message}`);
            }

            // Update Zustand store immediately
            updateProject(project.id, {
              status: 'completed',
              progress: 100,
              scraping_completed_at: new Date().toISOString(),
              total_pages: retryData.pages?.length || 0,
              total_links: retryData.summary?.totalLinks || 0,
              total_images: retryData.summary?.totalImages || 0
            } as Parameters<typeof updateProject>[1]);

            // Update the project in state immediately
            const updatedProject = {
              ...project,
              status: 'completed' as const,
              progress: 100,
              scraping_completed_at: new Date().toISOString(),
              total_pages: retryData.pages?.length || 0,
              total_links: retryData.summary?.totalLinks || 0,
              total_images: retryData.summary?.totalImages || 0,
              scraping_data: retryData
            };
            updateState({
              project: updatedProject,
              isScraping: false,
              dataVersion: state.dataVersion + 1
            });

            // Show feedback modal after successful crawl completion
            try {
              const currentProfile = userProfileRef.current as MinimalProfile | null;
              const projectCount = (projects?.length || currentProfile?.projects || 0) as number;
              console.log('🔍 [DEBUG] Post-scrape feedback check (retry path):', {
                currentProfile: currentProfile ? { ...currentProfile, feedback_given: currentProfile.feedback_given } : null,
                projectCount,
                projectsLength: projects?.length,
                profileProjects: currentProfile?.projects
              });
              const userHasGivenFeedback = await fetchLatestFeedbackGiven();
              console.log('🔍 [DEBUG] Post-scrape result (retry path):', {
                userHasGivenFeedback,
                projectCount,
                shouldShowModal: projectCount >= 2 && !userHasGivenFeedback
              });
              if (projectCount >= 2 && !userHasGivenFeedback) {
                console.log('🔍 [DEBUG] Setting feedback modal to TRUE (post-scrape retry path)');
                setShowFeedbackModal(true);
              }
            } catch (error) {
              console.error('🔍 [DEBUG] Error in post-scrape feedback check (retry path):', error);
            }
            return; // Success, exit early
          } catch (refreshError) {
            console.error('❌ Session refresh failed:', refreshError);
            throw new Error('Authentication required. Please log in again.');
          }
        }
        throw new Error(errorData.message || errorData.error || `Scraping failed: ${scrapeResponse.status}`);
      }
      const scrapeData = await scrapeResponse.json();

      // Log the scraping data received from API
      const scrapeSummary = scrapeData as ScrapeResponseSummary;

      // Update project status to completed FIRST (without large data to avoid timeout)
      const {
        error: updateError
      } = await updateAuditProject(project.id, {
        status: 'completed',
        progress: 100,
        scraping_completed_at: new Date().toISOString(),
        total_pages: scrapeSummary.pages ? scrapeSummary.pages.length : 0,
        total_links: scrapeSummary.summary?.totalLinks || 0,
        total_images: scrapeSummary.summary?.totalImages || 0,
        brand_data: {
          favicons: scrapeSummary.summary?.favicons || [],
          summary: scrapeSummary.summary
        } // Store favicon data in brand_data
      });
      if (updateError) {
        throw new Error(`Failed to update project: ${updateError.message}`);
      }

      // Update Zustand store immediately
      updateProject(project.id, {
        status: 'completed',
        progress: 100,
        scraping_completed_at: new Date().toISOString(),
        total_pages: scrapeSummary.pages ? scrapeSummary.pages.length : 0,
        total_links: scrapeSummary.summary?.totalLinks || 0,
        total_images: scrapeSummary.summary?.totalImages || 0
      } as Parameters<typeof updateProject>[1]);

      // Update the project in state immediately
      const updatedProject = {
        ...project,
        status: 'completed' as const,
        progress: 100,
        scraping_completed_at: new Date().toISOString(),
        total_pages: scrapeSummary.pages ? scrapeSummary.pages.length : 0,
        total_links: scrapeSummary.summary?.totalLinks || 0,
        total_images: scrapeSummary.summary?.totalImages || 0,
        scraping_data: scrapeData
      };
      updateState({
        project: updatedProject,
        isScraping: false,
        dataVersion: state.dataVersion + 1
      });

      // Show feedback modal after successful crawl completion
      try {
        const currentProfile = userProfileRef.current as MinimalProfile | null;
        const projectCount = (projects?.length || currentProfile?.projects || 0) as number;
        console.log('🔍 [DEBUG] Post-scrape feedback check (main path):', {
          currentProfile: currentProfile ? { ...currentProfile, feedback_given: currentProfile.feedback_given } : null,
          projectCount,
          projectsLength: projects?.length,
          profileProjects: currentProfile?.projects
        });
        const userHasGivenFeedback = await fetchLatestFeedbackGiven();
        console.log('🔍 [DEBUG] Post-scrape result (main path):', {
          userHasGivenFeedback,
          projectCount,
          shouldShowModal: projectCount >= 2 && !userHasGivenFeedback
        });
        if (projectCount >= 2 && !userHasGivenFeedback) {
          console.log('🔍 [DEBUG] Setting feedback modal to TRUE (post-scrape main path)');
          setShowFeedbackModal(true);
        } else {
          console.log('🔍 [DEBUG] NOT showing feedback modal:', {
            reason: projectCount < 2 ? 'projectCount < 2' : 'userHasGivenFeedback = true'
          });
        }
      } catch (error) {
        console.error('🔍 [DEBUG] Error in post-scrape feedback check (main path):', error);
      }
    } catch (error) {
      console.error('❌ Scraping error:', error);

      // Provide more user-friendly error messages
      let errorMessage = 'Scraping failed';
      if (error instanceof Error) {
        const errorMsgLower = error.message.toLowerCase();
        if (errorMsgLower.includes('authentication') || 
            errorMsgLower.includes('session') || 
            errorMsgLower.includes('auth') ||
            errorMsgLower.includes('401') ||
            errorMsgLower.includes('unauthorized') ||
            errorMsgLower.includes('log in')) {
          errorMessage = 'Your session has expired. Please refresh the page and try again.';
        } else if (error.message.includes('SERVICE_UNAVAILABLE')) {
          errorMessage = 'The scraping service is currently unavailable. Please try again later.';
        } else if (error.message.includes('PROJECT_LIMIT_REACHED')) {
          errorMessage = 'You have reached your project limit. Please upgrade your plan to create more projects.';
        } else if (error.message.includes('FEATURE_NOT_AVAILABLE')) {
          errorMessage = 'This feature is not available in your current plan. Please upgrade to access this feature.';
        } else {
          errorMessage = error.message;
        }
      }
      updateState({
        isScraping: false,
        scrapingError: errorMessage
      });
    }
  }, [
    updateState,
    updateAuditProject,
    updateProject,
    projects?.length,
    scrapingInitiated,
    state.isScraping,
    state.dataVersion,
    session?.access_token
  ]);

  const confirmFeedback = useCallback(async (text?: string) => {
    console.log('🔍 [DEBUG] confirmFeedback called with text:', text);
    try {
      if (user?.id) {
        const updates: { feedback_given: boolean; notes?: string } = { feedback_given: true };
        if (text && text.length > 0) {
          updates.notes = text;
        }
        console.log('🔍 [DEBUG] Updating user with:', updates);
        await updateUser(user.id, updates);
        console.log('🔍 [DEBUG] User updated successfully');
      } else {
        console.log('🔍 [DEBUG] No user ID, skipping update');
      }
    } catch (error) {
      console.error('🔍 [DEBUG] Error updating user feedback:', error);
    }
    console.log('🔍 [DEBUG] Setting feedback modal to false (confirmFeedback)');
    setShowFeedbackModal(false);
  }, [updateUser, user?.id]);

  const laterFeedback = useCallback(() => {
    console.log('🔍 [DEBUG] laterFeedback called, setting feedback modal to false');
    setShowFeedbackModal(false);
  }, []);

  // Load project data from database
  const loadProjectData = useCallback(async (skipAutoScraping = false) => {
    if (!projectId) {
      updateState({
        error: 'No project ID provided',
        loading: false
      });
      return;
    }
    
    // Check authentication before loading
    if (!session?.access_token) {
      console.error('❌ Authentication error: No session token available');
      updateState({
        error: 'Authentication required. Please log in again.',
        loading: false
      });
      return;
    }
    
    updateState({
      loading: true,
      error: null
    });
    try {
      // Get project data
      const {
        data: projectData,
        error: projectError
      } = await getAuditProject(projectId);
      if (projectError) {
        // Check if it's an authentication error
        if (projectError.message?.includes('auth') || projectError.message?.includes('session') || projectError.message?.includes('401')) {
          throw new Error('Authentication failed. Please log in again.');
        }
        throw new Error(`Failed to load project: ${projectError.message || 'Unknown error'}`);
      }
      if (!projectData) {
        throw new Error('Project not found');
      }
      updateState({
        project: projectData,
        dataFetched: true,
        lastFetchTime: Date.now(),
        loading: false
      });

      // Always try to load scraped pages if project exists
      if (projectData) {
        await loadScrapedPages();
      }

      // If project is pending and has no data, start scraping
      if (projectData.status === 'pending' && !skipAutoScraping && !scrapingInitiated) {
        await startScraping(projectData);
      }
    } catch (error) {
      console.error('❌ Error loading project data:', error);
      let errorMessage = 'Failed to load project';
      if (error instanceof Error) {
        errorMessage = error.message;
        // Check if it's an authentication-related error
        if (error.message.toLowerCase().includes('auth') || 
            error.message.toLowerCase().includes('session') || 
            error.message.toLowerCase().includes('401') ||
            error.message.toLowerCase().includes('unauthorized')) {
          errorMessage = 'Authentication failed. Please log in again.';
        }
      }
      updateState({
        error: errorMessage,
        loading: false
      });
    }
  }, [projectId, getAuditProject, startScraping, updateState, loadScrapedPages, scrapingInitiated, session]);

  // Handle section change
  const handleSectionChange = useCallback((section: string) => {
    updateState({
      activeSection: section
    });
  }, [updateState]);

  // Refresh data
  const refreshData = useCallback(async (forceRefresh = false) => {
    if (!projectId || state.isRefreshing) return;
    const now = Date.now();
    const timeSinceLastFetch = now - state.lastFetchTime;
    const REFRESH_THRESHOLD = 10 * 1000; // 10 seconds

    if (!forceRefresh && timeSinceLastFetch < REFRESH_THRESHOLD) {
      return;
    }
    updateState({
      isRefreshing: true
    });
    await loadProjectData(true); // Skip auto-scraping on refresh
    updateState({
      isRefreshing: false
    });
  }, [projectId, state.isRefreshing, state.lastFetchTime, loadProjectData, updateState]);

  // Initial load - prevent double execution in React Strict Mode
  useEffect(() => {
    // Prevent double execution using ref (more reliable than state)
    if (initializationRef.current) {
      return;
    }
    initializationRef.current = true;

    // Use cached data if available
    if (cachedData) {
      updateState({
        project: cachedData.project,
        scrapedPages: cachedData.scrapedPages,
        loading: false,
        error: null,
        dataFetched: true,
        lastFetchTime: cachedData.lastFetchTime
      });
      return;
    }
    loadProjectData();
  }, [projectId, cachedData, loadProjectData, updateState]);

  // Cleanup effect to reset initialization ref when component unmounts
  useEffect(() => {
    return () => {
      initializationRef.current = false;
    };
  }, []);
  return {
    state,
    updateState,
    loadProjectData,
    loadScrapedPages,
    refreshData,
    handleSectionChange,
    startScraping,
    showFeedbackModal,
    confirmFeedback,
    laterFeedback
  };
}

'use client';

import { motion, AnimatePresence } from 'framer-motion';
import { useRouter } from 'next/navigation';
import Image from 'next/image';
import Link from 'next/link';
import { useSupabase } from '@/contexts/SupabaseContext';
import { useState, useEffect, useCallback, useMemo } from 'react';
import { roleVerifier } from '@/lib/role-utils';
import { useUserPlan } from '@/hooks/useUserPlan';
interface DashboardSidebarProps {
  isOpen: boolean;
  onClose: () => void;
  activeTab: string;
  onTabChange: (tab: string) => void;
  userProfile: {
    id: string;
    email: string;
    first_name: string | null;
    last_name: string | null;
    role: string;
    email_confirmed: boolean;
    created_at: string;
  } | null;
  selectedProjectId?: string | null;
}
export default function DashboardSidebar({
  isOpen,
  onClose,
  activeTab,
  onTabChange,
  userProfile,
  selectedProjectId
}: DashboardSidebarProps) {
  const {
    signOut,
    user
  } = useSupabase();
  const router = useRouter();
  const [isAdmin, setIsAdmin] = useState<boolean | null>(null);
  const [roleLoading, setRoleLoading] = useState(true);
  const [displayName, setDisplayName] = useState<string>('');
  const [userInitial, setUserInitial] = useState<string>('U');

  // Get user plan information
  const {
    planInfo,
    loading: planLoading,
    refreshPlan
  } = useUserPlan();

  // Real-time role verification
  const verifyRole = useCallback(async () => {
    if (!user) {
      setIsAdmin(false);
      setRoleLoading(false);
      return;
    }
    try {
      setRoleLoading(true);
      const result = await roleVerifier.verifyUserRole(user.id, false); // Use cache if available
      const adminStatus = result.isAdmin && result.verified;
      setIsAdmin(adminStatus);
    } catch (error) {
      console.error('Sidebar role verification error:', error);
      setIsAdmin(false);
    } finally {
      setRoleLoading(false);
    }
  }, [user]);
  useEffect(() => {
    verifyRole();
  }, [verifyRole]);

  // Update display name when userProfile or user changes
  useEffect(() => {
    // Priority 1: Check userProfile first_name and last_name
    if (userProfile?.first_name && userProfile?.last_name) {
      const fullName = `${userProfile.first_name} ${userProfile.last_name}`;
      setDisplayName(fullName);
      setUserInitial(userProfile.first_name[0].toUpperCase());
    } else if (userProfile?.first_name) {
      setDisplayName(userProfile.first_name);
      setUserInitial(userProfile.first_name[0].toUpperCase());
    } else if (userProfile?.last_name) {
      setDisplayName(userProfile.last_name);
      setUserInitial(userProfile.last_name[0].toUpperCase());
    } 
    // Priority 2: Check Google user metadata (full_name or name)
    else if (user?.user_metadata?.full_name) {
      const googleName = user.user_metadata.full_name;
      setDisplayName(googleName);
      setUserInitial(googleName.trim()[0].toUpperCase());
    } else if (user?.user_metadata?.name) {
      const googleName = user.user_metadata.name;
      setDisplayName(googleName);
      setUserInitial(googleName.trim()[0].toUpperCase());
    }
    // Priority 3: Fall back to email trimming
    else if (userProfile?.email) {
      setDisplayName(userProfile.email.split('@')[0]);
      setUserInitial(userProfile.email[0].toUpperCase());
    } else if (user?.email) {
      setDisplayName(user.email.split('@')[0]);
      setUserInitial(user.email[0].toUpperCase());
    } else {
      setDisplayName('User');
      setUserInitial('U');
    }
  }, [userProfile, user]);

  // Refresh plan information when user changes
  const handlePlanRefresh = useCallback(() => {
    if (user && refreshPlan) {
      refreshPlan();
    }
  }, [user, refreshPlan]);
  useEffect(() => {
    handlePlanRefresh();
  }, [handlePlanRefresh]);

  // Debug plan information (only log when plan info actually changes)
  useEffect(() => {
    if (planInfo) {}
  }, [planInfo, planLoading, user?.id]);

  // Memoize navigation items to prevent re-creation on every render
  const navigationItems = useMemo(() => {
    const baseItems = [{
      id: 'dashboard',
      name: 'Dashboard',
