    if (activeTab === 'analysis' && selectedProjectId) {
      baseItems.push({
        id: 'analysis',
        name: 'Analysis',
        icon: <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
