}

'use client'

import { motion } from 'framer-motion'
import { useState, useEffect } from 'react'
import { supabase } from '@/lib/supabase-client'
import { roleVerifier, roleTester, RoleVerificationResult } from '@/lib/role-utils'
import AdminOverview from './admin-subtabs/AdminOverview'
import AdminUsers from './admin-subtabs/AdminUsers'
import AdminPlans from './admin-subtabs/AdminPlans'
import AdminFeatureManagement from './admin-subtabs/AdminFeatureManagement'
import AdminSubscription from './admin-subtabs/AdminSubscription'
import AdminAlerts from './admin-subtabs/AdminAlerts'
import AdminSupport from './admin-subtabs/AdminSupport'
import AdminEmailManagement from './admin-subtabs/AdminEmailManagement'
import AdminBlogEditor from './admin-subtabs/AdminBlogEditor'

interface UserProfile {
  id: string
  email: string
  first_name: string | null
  last_name: string | null
  role: 'user' | 'admin'
  email_confirmed: boolean
  created_at: string
}

interface AdminTabProps {
  userProfile: UserProfile
}

type AdminTabType =
  | 'overview'
  | 'users'
  | 'plans'
  | 'features'
  | 'subscription'
  | 'revenue'
  | 'alerts'
  | 'support'
  | 'email'
  | 'blogs'

export default function AdminTab({ userProfile }: AdminTabProps) {
  const [isAdminVerified, setIsAdminVerified] = useState<boolean | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [_roleVerificationResult, setRoleVerificationResult] = useState<RoleVerificationResult | null>(null)
  const [verificationError, setVerificationError] = useState<string | null>(null)
  const [activeTab, setActiveTab] = useState<AdminTabType>('overview')

  // Enhanced admin role verification
  useEffect(() => {
    const verifyAdminRole = async () => {
      try {
        setIsLoading(true)
        setVerificationError(null)

        // Get current user
        const { data: { user }, error: userError } = await supabase.auth.getUser()
        if (userError || !user) {
          console.error('Auth user error:', userError)
          setVerificationError('Authentication failed')
          setIsAdminVerified(false)
          return
        }

        // Use the enhanced role verification system
        const result = await roleVerifier.verifyUserRole(user.id, true)
        setRoleVerificationResult(result)
        if (!result.verified) {
          console.error('Role verification failed:', result.error)
          setVerificationError(result.error || 'Role verification failed')
          setIsAdminVerified(false)
          return
        }

        // Test admin access specifically
        const adminTest = await roleTester.testAdminAccess(user.id)
        setIsAdminVerified(adminTest.hasAccess)
        if (!adminTest.hasAccess) {
          setVerificationError(`Access denied. User role: ${result.role}`)
        }
      } catch (error) {
        console.error('Error verifying admin role:', error)
        setVerificationError(`Unexpected error: ${error}`)
        setIsAdminVerified(false)
      } finally {
        setIsLoading(false)
      }
    }
    verifyAdminRole()
  }, [])

  const tabs = [
    { id: 'overview', label: 'Overview' },
    { id: 'users', label: 'Users' },
    { id: 'plans', label: 'Plans & Usage' },
    { id: 'features', label: 'Feature Management' },
    { id: 'subscription', label: 'Subscription' },
    { id: 'alerts', label: 'Alerts' },
    { id: 'support', label: 'Support' },
    { id: 'email', label: 'Email Management' },
    { id: 'blogs', label: 'Blog Editor' }
  ]

  const renderTabContent = () => {
    switch (activeTab) {
      case 'overview':
        return <AdminOverview userProfile={userProfile} />
      case 'users':
        return <AdminUsers userProfile={userProfile} />
      case 'plans':
        return <AdminPlans userProfile={userProfile} />
      case 'features':
        return <AdminFeatureManagement userProfile={userProfile} />
      case 'subscription':
        return <AdminSubscription userProfile={userProfile} />
     
      case 'alerts':
        return <AdminAlerts userProfile={userProfile} />
      case 'support':
        return <AdminSupport userProfile={userProfile} />
      case 'email':
        return <AdminEmailManagement userProfile={userProfile} />
      case 'blogs':
        return <AdminBlogEditor userProfile={userProfile} />
      default:
        return <AdminOverview userProfile={userProfile} />
    }
  }

  // Show loading state while verifying admin role
  if (isLoading) {
    return (
      <div className="text-center py-12">
        <div className="mx-auto w-24 h-24 bg-[#ff4b01]/20 rounded-full flex items-center justify-center mb-4">
          <svg className="w-12 h-12 text-[#ff4b01] animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
          </svg>
        </div>
        <h2 className="text-2xl font-bold text-black mb-2">Verifying Access</h2>
        <p className="text-gray-600">Checking your admin permissions...</p>
      </div>
    )
  }

  // Check if user is admin (database verified)
  if (!isAdminVerified) {
    return (
      <div className="text-center py-12">
        <div className="mx-auto w-24 h-24 bg-red-100 rounded-full flex items-center justify-center mb-4">
          <svg className="w-12 h-12 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
          </svg>
        </div>
        <h2 className="text-2xl font-bold text-black mb-2">Access Denied</h2>
        <p className="text-gray-600">You don&apos;t have admin permissions to access this panel.</p>
        <p className="text-sm text-gray-500 mt-2">Database verification failed.</p>
        {verificationError && (
          <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded-md">
            <p className="text-sm text-red-600">Error: {verificationError}</p>
      </div>
        )}
            </div>
    )
  }

  return (
    <motion.div
      className="space-y-6 lg:px-6 py-6"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      {/* Header */}
    

      {/* Tab Navigation */}
      <motion.div
        className=" "
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: 0.2 }}
      >
         {/* Welcome Section */}
      <motion.div
        className="pb-4"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: 0.1 }}
      >
        <h1 className="text-2xl font-bold text-black mb-2">
          Welcome back, {userProfile?.first_name || 'Admin'}!
        </h1>
        <p className="text-gray-600">
          Here&apos;s an overview of your system performance and recent activity.
        </p>
      </motion.div>
        <div className="overflow-x-auto ">
          <nav className="-mb-px flex space-x-4 sm:space-x-8 min-w-max">
            {tabs.map((tab) => (
              <motion.button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as AdminTabType)}
                className={`py-2 px-1 border-b-2 font-medium text-sm transition-colors whitespace-nowrap flex-shrink-0 ${
                  activeTab === tab.id
                    ? 'border-[#ff4b01] text-[#ff4b01] bg-[#ff4b01]/10'
                    : 'border-transparent text-gray-500 hover:text-[#ff4b01] hover:border-[#ff4b01]/30'
                }`}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
              >
                {tab.label}
              </motion.button>
            ))}
          </nav>
        </div>
      </motion.div>

      {/* Tab Content */}
      <motion.div
        key={activeTab}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
      >
        {renderTabContent()}
      </motion.div>
    </motion.div>
  )
}

'use client'

// import { motion } from 'framer-motion' // Unused import
import { useState } from 'react'
import { useSupabase } from '@/contexts/SupabaseContext'
import { useUserPlan } from '@/hooks/useUserPlan'
import SiteCrawlForm from '../dashboard-components/SiteCrawlForm'
import { StatsCards, RecentProjects, FeaturesShowcase } from '../dashboard-components'
import UpgradeModal from '../modals/UpgradeModal'
import { useProjectsStore } from '@/lib/stores/projectsStore'

interface UserProfile {
  id: string
  email: string
  first_name: string | null
  last_name: string | null
  role: 'user' | 'admin'
  email_confirmed: boolean
  created_at: string
  updated_at?: string
}

interface DashboardOverviewProps {
  userProfile: UserProfile | null
  onProjectSelect?: (projectId: string) => void
}

interface Feature {
  id: number
  name: string
  description: string
  icon: string
  category: 'Performance' | 'SEO' | 'Security' | 'Accessibility'
}

export default function DashboardOverview({ 
  userProfile, 
  onProjectSelect
}: DashboardOverviewProps) {
  // Use Zustand store for projects data
  const { projects, loading: projectsLoading, error: _projectsError, refreshProjects } = useProjectsStore();
  const { createAuditProject } = useSupabase()
  const { planInfo } = useUserPlan()
  
  // Form submission states
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [submitStatus, setSubmitStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle')
  
  // Upgrade modal states
  const [showUpgradeModal, setShowUpgradeModal] = useState(false)
  const [upgradeModalConfig, setUpgradeModalConfig] = useState<{
    title: string
    description: string
    featureName: string
  }>({
    title: '',
    description: '',
    featureName: ''
  })



  // Test function to check database connection
  const testDatabaseConnection = async () => {
    try {
      
      
      // Use refreshProjects to test connection
      await refreshProjects()
      
      return true
    } catch (error) {
      console.error('Database connection test error:', error)
      return false
    }
  }


  // Handle form submission from SiteCrawlForm
  const handleFormSubmit = async (formData: {
    siteUrl: string
    pageType: 'single' | 'multiple'
    brandConsistency: boolean
    hiddenUrls: boolean
    keysCheck: boolean
    brandData: {
      companyName: string
      phoneNumber: string
      emailAddress: string
      address: string
      additionalInformation: string
    }
    hiddenUrlsList: Array<{ id: string; url: string }>
  }) => {
    
    setIsSubmitting(true)
    setSubmitStatus('submitting')
    
    try {
      // Test database connection first
      
      const dbConnected = await testDatabaseConnection()
      
      
      if (!dbConnected) {
        console.warn('⚠️ Database connection test failed, but continuing with form submission...')
      } else {
        
      }

      // Ensure the URL has https:// protocol
      
      let formattedUrl = formData.siteUrl.trim()
      
      if (!formattedUrl.startsWith('http://') && !formattedUrl.startsWith('https://')) {
        formattedUrl = `https://${formattedUrl}`
        
      } else {
        
      }
      
      // Prepare the project data
      
      const projectData = {
        site_url: formattedUrl,
        page_type: formData.pageType,
        brand_consistency: formData.brandConsistency,
        hidden_urls: formData.hiddenUrls,
        keys_check: formData.keysCheck,
        brand_data: formData.brandConsistency ? formData.brandData : null,
        hidden_urls_data: formData.hiddenUrls ? formData.hiddenUrlsList.filter(url => url.url.trim() !== '') : null,
        status: 'pending' as const,
        progress: 0,
        score: 0,
        issues_count: 0,
        total_pages: 0,
        total_links: 0,
        total_images: 0,
        total_meta_tags: 0,
        technologies_found: 0,
        cms_detected: false,
        total_html_content: 0,
        average_html_per_page: 0,
        pages_per_second: 0,
        total_response_time: 0,
        scraping_completed_at: null,
        scraping_data: null,
        // CMS fields
        cms_type: null,
        cms_version: null,
        cms_plugins: null,
        cms_themes: null,
        cms_components: null,
        cms_confidence: 0,
        cms_detection_method: null,
        cms_metadata: null,
        // Technologies fields
        technologies: null,
        technologies_confidence: 0,
        technologies_detection_method: null,
        technologies_metadata: null,
        // PageSpeed Insights fields
        pagespeed_insights_data: null,
        pagespeed_insights_loading: false,
        pagespeed_insights_error: null,
        // SEO Analysis fields
        seo_analysis: null,
        // Meta tags fields
        meta_tags_data: null,
        social_meta_tags_data: null,
        // Keys detection fields
        detected_keys: null
      }

      

      // Create the audit project
      
      const { data: createdProject, error: projectError } = await createAuditProject(projectData)
      
      if (projectError) {
        // Handle empty error object first - show modal, no error logging
        if (!projectError.message && !projectError.code && Object.keys(projectError).length === 0) {
          setUpgradeModalConfig({
            title: 'Project Limit Reached',
            description: 'You may have reached your project limit. Please upgrade your plan to create more projects.',
            featureName: 'project_limit'
          })
          setShowUpgradeModal(true)
          return
        }
        
        setSubmitStatus('error')
        
        // Handle specific error codes
        if (projectError.code === 'PROJECT_LIMIT_REACHED') {
          setUpgradeModalConfig({
            title: 'Project Limit Reached',
            description: projectError.message || 'You have reached your project limit. Upgrade to create more projects.',
            featureName: 'project_limit'
          })
          setShowUpgradeModal(true)
        } else if (projectError.code === 'FEATURE_NOT_AVAILABLE') {
          setUpgradeModalConfig({
            title: 'Feature Not Available',
            description: projectError.message || 'This feature is not available in your current plan.',
            featureName: 'full_site_crawl'
          })
          setShowUpgradeModal(true)
        } else if (projectError.code === 'RLS_POLICY_ISSUE') {
          alert(`Database permission issue: ${projectError.message}. Please contact support.`)
        } else if (projectError.code === 'TABLE_NOT_EXISTS') {
          alert(`Database setup issue: ${projectError.message}. Please contact support.`)
        } else {
          // For other errors, show a simple alert
          alert(`Failed to create project: ${projectError.message || 'Please try again.'}`)
        }
        return
      }

      if (!createdProject) {
        console.error('❌ No project created')
        setSubmitStatus('error')
        alert('Failed to create project. Please try again.')
        return
      }

      
      setSubmitStatus('success')
      
      // Refresh projects data to show the new project
      await refreshProjects()
      
      // Redirect to analysis tab immediately
      
      if (onProjectSelect) {
        onProjectSelect(createdProject.id)
      }
      
    } catch (error) {
      console.error('❌ Unexpected error in form submission:', error)
      setSubmitStatus('error')
      alert(`An unexpected error occurred: ${error}`)
    } finally {
      
      setIsSubmitting(false)
      // Reset status after 3 seconds
      setTimeout(() => {
        setSubmitStatus('idle')
      }, 3000)
    }
  }


  return (
    <div className="m lg:px-8 py-8 space-y-8">
      {/* Welcome Section */}
      <div className="mb-4">
        <h1 className="text-2xl sm:text-3xl font-bold text-black mb-2">
          Welcome back, {userProfile?.first_name || 'User'}!
        </h1>
        <p className="text-gray-600 text-sm sm:text-base">
          Here&apos;s what&apos;s happening with your web audits today.
        </p>
      </div>

      {/* Main Content Row - Site Crawl and Stats Cards */}
      <div className="flex flex-col lg:flex-row gap-6 lg:items-stretch">
        {/* Site Crawl Form - Takes full width on mobile, 2/3 width on lg+ */}
        <div className="w-full lg:w-[70%]">
          <SiteCrawlForm 
            onSubmit={handleFormSubmit}
            isSubmitting={isSubmitting}
            submitStatus={submitStatus}
          />
        </div>
        {/* Stats Cards - Takes full width on mobile, 1/3 width on lg+ */}
        <div className="w-full lg:w-[30%]">
          <StatsCards 
            projects={projects}
            projectsLoading={projectsLoading}
          />
        </div>
      </div>

      {/* Recent Projects */}
      <div className="mt-8">
        <RecentProjects 
          onProjectSelect={onProjectSelect}
        />
      </div>
      {/* Features Showcase */}
      {/* <FeaturesShowcase features={features} /> */}

      {/* Upgrade Modal */}
      <UpgradeModal
        isOpen={showUpgradeModal}
        onClose={() => setShowUpgradeModal(false)}
        title={upgradeModalConfig.title}
        description={upgradeModalConfig.description}
        featureName={upgradeModalConfig.featureName}
        currentPlan={planInfo ? {
          name: planInfo.plan_name,
          type: planInfo.plan_type,
          maxProjects: planInfo.max_projects,
          currentProjects: planInfo.current_projects
        } : undefined}
      />
    </div>
  )
}

'use client'

import { useState, useEffect, useMemo, useCallback } from 'react'
import { useSupabase } from '@/contexts/SupabaseContext'
import { AuditProject } from '@/types/audit'
import { GeminiAnalysisResult } from '@/lib/gemini'
import AnalysisHeader from '../analysis-tab-components/AnalysisHeader'
import { useUserPlan } from '@/hooks/useUserPlan'
import FeatureUnavailableCard from '../FeatureUnavailableCard'
import {
  OverviewTab,
  GrammarContentTab,
  BrandConsistencyTab,
  UIQualityTab,
  TechnicalTab,
  PerformanceTab,
  AccessibilityTab
} from '../page-analysis-components'
import SEOAnalysisSection from '../analysis-tab-components/SEOAnalysisSection'
import ImagesSection from '../analysis-tab-components/ImagesSection'
import LinksSection from '../analysis-tab-components/LinksSection'

// Brand consistency data interface
interface BrandConsistencyData {
  companyName: string;
  phoneNumber: string;
  emailAddress: string;
  address: string;
  additionalInformation: string;
}

interface PageAnalysisTabProps {
  pageId: string
}

interface PageData {
  id: string
  audit_project_id: string
  user_id: string
  url: string
  status_code: number | null
  title: string | null
  description: string | null
  html_content: string | null
  filtered_content?: string | null
  html_content_length: number | null
  links_count: number
  images_count: number
  links: Array<{url: string, text: string, isExternal: boolean}> | null
  images: Array<{src: string, alt?: string, title?: string}> | null
  meta_tags_count: number
  technologies_count: number
  technologies: string[] | null
  cms_type: string | null
  cms_version: string | null
  cms_plugins: string[] | null
  social_meta_tags: Record<string, string> | null
  social_meta_tags_count: number
  is_external: boolean
  response_time: number | null
  performance_analysis: Record<string, unknown> | undefined
  gemini_analysis?: GeminiAnalysisResult | null
  created_at: string
  updated_at: string
}

interface ProjectWithBrandData extends Omit<AuditProject, 'brand_data'> {
  brand_data: BrandConsistencyData | null;
  brand_consistency?: boolean;
}

export default function PageAnalysisTab({ pageId }: PageAnalysisTabProps) {
  const { getScrapedPage, getAuditProject } = useSupabase()
  const { hasFeature } = useUserPlan()
  const [activeTab, setActiveTab] = useState('overview')
  const [page, setPage] = useState<PageData | null>(null)
  const [project, setProject] = useState<ProjectWithBrandData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Grammar analysis state - moved to parent to persist across tab changes
  const [grammarAnalysis, setGrammarAnalysis] = useState<GeminiAnalysisResult | null>(null)
  const [grammarAnalysisError, setGrammarAnalysisError] = useState<string | null>(null)
  const [isGrammarAnalyzing, setIsGrammarAnalyzing] = useState(false)

  // Memoize cached analysis to prevent unnecessary re-renders
  const cachedAnalysis = useMemo((): GeminiAnalysisResult | undefined => {
    const analysis = page?.gemini_analysis || grammarAnalysis
    return analysis as GeminiAnalysisResult | undefined
  }, [page?.gemini_analysis, grammarAnalysis])

  // Function to start grammar analysis
  const startGrammarAnalysis = useCallback(async () => {
    if (!page?.id || !page?.url || !page?.html_content) return;

    setIsGrammarAnalyzing(true);
    setGrammarAnalysisError(null);

    try {
      const response = await fetch('/api/gemini-analysis-stream', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          pageId: page.id,
          content: page.filtered_content || page.html_content,
          url: page.url,
          userId: null // Will be handled by the API
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Analysis failed');
      }

      // Check if it's a cached response (immediate JSON)
      const contentType = response.headers.get('content-type');
      if (contentType?.includes('application/json')) {
        const data = await response.json();
        setGrammarAnalysis(data.analysis);
        setIsGrammarAnalyzing(false);
        return;
      }

      // Handle streaming response
      const reader = response.body?.getReader();
      if (!reader) {
        throw new Error('No response body');
      }

      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();

        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            try {
              const data = JSON.parse(line.slice(6));

              if (data.status === 'completed' && data.analysis) {
                setGrammarAnalysis(data.analysis);
                setIsGrammarAnalyzing(false);
                return;
              }

              if (data.status === 'error') {
                throw new Error(data.error || 'Analysis failed');
              }
            } catch (parseError) {
              console.error('Error parsing stream data:', parseError);
            }
          }
        }
      }
    } catch (error) {
      console.error('Error in grammar analysis:', error);
      setGrammarAnalysisError(error instanceof Error ? error.message : 'Analysis failed');
      setIsGrammarAnalyzing(false);
    }
  }, [page?.id, page?.url, page?.html_content]);

  // Auto-start grammar analysis when page data is loaded
  useEffect(() => {
    // Only start analysis if:
    // 1. Page data is available
    // 2. No analysis exists yet (neither cached nor in progress)
    // 3. Not currently analyzing
    // 4. No previous error (to prevent infinite retries on API failures)
    // 5. User has feature access
    if (page?.id && page?.url && page?.html_content && 
        !page?.gemini_analysis && 
        !grammarAnalysis && 
        !isGrammarAnalyzing &&
        !grammarAnalysisError) {
      // Check if user has access to grammar content analysis
      if (hasFeature('grammar_content_analysis')) {
        startGrammarAnalysis();
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page?.id, page?.url, page?.html_content, page?.gemini_analysis, grammarAnalysis, isGrammarAnalyzing, grammarAnalysisError]);

  useEffect(() => {
    const loadData = async () => {
      try {
        setLoading(true)

        // Verify context methods are available
        if (!getScrapedPage || !getAuditProject) {
          throw new Error('Supabase context methods not available. Please check if user is authenticated.')
        }

        // Load page data
        const { data: pageData, error: pageError } = await getScrapedPage(pageId)
        if (pageError) {
          console.error('Error fetching scraped page:', pageError)
          throw pageError
        }
        if (!pageData) throw new Error('Page not found')

        setPage({
          ...pageData,
          images: (pageData as any).images || null
        } as PageData)

        // Load project data
        if (pageData.audit_project_id) {
          const { data: projectData, error: projectError } = await getAuditProject(pageData.audit_project_id)

          if (projectError) {
            console.error('Error fetching audit project:', projectError)
          }
          if (!projectError && projectData) {
            setProject(projectData as ProjectWithBrandData)
          }
        }

      } catch (err) {
        console.error('Error loading page data:', err)
        setError(err instanceof Error ? err.message : 'Failed to load page')
      } finally {
        setLoading(false)
      }
    }

    if (pageId) {
      loadData()
    }
  }, [pageId, getScrapedPage, getAuditProject])

  // Check if user has access to a specific tab
  const hasAccessToTab = (tabId: string): boolean => {
    const featureMap: Record<string, string> = {
      'overview': 'single_page_crawl', // Basic overview is available to all
      'links': 'link_scanner',
      'images': 'image_scan',
      'grammar-content': 'grammar_content_analysis',
      'brand-consistency': 'brand_consistency_check',
      'seo-structure': 'seo_structure',
      'ui-quality': 'ui_ux_quality_check',
      'technical': 'technical_analysis',
      'performance': 'performance_metrics',
      'accessibility': 'accessibility_audit'
    }

    const featureId = featureMap[tabId]
    if (!featureId) return true // Show tabs that don't require specific features

    // Special case for brand-consistency: check both plan feature access AND project brand_consistency column
    if (tabId === 'brand-consistency') {
      const hasPlanAccess = hasFeature(featureId)
      const hasProjectAccess = project?.brand_consistency === true
      return hasPlanAccess && hasProjectAccess
    }

    return hasFeature(featureId)
  }

  // Get tab information for unavailable cards
  const getTabInfo = (tabId: string) => {
    const tabInfoMap: Record<string, { title: string; description: string }> = {
      'overview': {
        title: 'Overview Analysis',
        description: 'This feature is not available in your current plan. Upgrade to access comprehensive page overview and insights.'
      },
      'links': {
        title: 'Link Scanner',
        description: 'This feature is not available in your current plan. Upgrade to access link validation and broken link detection.'
      },
      'images': {
        title: 'Image Analysis',
        description: 'This feature is not available in your current plan. Upgrade to access image optimization analysis and recommendations.'
      },
      'grammar-content': {
        title: 'Grammar & Content Analysis',
        description: 'This feature is not available in your current plan. Upgrade to access AI-powered grammar and content analysis.'
      },
      'brand-consistency': {
        title: 'Brand Consistency Analysis',
        description: 'This feature is not available in your current plan. Upgrade to access brand consistency analysis and guidelines checking.'
      },
      'seo-structure': {
        title: 'SEO & Structure Analysis',
        description: 'This feature is not available in your current plan. Upgrade to access comprehensive SEO structure analysis.'
      },
      'ui-quality': {
        title: 'UI/UX Quality Check',
        description: 'This feature is not available in your current plan. Upgrade to access UI/UX quality analysis and recommendations.'
      },
      'technical': {
        title: 'Technical Analysis',
        description: 'This feature is not available in your current plan. Upgrade to access comprehensive technical audit and recommendations.'
      },
      'performance': {
        title: 'Performance Metrics',
        description: 'This feature is not available in your current plan. Upgrade to access detailed performance analysis and PageSpeed Insights.'
      },
      'accessibility': {
        title: 'Accessibility Audit',
        description: 'This feature is not available in your current plan. Upgrade to access comprehensive accessibility compliance checking.'
      }
    }
    return tabInfoMap[tabId] || {
      title: 'Feature Unavailable',
      description: 'This feature is not available in your current plan. Upgrade to access this functionality.'
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center overflow-x-hidden w-[100vw]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#ff4b01] mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading page analysis...</p>
        </div>
      </div>
    )
  }

  if (error || !page) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="text-red-500 text-xl mb-4">❌</div>
          <p className="text-gray-600">{error || 'Page not found'}</p>
        </div>
      </div>
    )
  }

  // Create a mock project object for the AnalysisHeader
  const mockProject: AuditProject = project ? {
    ...project,
    score: 85, // You can calculate this based on page analysis
    status: 'completed' as const,
    brand_data: project.brand_data ?? null
  } : {
    id: 'mock',
    site_url: page?.url || 'Unknown URL',
    status: 'completed' as const,
    score: 85,
    progress: 100,
    last_audit_at: new Date().toISOString(),
    issues_count: 0,
    total_pages: 1,
    total_links: 0,
    total_images: 0,
    total_meta_tags: 0,
    technologies_found: 0,
    cms_detected: false,
    cms_type: null,
    cms_version: null,
    cms_plugins: null,
    cms_themes: null,
    cms_components: null,
    cms_confidence: 0,
    cms_detection_method: null,
    cms_metadata: null,
    technologies: null,
    technologies_confidence: 0,
    technologies_detection_method: null,
    technologies_metadata: null,
    total_html_content: 0,
    average_html_per_page: 0,
    pagespeed_insights_data: null,
    pagespeed_insights_loading: false,
    pagespeed_insights_error: null,
    scraping_data: null,
    seo_analysis: null,
    meta_tags_data: null,
    social_meta_tags_data: null,
    detected_keys: null,
    brand_data: null,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  }

  const renderActiveTab = () => {
    // Check if user has access to the current tab
    if (!hasAccessToTab(activeTab)) {
      const tabInfo = getTabInfo(activeTab)
      return (
        <FeatureUnavailableCard
          title={tabInfo.title}
          description={tabInfo.description}
        />
      )
    }

    // Create a mock scrapedPages array with the current page for the sections
    const scrapedPages = page ? [page] : []

    // Convert ProjectWithBrandData to AuditProject for components that require it
    const auditProject: AuditProject | null = project ? {
      ...project,
      brand_data: project.brand_data ?? null
    } : null;

    switch (activeTab) {
      case 'overview':
        return <OverviewTab page={page} project={auditProject} />
      case 'links':
        return <LinksSection project={mockProject} scrapedPages={scrapedPages} originalScrapingData={undefined} />
      case 'images':
        return <ImagesSection project={mockProject} scrapedPages={scrapedPages} originalScrapingData={undefined} />
      case 'grammar-content':
        return (
          <GrammarContentTab
            page={{
              id: page.id,
              url: page.url,
              html_content: page.html_content,
              filtered_content: page.filtered_content,
              gemini_analysis: page.gemini_analysis as GeminiAnalysisResult | null
            }}
            cachedAnalysis={cachedAnalysis}
            grammarAnalysis={grammarAnalysis}
            grammarAnalysisError={grammarAnalysisError}
            isGrammarAnalyzing={isGrammarAnalyzing}
            onReAnalyze={startGrammarAnalysis}
          />
        )
      case 'brand-consistency':

        // Test: Try to create a project with brand data to see if it works
        if (!project?.brand_data) {

          // This is just for debugging - we'll remove this later
        }

        return (
          <BrandConsistencyTab
            page={page!}
            projectBrandData={project?.brand_data as BrandConsistencyData | null | undefined}
            onBrandDataUpdate={(newBrandData) => {
              // Update the project state with new brand data
              setProject(prev => prev ? { ...prev, brand_data: newBrandData as BrandConsistencyData } : null);
            }}
          />
        )
      case 'seo-structure':
        return <SEOAnalysisSection page={page!} isPageAnalysis={true} cachedAnalysis={null} />
      case 'ui-quality':
        return <UIQualityTab page={page!} />
      case 'technical':
        return <TechnicalTab page={page!} />
      case 'performance':
        return page ? <PerformanceTab page={{...page, html_content: page.html_content || undefined, images: Array.isArray(page.images) ? page.images.map(() => ({ size: 0, loading: 'lazy', format: 'unknown' })) : undefined, response_time: page.response_time || undefined, html_content_length: page.html_content_length || undefined, performance_analysis: undefined}} cachedAnalysis={undefined} /> : null
      case 'accessibility':
        return page ? <AccessibilityTab page={page} /> : null
      default:
        return <OverviewTab page={page} project={auditProject} />
    }
  }

  // Map page analysis tabs to the AnalysisHeader format
  const pageAnalysisTabs = [
    { id: 'overview', name: 'Overview', icon: '📊' },
    { id: 'links', name: 'Links', icon: '🔗' },
    { id: 'images', name: 'Images', icon: '🖼️' },
    { id: 'grammar-content', name: 'Grammar & Content', icon: '📝' },
    // Only include brand-consistency tab if project has brand_consistency enabled
    ...(project?.brand_consistency === true ? [{ id: 'brand-consistency', name: 'Brand Consistency', icon: '🎯' }] : []),
    { id: 'seo-structure', name: 'SEO & Structure', icon: '🔍' },
    { id: 'ui-quality', name: 'UI Quality', icon: '🎨' },
    { id: 'technical', name: 'Technical', icon: '⚙️' },
    { id: 'performance', name: 'Performance', icon: '⚡' },
    { id: 'accessibility', name: 'Accessibility', icon: '♿' }
  ]

  return (
    <div className="space-y-6 lg:px-6">
      {/* Use AnalysisHeader for consistent design */}
      <AnalysisHeader
        project={mockProject}
        activeSection={activeTab}
        onSectionChange={setActiveTab}
        customTabs={pageAnalysisTabs}
        pageTitle={page?.title || 'Untitled Page'}
        showUnavailableContent={false}
      />

      {/* Tab Content */}
      <div className="min-h-96">
        {renderActiveTab()}
      </div>
    </div>
  )
}

'use client';

import { motion, AnimatePresence } from 'framer-motion';
import { useEffect, useState, useRef } from 'react';
import Image from 'next/image';
import { AuditProject } from '@/types/audit';
import { ProjectCardSkeleton, StatsCardSkeleton } from '../SkeletonLoader';
import EditProjectModal from '../modals/EditProjectModal';
import { useProjectsStore } from '@/lib/stores/projectsStore';
import FaviconDisplay from '../FaviconDisplay';
interface BrandConsistencyData {
  companyName: string;
  phoneNumber: string;
  emailAddress: string;
  address: string;
  additionalInformation: string;
}
interface HiddenUrl {
  id: string;
  url: string;
}
interface ProjectsTabProps {
  userProfile: unknown;
  onProjectSelect?: (projectId: string) => void;
  onUpdateProject?: (projectId: string, data: {
    siteUrl: string;
    pageType: 'single' | 'multiple';
    brandConsistency: boolean;
    hiddenUrls: boolean;
    keysCheck: boolean;
    brandData: BrandConsistencyData;
    hiddenUrlsList: HiddenUrl[];
  }) => Promise<void>;
  onDeleteProject?: (projectId: string) => Promise<void>;
  onRecrawlProject?: (projectId: string) => Promise<void>;
}
export default function ProjectsTab({
  onProjectSelect,
  onUpdateProject,
  onDeleteProject,
  onRecrawlProject
}: Omit<ProjectsTabProps, 'userProfile'>) {
  // Use Zustand store for projects data
  const { projects, loading: projectsLoading, error: projectsError, refreshProjects } = useProjectsStore();
  const [expandedCards, setExpandedCards] = useState<Set<string>>(new Set());
  const previousProjectsRef = useRef<AuditProject[]>([]);
  const [editModalOpen, setEditModalOpen] = useState(false);
  const [selectedProject, setSelectedProject] = useState<AuditProject | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [projectToDelete, setProjectToDelete] = useState<string | null>(null);

  // Load projects when component mounts
  useEffect(() => {
    refreshProjects();
  }, [refreshProjects]);

  // Zustand store automatically handles status updates - no need for manual monitoring

  // Performance tracking
  useEffect(() => {
    if (projectsLoading) {} else if (projectsError) {} else if (projects.length === 0) {} else {
      // Use requestAnimationFrame to measure after DOM updates
      requestAnimationFrame(() => {
        // Performance tracking logic can be added here if needed
      });
    }
  }, [projectsLoading, projectsError, projects.length]);
  const toggleCardExpansion = (projectId: string) => {
    setExpandedCards(prev => {
      const newSet = new Set(prev);
      if (newSet.has(projectId)) {
        newSet.delete(projectId);
      } else {
        newSet.add(projectId);
      }
      return newSet;
    });
  };
  const handleEditProject = (project: AuditProject) => {
    setSelectedProject(project);
    setEditModalOpen(true);
  };
  const handleSaveProject = async (projectId: string, data: {
    siteUrl: string;
    pageType: 'single' | 'multiple';
    brandConsistency: boolean;
    hiddenUrls: boolean;
    keysCheck: boolean;
    brandData: BrandConsistencyData;
    hiddenUrlsList: HiddenUrl[];
  }) => {
    if (!onUpdateProject) {
      return;
    }
    setIsSubmitting(true);
    try {
      await onUpdateProject(projectId, data);
      setEditModalOpen(false);
      setSelectedProject(null);
      await refreshProjects();
    } catch (error) {
      console.error('ProjectsTab: Error updating project:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  // Removed unused handleRecrawlProject function

  const handleDeleteProject = (projectId: string) => {
    setProjectToDelete(projectId);
    setDeleteConfirmOpen(true);
  };
  const confirmDeleteProject = async () => {
    if (!onDeleteProject || !projectToDelete) return;
    try {
      await onDeleteProject(projectToDelete);
      await refreshProjects();
      setDeleteConfirmOpen(false);
      setProjectToDelete(null);
    } catch (error) {
      console.error('Error deleting project:', error);
    }
  };
  const cancelDeleteProject = () => {
    setDeleteConfirmOpen(false);
    setProjectToDelete(null);
  };
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed':
        return 'bg-[#ff4b01]/10 text-[#ff4b01] border border-[#ff4b01]/30';
      case 'in_progress':
        return 'bg-[#ff4b01]/10 text-[#ff4b01] border border-[#ff4b01]/30';
      case 'pending':
        return 'bg-gray-50 text-gray-700 border border-gray-200';
      case 'failed':
        return 'bg-gray-50 text-gray-700 border border-gray-200';
      default:
        return 'bg-gray-50 text-gray-700 border border-gray-200';
    }
  };
  const getStatusDisplayName = (status: string) => {
    switch (status) {
      case 'completed':
        return 'Completed';
      case 'in_progress':
        return 'In Progress';
      case 'pending':
        return 'Pending';
      case 'failed':
        return 'Failed';
      default:
        return status;
    }
  };
  const getProjectName = (siteUrl: string) => {
    try {
      const url = new URL(siteUrl);
      return url.hostname.replace('www.', '');
    } catch {
      return siteUrl;
    }
  };
  const formatDate = (dateString: string | null) => {
    if (!dateString) return 'Never';
    const date = new Date(dateString);
    return date.toLocaleDateString();
  };

