        error
      );

      return {
        data: null,

        error,
      };
    }
  };

  const getAuditProjects = async (user: User | null) => {
    if (!user) {
      return {
        data: null,

        error: {
          message: "No user logged in",
        },
      };
    }

    try {
      const {
        data,

        error,
