            meta_tags_data,

            social_meta_tags_data,

            detected_keys

          `
        )
        .eq("user_id", user.id)
        .order("created_at", {
          ascending: false,
        });

      // If query fails with column error, retry without optional fields
      // Handle various error codes: PGRST116 (column doesn't exist), 42703 (PostgreSQL undefined column), or 400 with column error message
      const isColumnError = error && (
        error.code === 'PGRST116' || 
        error.code === '42703' ||
        error.code === 'P0001' ||
        (error.message?.toLowerCase().includes('column') || 
         error.message?.toLowerCase().includes('does not exist') ||
         error.message?.toLowerCase().includes('unknown column') ||
         error.message?.toLowerCase().includes('could not find'))
      );
      
      if (isColumnError) {
        console.warn('⚠️ Some columns may not exist in database, retrying without optional favicon fields');
        
        // Retry with only essential fields
        const fallbackResult = await supabase
          .from("audit_projects")
          .select(
            `

              id,

              site_url,

              status,

              progress,

              last_audit_at,

              issues_count,

              score,

              created_at,

              updated_at,

              total_pages,

              total_links,

              total_images,

              total_meta_tags,

              technologies_found,

              cms_detected

            `
          )
          .eq("user_id", user.id)
          .order("created_at", {
            ascending: false,
          });
        
        // Add default values for missing favicon fields in fallback data
        data = fallbackResult.data?.map((project: any) => ({
          ...project,
          brand_data: null,
          scraping_data: null,
          meta_tags_data: null,
          social_meta_tags_data: null,
          detected_keys: null,
        })) || null;
        error = fallbackResult.error;
      }

      const queryEndTime = performance.now();

      const queryTime = queryEndTime - queryStartTime;

      if (error) {
        console.error(
          "❌ SupabaseContext: Query error after",
          queryTime.toFixed(2),
          "ms:",
          error
        );

        console.error("❌ Error details:", {
          message: error.message,

          details: error.details,

          hint: error.hint,

          code: error.code,
        });

        // Check for specific error types

        if (
          error.message?.includes('relation "audit_projects" does not exist') ||
          error.code === "PGRST301"
        ) {
          return {
            data: null,

            error: {
              message:
                "Database not set up. Please run the database migration script first.",

              code: "TABLE_NOT_EXISTS",
            },
          };
        }

        if (
          error.message?.includes("permission denied") ||
          !error.message ||
          error.message === "" ||
          Object.keys(error).length === 0
        ) {
          return {
            data: null,

            error: {
              message:
                "RLS policy issue detected. Please check your Supabase RLS policies.",

              code: "RLS_POLICY_ISSUE",
            },
          };
        }

        return {
          data: null,

          error,
        };
      }

      if (data && data.length > 0) {
        const dataSize = JSON.stringify(data).length;
      }

      // Add default values for fields if they don't exist

      const projectsWithDefaults =
        data?.map((project) => ({
          ...(project as any),

          brand_data: (project as any).brand_data || null,

          scraping_data: (project as any).scraping_data || null,

          meta_tags_data: (project as any).meta_tags_data || null,

          social_meta_tags_data: (project as any).social_meta_tags_data || null,

          detected_keys: (project as any).detected_keys || null,
        })) || [];

      return {
        data: projectsWithDefaults as AuditProject[],

        error: null,
      };
    } catch (error) {
      const queryEndTime = performance.now();

      const queryTime = queryEndTime - queryStartTime;

      console.error(
        "❌ SupabaseContext: Unexpected error after",
        queryTime.toFixed(2),
        "ms:",
        error
      );

      return {
        data: null,

        error,
      };
    }
  };

  const updateAuditProject = async (
    user: User | null,
    id: string,
    updates: Partial<AuditProjectWithUserId>,
    retryCount = 0
  ) => {
    if (!user) {
      return {
        data: null,

        error: {
          message: "No user logged in",
        },
      };
    }

    const maxRetries = 3;

    const retryDelay = 1000 * Math.pow(2, retryCount); // Exponential backoff

    try {
      const {
        data,

        error,
      } = await supabase
        .from("audit_projects")
        .update(updates)
        .eq("id", id)
        .eq("user_id", user.id)
        .select()
        .single();

      if (error) {
        console.error("Error updating audit project:", error);

        console.error("Error details:", JSON.stringify(error, null, 2));

        return {
          data: null,

          error,
        };
      }

      return {
        data: data as AuditProjectWithUserId,

        error: null,
      };
    } catch (error) {
      console.error("Unexpected error updating audit project:", error);

      console.error(
        "Unexpected error details:",
        JSON.stringify(error, null, 2)
      );

      // Check if it's a network error and retry

      if (
        error instanceof Error &&
        (error.message.includes("Failed to fetch") ||
          error.message.includes("NetworkError") ||
          error.message.includes("fetch")) &&
        retryCount < maxRetries
      ) {
        await new Promise((resolve) => setTimeout(resolve, retryDelay));

        return updateAuditProject(user, id, updates, retryCount + 1);
      }

      return {
        data: null,

        error:
          error instanceof Error
            ? error
            : {
              message: "Unknown error occurred",
            },
      };
    }
  };

  const deleteAuditProject = async (user: User | null, id: string) => {
    if (!user) {
      return {
        error: {
          message: "No user logged in",
        },
      };
    }

    try {
      const { error } = await supabase
        .from("audit_projects")
        .delete()
        .eq("id", id)
        .eq("user_id", user.id);

      if (error) {
        console.error("Error deleting audit project:", error);

        return {
          error,
        };
      }

      return {
        error: null,
      };
    } catch (error) {
      console.error("Unexpected error deleting audit project:", error);

      return {
        error,
      };
    }
  };

export {
