                },
              };
            }

            hasError = true;
            lastError = error;
            // Continue with next batch even if one fails
          } else if (data) {
            allResults.push(...data);
            console.log(`✅ Successfully inserted batch ${i / batchSize + 1} with ${batch.length} images`);
          }
        } catch (batchError) {
