// Utility function to get plan name from database based on plan type
const getPlanNameFromDB = async (planType: PlanType): Promise<string> => {
  try {
    const {
      data: plan,
      error
    } = await supabase.from('plans').select('name').eq('plan_type', planType).eq('is_active', true).single();
    if (error || !plan) {
      console.warn(`No plan found for type ${planType}, using fallback name`);
      return `${planType} Plan`; // Fallback to plan type + "Plan"
    }
    return plan.name;
  } catch (err) {
    console.error(`Error fetching plan name for ${planType}:`, err);
    return `${planType} Plan`; // Fallback to plan type + "Plan"
  }
};
export function useUserPlan(): UseUserPlanResult {
  const [planInfo, setPlanInfo] = useState<UserPlanInfo | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [lastExpiryCheck, setLastExpiryCheck] = useState<number>(0);
  const [isCheckingExpiry, setIsCheckingExpiry] = useState(false);

  // Function to check plan expiry with debouncing
  const checkPlanExpiry = async () => {
    const now = Date.now();
    const DEBOUNCE_TIME = 10 * 60 * 1000; // 10 minutes (increased from 5)
    
    // Prevent concurrent expiry checks
    if (isCheckingExpiry) {
      return;
    }
    
    // Only check if enough time has passed since last check
    if (now - lastExpiryCheck < DEBOUNCE_TIME) {
      return;
    }
    
    // Skip expiry check if user is on Starter plan (no expiry)
    if (planInfo?.plan_type === 'Starter') {
      return;
    }
    
    try {
      // Get current session for authentication
      const {
        data: {
          session
        }
      } = await supabase.auth.getSession();
      const token = session?.access_token;
      if (!token) {
        console.warn('No session token available for plan expiry check');
        return;
      }
      
    setLastExpiryCheck(now);
    setIsCheckingExpiry(true);
    
    // Add timeout to prevent hanging requests
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000); // 5 second timeout
      
      const response = await fetch('/api/check-plan-expiry', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        signal: controller.signal
      });
      
      clearTimeout(timeoutId);
      
      if (response.ok) {
        const data = await response.json();
        if (data.downgraded) {
          // Trigger a refresh of plan data
          setTimeout(() => {
            fetchUserPlan();
          }, 1000);
        }
      } else {
        console.warn('Plan expiry check failed:', response.status);
      }
    } catch (error) {
      // Handle AbortError specifically (timeout) - don't log as error
      if (error instanceof Error && error.name === 'AbortError') {
        console.warn('Plan expiry check timed out - this is normal for slow connections');
        return;
      }
      console.error('Error checking plan expiry:', error);
      // Don't throw error - this is a background check
    } finally {
      setIsCheckingExpiry(false);
    }
  };
  const fetchUserPlan = async () => {
    try {
      setLoading(true);
      setError(null);

      // Get current user
      const {
        data: {
          user
        },
        error: userError
      } = await supabase.auth.getUser();
      if (userError || !user) {
        // Handle authentication errors
        const wasLoggedOut = await handleAuthError(userError, 'useUserPlan');
        if (wasLoggedOut) {
          return;
        }
        throw new Error('User not authenticated');
      }

      // Check plan expiry first (with debouncing) - non-blocking
      checkPlanExpiry().catch(error => {
        console.warn('Plan expiry check failed (non-blocking):', error);
      });

      // Get user's plan data from user table (including credits)
      const {
        data: userData,
        error: userDataError
      } = await supabase.from('users').select('plan_type, plan_id, max_projects, can_use_features, plan_expires_at, billing_cycle, image_scan_credits').eq('id', user.id).single();
      let userPlan: UserPlanInfo | null = null;
      if (userDataError || !userData || !userData.plan_type) {
        console.warn('No plan_type found in user table, using fallback plan');
        // Use a fallback plan if no plan_type is set
        const fallbackPlanName = await getPlanNameFromDB('Starter');
        userPlan = {
          plan_type: 'Starter' as PlanType,
          plan_id: 'fallback-starter',
          plan_name: fallbackPlanName,
          can_use_features: ['basic_audit'],
          max_projects: 1,
          current_projects: 0,
          image_scan_credits: 0
        };
      } else {
        // Always fetch fresh data from plans table to get latest features and limits
        // This ensures we get the most up-to-date plan configuration
        let planData, planError;
        
        // Try to get by plan_id first if available, otherwise by plan_type
        if (userData.plan_id) {
          const result = await supabase.from('plans').select('id, name, plan_type, can_use_features, max_projects').eq('id', userData.plan_id).eq('is_active', true).single();
          planData = result.data;
          planError = result.error;
        }
        
        // If plan_id query failed or no plan_id, try by plan_type
        if (planError || !planData) {
          const result = await supabase.from('plans').select('id, name, plan_type, can_use_features, max_projects').eq('plan_type', userData.plan_type).eq('is_active', true).order('created_at', { ascending: true }).limit(1).single();
          planData = result.data;
          planError = result.error;
        }
        
        if (planError || !planData) {
          console.warn(`No plan found for type ${userData.plan_type}, using fallback plan`);
          console.error('Plan query error:', planError);
          const fallbackPlanName = await getPlanNameFromDB(userData.plan_type as PlanType);
          userPlan = {
            plan_type: userData.plan_type as PlanType,
            plan_id: 'fallback-' + userData.plan_type.toLowerCase(),
            plan_name: fallbackPlanName,
            can_use_features: ['basic_audit'],
            max_projects: 1,
            current_projects: 0,
            billing_cycle: userData.billing_cycle,
            plan_expires_at: userData.plan_expires_at,
            image_scan_credits: userData.image_scan_credits || 0
          };
        } else {
          userPlan = {
            plan_type: planData.plan_type,
            plan_id: planData.id,
            plan_name: planData.name,
            // Always use fresh data from plans table
            can_use_features: planData.can_use_features || [],
            max_projects: planData.max_projects || 1,
            current_projects: 0,
            billing_cycle: userData.billing_cycle,
            plan_expires_at: userData.plan_expires_at,
            image_scan_credits: userData.image_scan_credits || 0
          };
        }
      }

      // Get current project count
      const {
        data: projects,
        error: projectError
      } = await supabase.from('audit_projects').select('id').eq('user_id', user.id);
      if (!projectError && projects) {
        userPlan.current_projects = projects.length;
      }
      
      setPlanInfo(userPlan);
    } catch (err) {
      console.error('Error fetching user plan:', err);

      // Handle authentication errors
      const wasLoggedOut = await handleAuthError(err, 'useUserPlan catch block');
      if (wasLoggedOut) {
        return;
      }

      // If there's an error, provide a fallback plan instead of null
      const fallbackPlanName = await getPlanNameFromDB('Starter');
      const fallbackPlan: UserPlanInfo = {
        plan_type: 'Starter' as PlanType,
        plan_id: 'fallback-starter',
        plan_name: fallbackPlanName,
        can_use_features: ['basic_audit'],
        max_projects: 1,
        current_projects: 0,
        image_scan_credits: 0
      };
      setError(err instanceof Error ? err.message : 'Failed to fetch plan information');
      setPlanInfo(fallbackPlan); // Use fallback instead of null
    } finally {
      setLoading(false);
    }
  };
  const hasFeature = useCallback((featureId: string): boolean => {
    return planInfo?.can_use_features.includes(featureId) || false;
  }, [planInfo?.can_use_features]);
  const canCreateProject = (): boolean => {
    if (!planInfo) return false;
    return planInfo.max_projects === -1 || planInfo.current_projects < planInfo.max_projects;
  };
  const refreshPlan = useCallback(async () => {
    await fetchUserPlan();
  }, []);
  useEffect(() => {
    fetchUserPlan();
  }, []);

  // Add a refresh mechanism that can be triggered externally
  useEffect(() => {
    let lastFocusTime = 0;
    const FOCUS_DEBOUNCE = 30 * 1000; // 30 seconds
    
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'plan_updated' && e.newValue) {
        fetchUserPlan();
        localStorage.removeItem('plan_updated');
      }
    };
    const handleCustomEvent = () => {
      fetchUserPlan();
    };

    // Debounced focus handler to prevent excessive calls
    const handleFocus = () => {
      const now = Date.now();
      if (now - lastFocusTime > FOCUS_DEBOUNCE) {
        lastFocusTime = now;
        fetchUserPlan();
      }
    };
    
    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('planUpdated', handleCustomEvent);
    window.addEventListener('focus', handleFocus);
    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('planUpdated', handleCustomEvent);
      window.removeEventListener('focus', handleFocus);
    };
  }, []);
  return {
    planInfo,
    loading,
    error,
    hasFeature,
    canCreateProject,
    refreshPlan
  };
}

/**
 * Screenshot API Client
 * 
 * A production-ready TypeScript client for making authenticated requests to the Screenshot API.
 * 
 * ## Authentication Flow
 * 
 * This client implements API key authentication that aligns with the server-side implementation
 * in `/api/screenshot/route.ts`:
 * 
 * 1. **Client** → Sends request with `X-API-Key` header (default)
 * 2. **Server** (`/api/screenshot`) → Validates key matches `SCREENSHOT_API_KEY` env var
 * 3. **Server** → Forwards to external screenshot service with its own API key
 * 4. **Response** → Returns screenshot data to client
 * 
 * ## Security
 * 
 * - API keys are sent via headers (not query params) by default
 * - Server validates keys before processing any request
 * - Returns 401 for missing/invalid keys with detailed error messages
 * - Supports three authentication methods: header (default), bearer, query
 * 
 * ## Features
 * 
 * - ✅ Automatic retry with exponential backoff
 * - ✅ Configurable timeout (default: 5 minutes)
 * - ✅ Comprehensive error handling
 * - ✅ TypeScript type safety
 * - ✅ Detailed logging in development mode
 * - ✅ Multiple authentication methods
 * 
 * ## Usage
 * 
 * ```typescript
 * import { apiClient } from '@/lib/api-client/api-client'
 * 
 * // Take a screenshot
 * const result = await apiClient.takeScreenshot('https://example.com', {
 *   delay: 3000,
 *   fullPage: true
 * })
 * 
 * // With database storage
 * const result = await apiClient.takeScreenshotWithPageId(
 *   'https://example.com',
 *   'page-id-123',
 *   { delay: 3000 }
 * )
 * ```
 * 
 * @see README.md for complete documentation
 * @see INTEGRATION_EXAMPLES.md for usage examples
 */

import type {
  ApiClientConfig,
  ApiError,
  ApiKeyLocation,
  ScreenshotRequest,
  ScreenshotResponse,
  ScreenshotsListResponse,
  ServerStatusResponse,
} from './types'

/**
 * API Client for Screenshot Service
 * 
 * Handles authentication, retries, timeouts, and error handling for all API requests.
 */
export class ApiClient {
  private baseURL: string
  private apiKey: string
  private timeout: number
  private retries: number
  private retryDelay: number

  constructor(config: ApiClientConfig) {
    this.baseURL = config.baseURL.replace(/\/$/, '') // Remove trailing slash
    this.apiKey = config.apiKey
    this.timeout = config.timeout || 300000 // 5 minutes default
    this.retries = config.retries || 3
    this.retryDelay = config.retryDelay || 1000 // 1 second default

    if (!this.apiKey) {
      console.warn('⚠️ API Client: No API key provided. Requests may fail.')
    }
  }

  /**
   * Create headers with API key authentication
   * 
   * Supports three authentication methods:
   * 
   * 1. **header** (default, recommended): Sends `X-API-Key: your-key`
   *    - Most secure and standard approach
   *    - Validated by `/api/screenshot/route.ts` lines 6-48
   * 
   * 2. **bearer**: Sends `Authorization: Bearer your-key`
   *    - OAuth-style authentication
   *    - Alternative if your server expects Bearer tokens
   * 
   * 3. **query**: Appends `?apiKey=your-key` to URL
   *    - Less secure (visible in logs, browser history)
   *    - Only use if header authentication is not possible
   * 
   * @param apiKeyLocation - Where to send the API key (default: 'header')
   * @returns Headers object with authentication and content-type
   */
  private createHeaders(apiKeyLocation: ApiKeyLocation = 'header'): HeadersInit {
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
      Accept: 'application/json',
    }

    switch (apiKeyLocation) {
      case 'header':
        headers['X-API-Key'] = this.apiKey
        break
      case 'bearer':
        headers['Authorization'] = `Bearer ${this.apiKey}`
        break
      // query parameter is handled in the request method
    }

    return headers
  }

  /**
   * Make an authenticated request with retry logic
   */
  private async request<T>(
    endpoint: string,
    options: RequestInit = {},
    apiKeyLocation: ApiKeyLocation = 'header'
  ): Promise<T> {
    const url = endpoint.startsWith('http') ? endpoint : `${this.baseURL}${endpoint}`
    
    // Handle query parameter API key location
    const finalUrl = apiKeyLocation === 'query' 
      ? `${url}${url.includes('?') ? '&' : '?'}apiKey=${encodeURIComponent(this.apiKey)}`
      : url

    const headers = this.createHeaders(apiKeyLocation === 'query' ? 'header' : apiKeyLocation)

    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), this.timeout)

    let lastError: ApiError | null = null

    for (let attempt = 0; attempt <= this.retries; attempt++) {
      try {
        const response = await fetch(finalUrl, {
          ...options,
          headers: {
            ...headers,
            ...options.headers,
          },
          signal: controller.signal,
        })

        clearTimeout(timeoutId)

        // Handle 401 Unauthorized
        if (response.status === 401) {
          // Parse error response BEFORE logging (response can only be read once)
          const errorData = await this.parseErrorResponse(response)
          
          const error: ApiError = {
            message: errorData?.error || errorData?.message || 'Unauthorized: Invalid or missing API key',
            code: errorData?.code || 'UNAUTHORIZED',
            status: 401,
            details: errorData?.details || errorData?.error || 'Please check your API key configuration. Make sure NEXT_PUBLIC_SCREENSHOT_API_KEY is set in your .env.local file and matches SCREENSHOT_API_KEY on the server.',
          }
          
          // Log detailed error information
          console.error('❌ API Client: Authentication failed', {
            message: error.message,
            code: error.code,
            status: error.status,
            details: error.details,
            hasApiKey: !!this.apiKey,
            apiKeyLength: this.apiKey?.length || 0,
            apiKeyPrefix: this.apiKey?.substring(0, 8) + '...' || 'N/A',
            baseURL: this.baseURL,
            endpoint: url,
            serverResponse: errorData,
          })
          
          throw error
        }

        // Handle other error status codes
        if (!response.ok) {
          const errorData = await this.parseErrorResponse(response)
          const error: ApiError = {
            message: errorData.message || `Request failed with status ${response.status}`,
            code: errorData.code || 'REQUEST_FAILED',
            status: response.status,
            details: errorData.details || errorData.error || response.statusText,
          }
          
          // Don't retry on client errors (4xx), except 429 (rate limit)
          if (response.status >= 400 && response.status < 500 && response.status !== 429) {
            throw error
          }
          
          // Retry on server errors (5xx) and rate limits (429)
          lastError = error
          if (attempt < this.retries) {
            const delay = this.retryDelay * Math.pow(2, attempt) // Exponential backoff
            console.warn(`⚠️ API Client: Request failed, retrying in ${delay}ms (attempt ${attempt + 1}/${this.retries})`)
            await this.sleep(delay)
            continue
          }
          throw error
        }

        // Parse successful response
        const data = await response.json()
        return data as T
      } catch (error: any) {
        clearTimeout(timeoutId)

        // Handle abort (timeout)
        if (error.name === 'AbortError' || controller.signal.aborted) {
          const timeoutError: ApiError = {
            message: 'Request timeout',
            code: 'TIMEOUT',
            status: 504,
            details: `Request exceeded ${this.timeout}ms timeout`,
            originalError: error,
          }
          throw timeoutError
        }

        // Handle network errors
        if (error instanceof TypeError && error.message.includes('fetch')) {
          lastError = {
            message: 'Network error',
            code: 'NETWORK_ERROR',
            status: 0,
            details: 'Failed to connect to the API server. Please check your connection.',
            originalError: error,
          }
          
          if (attempt < this.retries) {
            const delay = this.retryDelay * Math.pow(2, attempt)
            console.warn(`⚠️ API Client: Network error, retrying in ${delay}ms (attempt ${attempt + 1}/${this.retries})`)
            await this.sleep(delay)
            continue
          }
          throw lastError
        }

        // Re-throw API errors
        if (error.code) {
          throw error
        }

        // Unknown error
        lastError = {
          message: error.message || 'Unknown error occurred',
          code: 'UNKNOWN_ERROR',
          status: 0,
          details: 'An unexpected error occurred',
          originalError: error,
        }

        if (attempt < this.retries) {
          const delay = this.retryDelay * Math.pow(2, attempt)
          console.warn(`⚠️ API Client: Error occurred, retrying in ${delay}ms (attempt ${attempt + 1}/${this.retries})`)
          await this.sleep(delay)
          continue
        }

        throw lastError
      }
    }

    throw lastError || {
      message: 'Request failed after all retries',
      code: 'MAX_RETRIES_EXCEEDED',
      status: 0,
    }
  }

  /**
   * Parse error response from API
   */
  private async parseErrorResponse(response: Response): Promise<any> {
    try {
      // Clone the response so we can read it multiple times
      const clonedResponse = response.clone()
      const text = await clonedResponse.text()
      
      if (!text || text.trim() === '') {
        return { 
          message: response.statusText || 'Unknown error', 
          status: response.status,
          error: response.statusText || 'Unknown error'
        }
      }
      
      try {
        const parsed = JSON.parse(text)
        return parsed
      } catch (parseError) {
        // If JSON parsing fails, return the text as the message
        return { 
          message: text, 
          status: response.status,
          error: text,
          details: text
        }
      }
    } catch (error) {
      console.error('Error parsing error response:', error)
      return { 
        message: response.statusText || 'Unknown error', 
        status: response.status,
        error: response.statusText || 'Unknown error'
      }
    }
  }

  /**
   * Sleep utility for retry delays
   */
  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms))
  }

  /**
   * Take a screenshot of a URL
   * 
   * Sends a POST request to `/api/screenshot` with the URL and options.
   * The server validates the API key and forwards the request to the external screenshot service.
   * 
   * @param url - The URL to capture (must be a valid HTTP/HTTPS URL)
   * @param options - Screenshot options (delay, fullPage, viewport, etc.)
   * @param apiKeyLocation - Authentication method (default: 'header')
   * 
   * @returns Promise resolving to screenshot data with desktop/mobile URLs
   * 
   * @throws {ApiError} With code 'UNAUTHORIZED' if API key is invalid
   * @throws {ApiError} With code 'TIMEOUT' if request exceeds timeout
   * @throws {ApiError} With code 'NETWORK_ERROR' if connection fails
   * 
   * @example
   * ```typescript
   * const result = await apiClient.takeScreenshot('https://example.com', {
   *   delay: 3000,
   *   fullPage: true,
   *   viewport: { width: 1920, height: 1080 }
   * })
   * console.log('Screenshot:', result.desktopUrl)
   * ```
   */
  async takeScreenshot(
    url: string,
    options?: ScreenshotRequest['options'],
    apiKeyLocation: ApiKeyLocation = 'header'
  ): Promise<ScreenshotResponse> {
    const requestBody: ScreenshotRequest = {
      url,
      options: options || { delay: 3000 },
      priority: 1,
    }

    return this.request<ScreenshotResponse>(
      '/api/screenshot',
      {
        method: 'POST',
        body: JSON.stringify(requestBody),
      },
      apiKeyLocation
    )
  }

  /**
   * Take a screenshot with pageId (for database storage)
   * 
   * Same as `takeScreenshot()` but includes a `pageId` to save the screenshot
   * to the database. The server will update the `scraped_pages` table with the
   * screenshot URLs and metadata.
   * 
   * @param url - The URL to capture
   * @param pageId - Database ID of the page (from scraped_pages table)
   * @param options - Screenshot options
   * @param apiKeyLocation - Authentication method (default: 'header')
   * 
   * @returns Promise resolving to screenshot data
   * 
   * @example
   * ```typescript
   * // Capture and save to database
   * const result = await apiClient.takeScreenshotWithPageId(
   *   'https://example.com',
   *   'page-uuid-123',
   *   { delay: 3000, fullPage: true }
   * )
   * // Screenshot is now saved in database under page_image column
   * ```
   */
  async takeScreenshotWithPageId(
    url: string,
    pageId: string,
    options?: ScreenshotRequest['options'],
    apiKeyLocation: ApiKeyLocation = 'header'
  ): Promise<ScreenshotResponse> {
    const requestBody: ScreenshotRequest & { pageId: string } = {
      url,
      pageId,
      options: options || { delay: 3000 },
      priority: 1,
    }

    return this.request<ScreenshotResponse>(
      '/api/screenshot',
      {
        method: 'POST',
        body: JSON.stringify(requestBody),
      },
      apiKeyLocation
    )
  }

  /**
   * Get list of screenshots
   */
  async getScreenshots(
    params?: { page?: number; limit?: number },
    apiKeyLocation: ApiKeyLocation = 'header'
  ): Promise<ScreenshotsListResponse> {
    const queryParams = new URLSearchParams()
    if (params?.page) queryParams.append('page', params.page.toString())
    if (params?.limit) queryParams.append('limit', params.limit.toString())

    const endpoint = `/screenshots${queryParams.toString() ? `?${queryParams.toString()}` : ''}`
    
    return this.request<ScreenshotsListResponse>(
      endpoint,
      {
        method: 'GET',
      },
      apiKeyLocation
    )
  }

  /**
   * Get server status
   */
  async getStatus(apiKeyLocation: ApiKeyLocation = 'header'): Promise<ServerStatusResponse> {
    return this.request<ServerStatusResponse>(
      '/status',
      {
        method: 'GET',
      },
      apiKeyLocation
    )
  }
}

/**
 * Create a default API client instance
 * 
 * Automatically configures the client using environment variables:
 * 
 * - `NEXT_PUBLIC_SCREENSHOT_API_KEY` - API key for authentication (required)
 * - `NEXT_PUBLIC_SCREENSHOT_API_BASE_URL` - Base URL (defaults to current origin)
 * 
 * ## Setup
 * 
 * 1. Add to `.env.local`:
 *    ```env
 *    NEXT_PUBLIC_SCREENSHOT_API_KEY=your-secret-key
 *    SCREENSHOT_API_KEY=your-secret-key  # Must match client key
 *    ```
 * 
 * 2. Generate a secure key:
 *    ```bash
 *    node -e "console.log(require('crypto').randomBytes(32).toString('hex'))"
 *    ```
 * 
 * 3. Restart dev server:
 *    ```bash
 *    npm run dev
 *    ```
 * 
 * @returns Configured ApiClient instance ready to use
 * 
 * @example
 * ```typescript
 * import { createApiClient } from '@/lib/api-client/api-client'
 * 
 * const client = createApiClient()
 * const result = await client.takeScreenshot('https://example.com')
 * ```
 */
export function createApiClient(): ApiClient {
  const baseURL = process.env.NEXT_PUBLIC_SCREENSHOT_API_BASE_URL || 
                  process.env.NEXT_PUBLIC_API_BASE_URL || 
                  (typeof window !== 'undefined' ? window.location.origin : 'http://localhost:3000')
  
  const apiKey = process.env.NEXT_PUBLIC_SCREENSHOT_API_KEY || 
                 process.env.NEXT_PUBLIC_API_KEY || 
                 ''

  if (!apiKey) {
    console.warn('⚠️ API Client: NEXT_PUBLIC_SCREENSHOT_API_KEY not found in environment variables')
    console.warn('⚠️ API Client: Please add NEXT_PUBLIC_SCREENSHOT_API_KEY to your .env.local file')
  } else if (process.env.NODE_ENV === 'development') {
    console.log('✅ API Client: API key found', {
      hasApiKey: true,
      apiKeyLength: apiKey.length,
      apiKeyPrefix: apiKey.substring(0, 8) + '...',
      baseURL,
    })
  }

  return new ApiClient({
    baseURL,
    apiKey,
    timeout: 300000, // 5 minutes
    retries: 3,
    retryDelay: 1000, // 1 second
  })
}

/**
 * Default API client instance
 */
export const apiClient = createApiClient()

/**
 * React Hooks for Screenshot API
 * Custom hooks for easy integration with React components
 */

'use client'

import { useState, useCallback, useRef, useEffect } from 'react'
import { apiClient, createApiClient } from './api-client'
import type {
  ApiError,
  ApiKeyLocation,
  ScreenshotOptions,
  ScreenshotResponse,
  ScreenshotsListResponse,
  ServerStatusResponse,
} from './types'

interface UseScreenshotOptions {
  onSuccess?: (response: ScreenshotResponse) => void
  onError?: (error: ApiError) => void
  apiKeyLocation?: ApiKeyLocation
  customClient?: ReturnType<typeof createApiClient>
}

interface UseScreenshotReturn {
  takeScreenshot: (url: string, options?: ScreenshotOptions, pageId?: string) => Promise<ScreenshotResponse | null>
  isProcessing: boolean
  error: ApiError | null
  clearError: () => void
  lastResponse: ScreenshotResponse | null
}

/**
 * Hook for taking screenshots
 */
export function useScreenshot(options: UseScreenshotOptions = {}): UseScreenshotReturn {
  const { onSuccess, onError, apiKeyLocation = 'header', customClient } = options
  const client = customClient || apiClient
  const [isProcessing, setIsProcessing] = useState(false)
  const [error, setError] = useState<ApiError | null>(null)
  const [lastResponse, setLastResponse] = useState<ScreenshotResponse | null>(null)
  const abortControllerRef = useRef<AbortController | null>(null)

  const takeScreenshot = useCallback(
    async (
      url: string,
      screenshotOptions?: ScreenshotOptions,
      pageId?: string
    ): Promise<ScreenshotResponse | null> => {
      // Cancel previous request if any
      if (abortControllerRef.current) {
        abortControllerRef.current.abort()
      }

      setIsProcessing(true)
      setError(null)

      try {
        const response = pageId
          ? await client.takeScreenshotWithPageId(url, pageId, screenshotOptions, apiKeyLocation)
          : await client.takeScreenshot(url, screenshotOptions, apiKeyLocation)

        setLastResponse(response)
        onSuccess?.(response)
        return response
      } catch (err: any) {
        const apiError: ApiError = {
          message: err.message || 'Failed to take screenshot',
          code: err.code || 'UNKNOWN_ERROR',
          status: err.status || 0,
          details: err.details || err.message || 'An unknown error occurred',
          originalError: err.originalError || err,
        }

        // Log error details in development
        if (process.env.NODE_ENV === 'development') {
          console.error('⚠️ useScreenshot hook error:', {
            message: apiError.message,
            code: apiError.code,
            status: apiError.status,
            details: apiError.details,
            fullError: err,
          })
        }

        setError(apiError)
        onError?.(apiError)
        return null
      } finally {
        setIsProcessing(false)
      }
    },
    [client, apiKeyLocation, onSuccess, onError]
  )

  const clearError = useCallback(() => {
    setError(null)
  }, [])

  return {
    takeScreenshot,
    isProcessing,
    error,
    clearError,
    lastResponse,
  }
}

interface UseScreenshotsListOptions {
  onSuccess?: (response: ScreenshotsListResponse) => void
  onError?: (error: ApiError) => void
  apiKeyLocation?: ApiKeyLocation
